-- ESQUEMA-BASE do iUser (sem dados). GERADO por scripts/staging/export-baseline.py a partir da produção (só leitura).
-- Não edite à mão: rode o script de novo. Cada bloco "-- @@ fase|descrição" é um comando; o aplicador repete os que falham por ordem de dependência.

-- @@ 10|extension ltree
CREATE EXTENSION IF NOT EXISTS "ltree" WITH SCHEMA "public";

-- @@ 10|extension pg_trgm
CREATE EXTENSION IF NOT EXISTS "pg_trgm" WITH SCHEMA "public";

-- @@ 10|extension pgcrypto
CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";

-- @@ 10|extension postgis
CREATE EXTENSION IF NOT EXISTS "postgis" WITH SCHEMA "public";

-- @@ 10|extension unaccent
CREATE EXTENSION IF NOT EXISTS "unaccent" WITH SCHEMA "public";

-- @@ 10|extension uuid-ossp
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "public";

-- @@ 20|enum appointment_direction
CREATE TYPE public."appointment_direction" AS ENUM ('outgoing', 'incoming', 'other');

-- @@ 20|enum appointment_status
CREATE TYPE public."appointment_status" AS ENUM ('confirmed', 'pending', 'cancelled', 'completed');

-- @@ 20|enum service_type
CREATE TYPE public."service_type" AS ENUM ('restaurant', 'barbershop', 'hotel', 'service');

