-- @@ 50|function _actor_status(uuid)
CREATE OR REPLACE FUNCTION public._actor_status(p_user uuid)
 RETURNS TABLE(status_id uuid, slug text, name text, level integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_email text;
    v_status uuid;
BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = p_user;
    SELECT pr.status_id INTO v_status FROM public.profiles pr WHERE pr.id = p_user;
    IF v_status IS NULL THEN
        SELECT s.id INTO v_status FROM public.user_statuses s
        WHERE s.slug = CASE WHEN v_email = 'ncastelano@gmail.com' THEN 'administrador' ELSE 'usuario' END;
    END IF;
    RETURN QUERY
        SELECT s.id, s.slug, s.name, s.level FROM public.user_statuses s
        WHERE s.id = v_status AND s.is_active;
END;
$function$;

-- @@ 50|function _address_area(text)
CREATE OR REPLACE FUNCTION public._address_area(p_address text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
    s text;
    parts text[];
    seg text;
    picked text[] := '{}';
    i integer;
BEGIN
    IF p_address IS NULL OR btrim(p_address) = '' THEN RETURN NULL; END IF;
    s := regexp_replace(p_address, '^[^,]*[—–]\s*', '');
    parts := string_to_array(s, ',');
    FOR i IN 2 .. COALESCE(array_length(parts, 1), 0) LOOP
        seg := btrim(regexp_replace(parts[i], '\s+[-–]\s+.*$', ''));
        CONTINUE WHEN seg = '' OR seg ~ '^[0-9]' OR seg ~* '^(brasil|brazil|regi[aã]o)';
        picked := picked || seg;
        EXIT WHEN array_length(picked, 1) >= 2;
    END LOOP;
    IF array_length(picked, 1) IS NULL THEN RETURN NULL; END IF;
    RETURN array_to_string(picked, ', ');
END;
$function$;

-- @@ 50|function _advance_delivery_search_v2(uuid)
CREATE OR REPLACE FUNCTION public._advance_delivery_search_v2(p_dispatch uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    d public.order_delivery_dispatches;
    cfg public.delivery_dispatch_settings;
    a public.delivery_reajust_authorizations;
    dec jsonb;
    v_action text;
    v_ride_status text;
    v_price numeric;
    v_radius numeric;
    v_req numeric;
    v_auto boolean;
    v_by uuid;
    v_round uuid;
    v_expires timestamptz;
BEGIN
    PERFORM set_config('app.delivery_v2_engine', '1', true);
    PERFORM set_config('app.delivery_actor', 'system', true);
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 OR d.status <> 'searching' THEN RETURN 'skip'; END IF;
    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    SELECT status INTO v_ride_status FROM public.ride_requests WHERE id = d.ride_request_id;
    IF v_ride_status IS DISTINCT FROM 'pending' THEN RETURN 'skip'; END IF;      -- aceita/cancelada: o gatilho de sincronização cuida

    IF now() >= d.created_at + make_interval(mins => cfg.max_search_minutes) THEN
        UPDATE public.delivery_reajust_authorizations SET status = 'expired', decided_at = now() WHERE dispatch_id = d.id AND status = 'pending' AND now() >= expires_at;
        PERFORM public._v2_end_search(d.id, 'timeout');
        RETURN 'ended:timeout';
    END IF;

    IF d.phase = 'AGUARDANDO_AUTORIZACAO_REAJUSTE' THEN
        SELECT * INTO a FROM public.delivery_reajust_authorizations WHERE dispatch_id = d.id AND status = 'pending';
        IF FOUND THEN
            IF now() >= a.expires_at THEN
                UPDATE public.delivery_reajust_authorizations SET status = 'expired', decided_at = now() WHERE id = a.id;
                PERFORM public._v2_end_search(d.id, 'authorization_expired');
                RETURN 'ended:authorization_expired';
            END IF;
            RETURN 'waiting';
        END IF;
        -- sem pedido pendente (estado inconsistente): volta a procurar sem inventar autorização
        UPDATE public.order_delivery_dispatches SET phase = 'PROCURANDO_ENTREGADOR', offer_expires_at = now(), updated_at = now() WHERE id = d.id;
        SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = d.id;
    END IF;

    IF d.offer_expires_at IS NOT NULL AND now() < d.offer_expires_at THEN RETURN 'open'; END IF;

    IF d.round >= cfg.max_rounds THEN
        PERFORM public._v2_end_search(d.id, 'max_rounds');
        RETURN 'ended:max_rounds';
    END IF;

    dec := public._v2_decide(d, cfg);
    v_action := dec->>'action';

    IF v_action = 'end' THEN
        PERFORM public._v2_end_search(d.id, 'exhausted');
        RETURN 'ended:exhausted';
    END IF;

    IF v_action = 'ask' THEN
        -- o próximo valor passa do limite automático: PARA e pergunta. O cliente autoriza um NOVO LIMITE, não paga nem fixa o frete.
        v_req := round(LEAST(cfg.max_freight, GREATEST(public._v2_projected_limit(d.final_freight, d.price_adjustments, cfg), (dec->>'next_price')::numeric)), 2);
        v_expires := now() + make_interval(mins => cfg.customer_authorization_timeout_minutes);
        SELECT id INTO v_round FROM public.order_delivery_rounds WHERE dispatch_id = d.id AND round = d.round;
        INSERT INTO public.delivery_reajust_authorizations (dispatch_id, round_id, customer_id, estimated_freight, current_offer, previous_limit, requested_limit, expires_at)
        VALUES (d.id, v_round, d.customer_id, COALESCE(d.estimated_freight, d.original_freight), d.final_freight, d.price_limit, v_req, v_expires);
        -- a oferta vigente (já autorizada) continua aceitável até o prazo da resposta; nada novo é oferecido
        UPDATE public.order_delivery_dispatches SET phase = 'AGUARDANDO_AUTORIZACAO_REAJUSTE', offer_expires_at = v_expires, updated_at = now() WHERE id = d.id;
        INSERT INTO public.order_delivery_events (dispatch_id, kind, round_id, data)
        VALUES (d.id, 'reajust_requested', v_round, jsonb_build_object('previous_limit', d.price_limit, 'requested_limit', v_req, 'current_offer', d.final_freight));
        RETURN 'asked';
    END IF;

    -- nova rodada: radius | price | radius_price | hold
    v_price := CASE WHEN v_action IN ('price', 'radius_price') THEN (dec->>'next_price')::numeric ELSE d.final_freight END;
    v_radius := CASE WHEN v_action IN ('radius', 'radius_price') THEN (dec->>'new_radius')::numeric ELSE d.radius_km END;
    v_auto := v_price <= public._v2_auto_limit(COALESCE(d.estimated_freight, d.original_freight), cfg);
    v_expires := now() + make_interval(secs => cfg.offer_duration_seconds);
    IF NOT v_auto THEN
        SELECT decided_by INTO v_by FROM public.delivery_reajust_authorizations WHERE dispatch_id = d.id AND status = 'authorized' ORDER BY decided_at DESC LIMIT 1;
    END IF;

    UPDATE public.order_delivery_rounds SET status = 'expired', ended_at = now(), end_reason = 'no_taker' WHERE dispatch_id = d.id AND round = d.round AND ended_at IS NULL;
    INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status,
                                              authorized_at, authorized_by, strategy, action, automatic, offer_expires_at, price_limit)
    VALUES (d.id, d.round + 1, CASE v_action WHEN 'hold' THEN 'hold' WHEN 'radius' THEN 'radius_only' ELSE 'increase' END,
            d.original_freight, v_price - d.original_freight, v_price, 0, v_price, v_radius, 'authorized',
            now(), CASE WHEN v_auto THEN NULL ELSE v_by END, cfg.search_strategy, v_action, v_auto, v_expires, d.price_limit)
    RETURNING id INTO v_round;

    UPDATE public.order_delivery_dispatches
       SET round = d.round + 1, radius_km = v_radius, final_freight = v_price,
           price_adjustments = d.price_adjustments + CASE WHEN v_action IN ('price', 'radius_price') THEN 1 ELSE 0 END,
           last_price_change_at = CASE WHEN v_action IN ('price', 'radius_price') THEN now() ELSE d.last_price_change_at END,
           round_started_at = now(), offer_expires_at = v_expires, updated_at = now()
     WHERE id = d.id;

    INSERT INTO public.order_delivery_events (dispatch_id, kind, old_radius, new_radius, round_id, data, processed_at)
    VALUES (d.id, 'round_started', d.radius_km, v_radius, v_round,
            jsonb_build_object('action', v_action, 'round', d.round + 1, 'price', v_price, 'price_changed', v_price <> d.final_freight, 'radius_changed', v_radius <> d.radius_km),
            CASE WHEN v_action = 'hold' THEN now() END);       -- "manter" só audita; as demais entram na fila de avisos aos motoristas
    RETURN 'round:' || v_action;
END;
$function$;

-- @@ 50|function _apply_campaign_discount(text,uuid,uuid,text,jsonb)
CREATE OR REPLACE FUNCTION public._apply_campaign_discount(p_code text, p_store uuid, p_order uuid, p_via text, p_items jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    red public.store_campaign_redemptions;
    camp public.store_campaigns;
    v_eligible numeric;
    v_discount numeric;
    v_updated integer;
BEGIN
    SELECT * INTO red FROM public.store_campaign_redemptions WHERE code = upper(btrim(p_code)) FOR UPDATE;
    IF NOT FOUND OR red.status <> 'available' THEN RAISE EXCEPTION 'Código inválido ou já usado'; END IF;
    SELECT * INTO camp FROM public.store_campaigns WHERE id = red.campaign_id;
    IF NOT FOUND OR NOT camp.active OR (camp.ends_at IS NOT NULL AND camp.ends_at <= now()) THEN RAISE EXCEPTION 'Código inválido ou já usado'; END IF;
    IF camp.store_id <> p_store THEN RAISE EXCEPTION 'Esse código não é dessa loja'; END IF;

    SELECT COALESCE(sum((i->>'total_price')::numeric), 0) INTO v_eligible
      FROM jsonb_array_elements(p_items) i
     WHERE (i->>'product_id')::uuid = ANY (camp.product_ids);
    v_discount := CASE camp.discount_type
        WHEN 'full' THEN v_eligible
        WHEN 'percent' THEN v_eligible * (COALESCE(camp.discount_value, 0) / 100)
        ELSE LEAST(COALESCE(camp.discount_value, 0), v_eligible)
    END;

    UPDATE public.store_campaign_redemptions
       SET status = 'redeemed', redeemed_at = now(), redeemed_via = p_via, order_id = p_order
     WHERE id = red.id AND status = 'available';
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated = 0 THEN RAISE EXCEPTION 'Código inválido ou já usado'; END IF;
    RETURN round(v_discount, 2);
END;
$function$;

-- @@ 50|function _avatar_border_block_reason(uuid,uuid)
CREATE OR REPLACE FUNCTION public._avatar_border_block_reason(p_user uuid, p_border uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_b public.avatar_borders%ROWTYPE;
    v_req public.network_levels%ROWTYPE;
    v_my_order integer;
    v_in_hierarchy boolean;
BEGIN
    SELECT * INTO v_b FROM public.avatar_borders WHERE id = p_border AND is_active;
    IF NOT FOUND THEN RETURN 'Essa borda não está disponível'; END IF;
    IF v_b.grant_mode = 'admin_only' THEN RETURN 'Só o administrador concede'; END IF;
    IF v_b.available_from IS NOT NULL AND now() < v_b.available_from THEN
        RETURN 'Abre em ' || to_char(v_b.available_from AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY');
    END IF;
    IF v_b.available_until IS NOT NULL AND now() > v_b.available_until THEN
        RETURN 'Prazo encerrado em ' || to_char(v_b.available_until AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY');
    END IF;

    -- Pré-pago: exigido quando a borda diz que exige, e SEMPRE nas bordas que entram com o Pré-pago (auto_prepaid).
    -- Quem é da hierarquia e a borda vale pra toda a hierarquia também pode, com plano ou sem.
    IF (v_b.requires_prepaid OR v_b.grant_mode = 'auto_prepaid') AND NOT public._has_active_prepaid(p_user) THEN
        SELECT EXISTS (SELECT 1 FROM public.profiles p JOIN public.user_statuses s ON s.id = p.status_id AND s.is_active WHERE p.id = p_user)
          INTO v_in_hierarchy;
        IF NOT (v_b.for_hierarchy AND v_in_hierarchy) THEN
            RETURN 'Pra quem usa o plano Pré-pago';
        END IF;
    END IF;

    IF v_b.required_level_id IS NOT NULL THEN
        SELECT * INTO v_req FROM public.network_levels WHERE id = v_b.required_level_id;
        SELECT l.level_order INTO v_my_order FROM public.network_levels l WHERE l.id = public._effective_level_id(p_user);
        IF COALESCE(v_my_order, 0) < v_req.level_order THEN
            RETURN 'Chegue ao nível ' || v_req.name || ' da graduação pra resgatar';
        END IF;
    END IF;
    RETURN NULL;
END; $function$;

-- @@ 50|function _award_points(uuid,text,text,timestamp with time zone,boolean)
CREATE OR REPLACE FUNCTION public._award_points(p_profile uuid, p_action text, p_ref text, p_at timestamp with time zone DEFAULT now(), p_enforce_limit boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.point_rules; v_today int; v_new int;
BEGIN
    IF p_profile IS NULL THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_profile) THEN RETURN; END IF;
    SELECT * INTO r FROM public.point_rules WHERE action = p_action;
    IF NOT FOUND OR NOT r.is_active OR r.points <= 0 THEN RETURN; END IF;

    IF p_enforce_limit AND r.daily_limit IS NOT NULL THEN
        SELECT count(*) INTO v_today FROM public.profile_points_events
         WHERE profile_id = p_profile AND action = p_action AND created_at >= date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo';
        IF v_today >= r.daily_limit THEN RETURN; END IF;
    END IF;

    INSERT INTO public.profile_points_events (profile_id, action, points, ref, created_at) VALUES (p_profile, p_action, r.points, p_ref, p_at)
    ON CONFLICT (profile_id, action, ref) DO NOTHING;
    GET DIAGNOSTICS v_new = ROW_COUNT;
    IF v_new > 0 THEN
        INSERT INTO public.profile_points (profile_id, total) VALUES (p_profile, r.points)
        ON CONFLICT (profile_id) DO UPDATE SET total = public.profile_points.total + EXCLUDED.total, updated_at = now();
    END IF;
END; $function$;

-- @@ 50|function _build_vehicle_slug(text,text,text,uuid,uuid)
CREATE OR REPLACE FUNCTION public._build_vehicle_slug(p_model text, p_plate text, p_kind text, p_driver uuid, p_vehicle uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_base text; v_try text; n int := 1; v_prof text;
BEGIN
    v_base := public._slugify(coalesce(p_model, '') || ' ' || coalesce(p_plate, ''));
    IF v_base IS NULL OR v_base = '' THEN
        SELECT "profileSlug" INTO v_prof FROM public.profiles WHERE id = p_driver;
        v_base := public._slugify(coalesce(v_prof, 'motorista') || ' ' || coalesce(p_kind, 'veiculo'));
    END IF;
    IF v_base = '' THEN v_base := 'veiculo'; END IF;
    v_try := v_base;
    WHILE public._slug_taken(v_try, p_vehicle) LOOP
        n := n + 1;
        v_try := left(v_base, 56) || '-' || n;
    END LOOP;
    RETURN v_try;
END; $function$;

-- @@ 50|function _can_access_conversation(uuid,uuid)
CREATE OR REPLACE FUNCTION public._can_access_conversation(p_conv uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p_user IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.conversations c
        WHERE c.id = p_conv
          AND (
              (c.kind = 'direct' AND (c.customer_id = p_user
                   OR c.owner_profile_id = p_user
                   OR EXISTS (SELECT 1 FROM public.stores s WHERE s.id = c.store_id AND s.owner_id = p_user)))
              OR (c.kind = 'group' AND EXISTS (
                   SELECT 1 FROM public.conversation_members cm
                   WHERE cm.conversation_id = c.id AND cm.profile_id = p_user AND cm.status = 'active'))
          )
    );
$function$;

-- @@ 50|function _coarse_address(text)
CREATE OR REPLACE FUNCTION public._coarse_address(a text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
    WITH parts AS (
        SELECT btrim(x) AS p, ord
        FROM unnest(string_to_array(coalesce(a, ''), ',')) WITH ORDINALITY AS t(x, ord)
        WHERE btrim(x) <> '' AND btrim(x) !~ '^[0-9]+([-[:space:]][0-9]+)?$'
    ), arr AS (SELECT array_agg(p ORDER BY ord) AS v FROM parts)
    SELECT CASE
        WHEN v IS NULL THEN NULL
        WHEN array_length(v, 1) >= 3 THEN v[2]
        ELSE NULLIF(btrim(regexp_replace(regexp_replace(v[1], '[0-9]+', '', 'g'), '[[:space:]]+', ' ', 'g')), '')
    END FROM arr
$function$;

-- @@ 50|function _community_close_rounds(uuid)
CREATE OR REPLACE FUNCTION public._community_close_rounds(p_community uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_today date := public._community_today(p_community); d record; w record; v_current text;
BEGIN
    FOR d IN
        SELECT DISTINCT round_day FROM public.community_photo_candidates
        WHERE community_id = p_community AND outcome IS NULL AND round_day < v_today
        ORDER BY round_day
    LOOP
        SELECT cand.id, cand.image_url, count(v.voter_id) AS votes INTO w
        FROM public.community_photo_candidates cand
        LEFT JOIN public.community_photo_votes v ON v.candidate_id = cand.id
        WHERE cand.community_id = p_community AND cand.round_day = d.round_day
        GROUP BY cand.id, cand.image_url, cand.created_at
        ORDER BY count(v.voter_id) DESC, cand.created_at ASC
        LIMIT 1;

        SELECT image_url INTO v_current FROM public.communities WHERE id = p_community;

        UPDATE public.community_photo_candidates SET outcome = 'lost'
        WHERE community_id = p_community AND round_day = d.round_day AND outcome IS NULL;
        IF w.id IS NOT NULL AND (w.votes > 0 OR v_current IS NULL) THEN
            UPDATE public.community_photo_candidates SET outcome = 'winner' WHERE id = w.id;
            UPDATE public.communities SET image_url = w.image_url WHERE id = p_community;
        END IF;
    END LOOP;
END; $function$;

-- @@ 50|function _community_is_member(uuid,uuid)
CREATE OR REPLACE FUNCTION public._community_is_member(p_community uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p_user IS NOT NULL AND (
        EXISTS (SELECT 1 FROM public.community_members m WHERE m.community_id = p_community AND m.profile_id = p_user)
        OR EXISTS (SELECT 1 FROM public.communities c WHERE c.id = p_community AND c.creator_id = p_user)
    );
$function$;

-- @@ 50|function _community_today(uuid)
CREATE OR REPLACE FUNCTION public._community_today(p_community uuid)
 RETURNS date
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT (now() AT TIME ZONE COALESCE((SELECT tz FROM public.communities WHERE id = p_community), 'America/Sao_Paulo'))::date;
$function$;

-- @@ 50|function _compute_delivery_estimate(integer)
CREATE OR REPLACE FUNCTION public._compute_delivery_estimate(p_distance_m integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    t record;
    c record;
    v_base integer; v_extra integer; v_ppk integer; v_base_m integer;
    v_extra_m integer; v_per_km integer; v_gross integer;
    v_step integer; v_rounded integer; v_min integer; v_max integer; v_after_min integer; v_final integer;
BEGIN
    IF p_distance_m IS NULL OR p_distance_m < 0 THEN RAISE EXCEPTION 'Distância inválida'; END IF;
    SELECT base_fee, extra_fee_objeto, price_per_km, base_distance_km INTO t FROM public.platform_tariffs WHERE vehicle_kind = 'moto';
    IF NOT FOUND THEN RAISE EXCEPTION 'Tarifa da plataforma indisponível'; END IF;
    SELECT min_freight, max_freight, freight_rounding_step, freight_rounding_mode INTO c FROM public.delivery_dispatch_settings WHERE id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Configuração da entrega indisponível'; END IF;

    v_base   := round(t.base_fee * 100)::integer;
    v_extra  := round(t.extra_fee_objeto * 100)::integer;
    v_ppk    := round(t.price_per_km * 100)::integer;
    v_base_m := round(t.base_distance_km * 1000)::integer;
    v_extra_m := GREATEST(0, p_distance_m - v_base_m);
    v_per_km := round((v_extra_m::numeric * v_ppk) / 1000)::integer;
    v_gross  := v_base + v_extra + v_per_km;

    v_step := GREATEST(1, round(c.freight_rounding_step * 100)::integer);
    v_rounded := public._freight_round_cents(v_gross, v_step, c.freight_rounding_mode);
    v_min := round(c.min_freight * 100)::integer;
    v_max := round(c.max_freight * 100)::integer;
    v_after_min := GREATEST(v_rounded, v_min);
    v_final := LEAST(v_after_min, v_max);

    RETURN jsonb_build_object(
        'calculation_version', 'est-v1',
        'vehicle_kind', 'moto',
        'distance_m', p_distance_m,
        'base_cents', v_base,
        'extra_object_cents', v_extra,
        'price_per_km_cents', v_ppk,
        'base_distance_m', v_base_m,
        'extra_distance_m', v_extra_m,
        'per_km_cents', v_per_km,
        'gross_cents', v_gross,
        'rounding', jsonb_build_object('step_cents', v_step, 'mode', c.freight_rounding_mode, 'rounded_cents', v_rounded),
        'min_cents', v_min, 'min_applied', v_after_min > v_rounded,
        'max_cents', v_max, 'ceiling_applied', v_final < v_after_min,
        'final_cents', v_final
    );
END;
$function$;

-- @@ 50|function _compute_store_delivery_fee(uuid,double precision,double precision)
CREATE OR REPLACE FUNCTION public._compute_store_delivery_fee(p_store uuid, p_lat double precision, p_lng double precision)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    s public.stores;
    v_dist numeric;
BEGIN
    SELECT * INTO s FROM public.stores WHERE id = p_store;
    IF NOT FOUND THEN RAISE EXCEPTION 'Loja não encontrada'; END IF;
    IF s.delivery_type = 'fixed' THEN
        RETURN COALESCE(s.delivery_fee, 0);
    ELSIF s.delivery_type = 'distance' THEN
        IF s.store_lat IS NULL OR s.store_lng IS NULL OR p_lat IS NULL OR p_lng IS NULL THEN
            RAISE EXCEPTION 'Não foi possível calcular a distância.';
        END IF;
        v_dist := public.haversine_km(s.store_lat, s.store_lng, p_lat, p_lng);
        IF s.delivery_base_distance IS NOT NULL AND s.delivery_base_fee IS NOT NULL THEN
            IF v_dist <= s.delivery_base_distance THEN RETURN s.delivery_base_fee; END IF;
            RETURN s.delivery_base_fee + (v_dist - s.delivery_base_distance) * COALESCE(s.delivery_fee_per_km, 0);
        END IF;
        RETURN v_dist * COALESCE(s.delivery_fee_per_km, 0);
    END IF;
    RETURN 0;   -- 'free' ou sem tipo
END;
$function$;

-- @@ 50|function _consume_delivery_estimate(uuid,uuid,uuid,text,double precision,double precision)
CREATE OR REPLACE FUNCTION public._consume_delivery_estimate(p_estimate uuid, p_customer uuid, p_store uuid, p_address text, p_lat double precision, p_lng double precision)
 RETURNS delivery_estimates
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    e public.delivery_estimates;
BEGIN
    SELECT * INTO e FROM public.delivery_estimates WHERE id = p_estimate FOR UPDATE;
    IF NOT FOUND OR e.customer_id IS DISTINCT FROM p_customer OR e.store_id IS DISTINCT FROM p_store THEN
        RAISE EXCEPTION 'Estimativa da entrega inválida. Solicite uma nova.' USING ERRCODE = '22023', HINT = 'estimate_invalid';
    END IF;
    IF e.order_id IS NOT NULL THEN
        RAISE EXCEPTION 'Esta estimativa já foi usada em outro pedido. Solicite uma nova.' USING ERRCODE = '22023', HINT = 'estimate_used';
    END IF;
    IF e.invalidated_at IS NOT NULL THEN
        RAISE EXCEPTION 'A estimativa foi substituída por uma mais recente. Solicite uma nova.' USING ERRCODE = '22023', HINT = 'estimate_replaced';
    END IF;
    IF e.expires_at <= now() THEN
        RAISE EXCEPTION 'A estimativa da entrega expirou. Atualizamos o valor para você.' USING ERRCODE = '22023', HINT = 'estimate_expired';
    END IF;
    IF e.calculation_version NOT IN ('est-v1') THEN
        RAISE EXCEPTION 'Versão de cálculo da estimativa não suportada. Solicite uma nova.' USING ERRCODE = '22023', HINT = 'estimate_invalid';
    END IF;
    IF COALESCE(e.snapshot->>'destination_check', '') <> 'verified' OR e.destination_address IS NULL THEN
        RAISE EXCEPTION 'Não foi possível confirmar o endereço da entrega. Solicite uma nova estimativa.' USING ERRCODE = '22023', HINT = 'estimate_unverified';
    END IF;
    IF e.destination_address IS DISTINCT FROM public._norm_address(p_address)
       OR p_lat IS NULL OR p_lng IS NULL
       OR public.haversine_km(e.destination_lat, e.destination_lng, p_lat, p_lng) > 0.03 THEN
        RAISE EXCEPTION 'O endereço mudou depois da estimativa. Solicite uma nova.' USING ERRCODE = '22023', HINT = 'estimate_address_changed';
    END IF;
    RETURN e;
END;
$function$;

-- @@ 50|function _count_network(uuid)
CREATE OR REPLACE FUNCTION public._count_network(p_user uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH RECURSIVE down AS (
        SELECT id, 1 AS depth FROM public.profiles WHERE upline_id = p_user
        UNION ALL
        SELECT p.id, d.depth + 1 FROM public.profiles p JOIN down d ON p.upline_id = d.id WHERE d.depth < 30
    )
    SELECT count(*)::integer FROM down;
$function$;

-- @@ 50|function _count_valid_directs(uuid)
CREATE OR REPLACE FUNCTION public._count_valid_directs(p_user uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT count(*)::integer FROM public.profiles
    WHERE upline_id = p_user AND COALESCE(is_active, true) AND NOT COALESCE(is_blocked, false);
$function$;

-- @@ 50|function _effective_level_id(uuid)
CREATE OR REPLACE FUNCTION public._effective_level_id(p_user uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE(
        (SELECT l.id
           FROM public.user_network_state s
           JOIN public.network_levels l ON l.id IN (s.highest_level_id, s.manual_level_id)
          WHERE s.user_id = p_user
          ORDER BY l.level_order DESC LIMIT 1),
        public._initial_level_id()
    );
$function$;

-- @@ 50|function _freight_round_cents(integer,integer,text)
CREATE OR REPLACE FUNCTION public._freight_round_cents(p_gross integer, p_step integer, p_mode text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE
        WHEN p_mode = 'UP' THEN (((p_gross + p_step - 1) / p_step) * p_step)
        ELSE (((2 * p_gross + p_step) / (2 * p_step)) * p_step)          -- NEAREST: meio sobe
    END
$function$;

-- @@ 50|function _grant_hierarchy_borders(uuid)
CREATE OR REPLACE FUNCTION public._grant_hierarchy_borders(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_new int;
BEGIN
    FOR r IN SELECT id FROM public.avatar_borders WHERE is_active AND for_hierarchy ORDER BY sort_order LOOP
        INSERT INTO public.user_avatar_borders (profile_id, border_id, source) VALUES (p_user, r.id, 'hierarchy') ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_new = ROW_COUNT;
        IF v_new > 0 THEN UPDATE public.profiles SET avatar_border_id = COALESCE(avatar_border_id, r.id) WHERE id = p_user; END IF;
    END LOOP;
END; $function$;

-- @@ 50|function _grant_prepaid_borders(uuid)
CREATE OR REPLACE FUNCTION public._grant_prepaid_borders(p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_new int;
BEGIN
    FOR r IN
        SELECT id FROM public.avatar_borders
        WHERE is_active AND grant_mode = 'auto_prepaid'
          AND (available_from IS NULL OR now() >= available_from)
          AND (available_until IS NULL OR now() <= available_until)
        ORDER BY sort_order
    LOOP
        INSERT INTO public.user_avatar_borders (profile_id, border_id, source) VALUES (p_user, r.id, 'prepaid_auto')
        ON CONFLICT DO NOTHING;
        GET DIAGNOSTICS v_new = ROW_COUNT;
        -- Só quando acabou de ganhar (renovar o plano não troca a borda que a pessoa escolheu)
        IF v_new > 0 THEN UPDATE public.profiles SET avatar_border_id = r.id WHERE id = p_user; END IF;
    END LOOP;
END; $function$;

-- @@ 50|function _has_active_prepaid(uuid)
CREATE OR REPLACE FUNCTION public._has_active_prepaid(p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.subscriptions s JOIN public.plans pl ON pl.id = s.plan_id
        WHERE s.user_id = p_user AND pl.code = 'pre_pago' AND s.status = 'active'
          AND (s.starts_at IS NULL OR s.starts_at <= now()) AND s.current_period_end > now()
    );
$function$;

-- @@ 50|function _have_accepted_service(uuid,uuid)
CREATE OR REPLACE FUNCTION public._have_accepted_service(p_a uuid, p_b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.service_applications a
        JOIN public.service_requests r ON r.id = a.service_request_id
        WHERE a.status = 'accepted'
          AND ((a.applicant_id = p_a AND r.requester_id = p_b) OR (a.applicant_id = p_b AND r.requester_id = p_a))
    );
$function$;

-- @@ 50|function _initial_level_id()
CREATE OR REPLACE FUNCTION public._initial_level_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT id FROM public.network_levels WHERE is_active ORDER BY level_order LIMIT 1;
$function$;

-- @@ 50|function _is_active_member(uuid,uuid)
CREATE OR REPLACE FUNCTION public._is_active_member(p_conv uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p_user IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.conversation_members cm
        WHERE cm.conversation_id = p_conv AND cm.profile_id = p_user AND cm.status = 'active'
    );
$function$;

-- @@ 50|function _is_request_applicant(uuid,uuid)
CREATE OR REPLACE FUNCTION public._is_request_applicant(p_request uuid, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p_user IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.service_applications a WHERE a.service_request_id = p_request AND a.applicant_id = p_user
    );
$function$;

-- @@ 50|function _legacy_delivery_phase(text,text)
CREATE OR REPLACE FUNCTION public._legacy_delivery_phase(p_status text, p_stage text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE
        WHEN p_status = 'cancelled' OR p_stage = 'cancelled' THEN 'CANCELADO'
        WHEN p_status = 'completed' OR p_stage = 'delivered' THEN 'CONCLUIDO'
        WHEN p_status = 'accepted' AND p_stage = 'in_transit' THEN 'A_CAMINHO_DO_CLIENTE'
        WHEN p_status = 'accepted' AND p_stage = 'at_store' THEN 'CHEGOU_NA_LOJA'
        WHEN p_status = 'accepted' AND p_stage = 'to_store' THEN 'A_CAMINHO_DA_LOJA'
        WHEN p_status = 'accepted' THEN 'ENTREGA_LIBERADA'
        ELSE 'PROCURANDO_ENTREGADOR'
    END
$function$;

-- @@ 50|function _level_requirements_met(uuid,network_levels)
CREATE OR REPLACE FUNCTION public._level_requirements_met(p_user uuid, p_level network_levels)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT public._count_valid_directs(p_user) >= p_level.min_direct_referrals;
$function$;

-- @@ 50|function _log(uuid,uuid,text,text,uuid,jsonb,jsonb,text)
CREATE OR REPLACE FUNCTION public._log(p_actor uuid, p_target uuid, p_action text, p_entity text, p_entity_id uuid, p_old jsonb, p_new jsonb, p_reason text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    INSERT INTO public.system_logs (actor_id, target_user_id, action, entity, entity_id, old_value, new_value, reason)
    VALUES (p_actor, p_target, p_action, p_entity, p_entity_id, p_old, p_new, NULLIF(btrim(COALESCE(p_reason, '')), ''));
$function$;

-- @@ 50|function _log_grant_event(text,text,text,uuid,uuid,uuid,text,text,text,uuid,timestamp with time zone,timestamp with time zone,text,jsonb)
CREATE OR REPLACE FUNCTION public._log_grant_event(p_action text, p_outcome text, p_denial text, p_actor uuid, p_target uuid, p_plan_id uuid, p_plan_code text, p_permission text, p_scope text, p_subscription uuid, p_starts timestamp with time zone, p_expires timestamp with time zone, p_reason text, p_metadata jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_id uuid;
    v_status_id uuid;
    v_status_slug text;
BEGIN
    SELECT st.status_id, st.slug INTO v_status_id, v_status_slug FROM public._actor_status(p_actor) st;
    INSERT INTO public.grant_audit_logs (
        action, outcome, denial_reason, actor_user_id, actor_status_id, actor_status_slug,
        target_user_id, plan_id, plan_code, permission_used, scope_used, subscription_id,
        starts_at, expires_at, reason, metadata
    ) VALUES (
        p_action, p_outcome, p_denial,
        (SELECT id FROM public.profiles WHERE id = p_actor), v_status_id, v_status_slug,
        (SELECT id FROM public.profiles WHERE id = p_target), p_plan_id, p_plan_code, p_permission, p_scope, p_subscription,
        p_starts, p_expires, p_reason, COALESCE(p_metadata, '{}'::jsonb)
    ) RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$;

-- @@ 50|function _merge_duplicate_profile_conversations()
CREATE OR REPLACE FUNCTION public._merge_duplicate_profile_conversations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    pair record; k public.conversations; d public.conversations;
    x uuid; y uuid;
    x_read_k timestamptz; y_read_k timestamptz; x_read_d timestamptz; y_read_d timestamptz;
    x_unread timestamptz; y_unread timestamptz;
    merged integer := 0;
BEGIN
    FOR pair IN
        SELECT LEAST(customer_id, owner_profile_id) AS a, GREATEST(customer_id, owner_profile_id) AS b
        FROM public.conversations
        WHERE owner_profile_id IS NOT NULL
        GROUP BY 1, 2
        HAVING count(*) > 1
    LOOP
        -- a sala que fica: a mais antiga
        SELECT * INTO k FROM public.conversations
        WHERE owner_profile_id IS NOT NULL
          AND LEAST(customer_id, owner_profile_id) = pair.a AND GREATEST(customer_id, owner_profile_id) = pair.b
        ORDER BY created_at, id LIMIT 1;

        FOR d IN
            SELECT * FROM public.conversations
            WHERE owner_profile_id IS NOT NULL
              AND LEAST(customer_id, owner_profile_id) = pair.a AND GREATEST(customer_id, owner_profile_id) = pair.b
              AND id <> k.id
            ORDER BY created_at, id
        LOOP
            x := k.customer_id; y := k.owner_profile_id;
            x_read_k := k.customer_read_at;
            y_read_k := COALESCE(k.owner_read_at, 'epoch'::timestamptz);
            -- na sala "d" os papéis estão trocados (o dono da sala que fica era o cliente aqui)
            IF d.customer_id = x THEN
                x_read_d := d.customer_read_at;
                y_read_d := COALESCE(d.owner_read_at, 'epoch'::timestamptz);
            ELSE
                x_read_d := COALESCE(d.owner_read_at, 'epoch'::timestamptz);
                y_read_d := d.customer_read_at;
            END IF;

            -- a primeira mensagem que cada um ainda não leu, nas duas salas
            SELECT min(m.created_at) INTO x_unread FROM public.direct_messages m
            WHERE m.sender_id <> x AND (
                (m.conversation_id = k.id AND m.created_at > x_read_k) OR (m.conversation_id = d.id AND m.created_at > x_read_d));
            SELECT min(m.created_at) INTO y_unread FROM public.direct_messages m
            WHERE m.sender_id <> y AND (
                (m.conversation_id = k.id AND m.created_at > y_read_k) OR (m.conversation_id = d.id AND m.created_at > y_read_d));

            UPDATE public.direct_messages SET conversation_id = k.id WHERE conversation_id = d.id;
            DELETE FROM public.conversations WHERE id = d.id;

            UPDATE public.conversations c SET
                customer_read_at = COALESCE(x_unread - interval '1 millisecond', GREATEST(x_read_k, x_read_d)),
                owner_read_at    = COALESCE(y_unread - interval '1 millisecond', GREATEST(y_read_k, y_read_d)),
                last_message_at  = lm.created_at,
                last_message     = left(lm.content, 140),
                last_sender_id   = lm.sender_id
            FROM (
                SELECT created_at, content, sender_id FROM public.direct_messages
                WHERE conversation_id = k.id ORDER BY created_at DESC, id DESC LIMIT 1
            ) lm
            WHERE c.id = k.id;

            merged := merged + 1;
        END LOOP;
    END LOOP;
    RETURN merged;
END; $function$;

-- @@ 50|function _network_children(uuid,integer,integer)
CREATE OR REPLACE FUNCTION public._network_children(p_parent uuid, p_limit integer, p_offset integer)
 RETURNS TABLE(id uuid, name text, profile_slug text, avatar_url text, joined_at timestamp with time zone, is_valid boolean, direct_count integer, level_id uuid, level_name text, level_order integer, border_style text, border_color text, border_colors text[], background_style text, badge_style text, icon text, rate_prepaid_bp integer, rate_postpaid_bp integer, is_custom boolean, total_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT c.id, c.name, c."profileSlug", c.avatar_url, c.created_at,
           (COALESCE(c.is_active, true) AND NOT COALESCE(c.is_blocked, false)),
           public._count_valid_directs(c.id),
           l.id, l.name, l.level_order, l.border_style, l.border_color, l.border_colors, l.background_style, l.badge_style, l.icon,
           (public.get_effective_commission(c.id, 'prepaid') ->> 'commission_rate_bp')::integer,
           (public.get_effective_commission(c.id, 'postpaid') ->> 'commission_rate_bp')::integer,
           (public.get_effective_commission(c.id, 'prepaid') ->> 'is_custom')::boolean
             OR (public.get_effective_commission(c.id, 'postpaid') ->> 'is_custom')::boolean,
           count(*) OVER ()
      FROM public.profiles c
      JOIN public.network_levels l ON l.id = public._effective_level_id(c.id)
     WHERE c.upline_id = p_parent
     ORDER BY c.created_at DESC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 100) OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$function$;

-- @@ 50|function _norm_address(text)
CREATE OR REPLACE FUNCTION public._norm_address(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT NULLIF(lower(regexp_replace(btrim(COALESCE(p, '')), '\s+', ' ', 'g')), '') $function$;

-- @@ 50|function _notify(uuid,text,uuid,uuid,jsonb,text)
CREATE OR REPLACE FUNCTION public._notify(p_profile uuid, p_kind text, p_actor uuid, p_ref uuid, p_meta jsonb, p_dedupe text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF p_profile IS NULL OR p_profile IS NOT DISTINCT FROM p_actor THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_profile) THEN RETURN; END IF;
    INSERT INTO public.profile_notifications (profile_id, kind, actor_id, ref_id, meta, dedupe_key)
    VALUES (p_profile, p_kind, p_actor, p_ref, COALESCE(p_meta, '{}'::jsonb), p_dedupe)
    ON CONFLICT (profile_id, dedupe_key) DO NOTHING;
END; $function$;

-- @@ 50|function _ping_delivery_events()
CREATE OR REPLACE FUNCTION public._ping_delivery_events()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_url text;
BEGIN
    IF COALESCE(current_setting('app.skip_delivery_ping', true), '') = '1' THEN RETURN; END IF;
    SELECT notify_url INTO v_url FROM public.delivery_dispatch_settings WHERE id;
    IF v_url IS NOT NULL AND v_url <> '' THEN
        PERFORM net.http_post(url := v_url, body := '{}'::jsonb, headers := '{"Content-Type":"application/json"}'::jsonb);
    END IF;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'delivery events ping failed: %', SQLERRM;
END;
$function$;

-- @@ 50|function _pix_key_valid(text,text)
CREATE OR REPLACE FUNCTION public._pix_key_valid(p_type text, p_key text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE p_type
        WHEN 'cpf' THEN p_key ~ '^\d{11}$' AND p_key !~ '^(\d)\1{10}$'
        WHEN 'cnpj' THEN p_key ~ '^\d{14}$' AND p_key !~ '^(\d)\1{13}$'
        WHEN 'phone' THEN p_key ~ '^\d{10,13}$'
        WHEN 'email' THEN p_key ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' AND char_length(p_key) <= 77
        WHEN 'random' THEN p_key ~ '^[0-9a-f]{8}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{4}-?[0-9a-f]{12}$'
        ELSE false
    END
$function$;

-- @@ 50|function _pix_mask(text,text)
CREATE OR REPLACE FUNCTION public._pix_mask(p_type text, p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE WHEN p_type = 'email' THEN left(p_key, 1) || '***' || substring(p_key from '@.*$') ELSE '***' || right(p_key, 4) END
$function$;

-- @@ 50|function _pix_normalize(text,text)
CREATE OR REPLACE FUNCTION public._pix_normalize(p_type text, p_key text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE p_type
        WHEN 'cpf' THEN regexp_replace(COALESCE(p_key, ''), '\D', '', 'g')
        WHEN 'cnpj' THEN regexp_replace(COALESCE(p_key, ''), '\D', '', 'g')
        WHEN 'phone' THEN regexp_replace(COALESCE(p_key, ''), '[^0-9]', '', 'g')
        WHEN 'email' THEN lower(btrim(COALESCE(p_key, '')))
        WHEN 'random' THEN lower(btrim(COALESCE(p_key, '')))
        ELSE NULL
    END
$function$;

-- @@ 50|function _price_order_items(uuid,jsonb,boolean)
CREATE OR REPLACE FUNCTION public._price_order_items(p_store uuid, p_items jsonb, p_allow_addons boolean)
 RETURNS TABLE(product_id uuid, product_name text, quantity integer, unit_price numeric, total_price numeric, comment text, addons jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    it jsonb;
    pr public.products;
    ad jsonb;
    ar record;
    v_qty integer;
    v_addons jsonb;
    v_addon_sum numeric;
BEGIN
    IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
        RAISE EXCEPTION 'Seu carrinho está vazio';
    END IF;
    IF jsonb_array_length(p_items) > 100 THEN RAISE EXCEPTION 'Itens demais no pedido'; END IF;
    FOR it IN SELECT * FROM jsonb_array_elements(p_items) LOOP
        SELECT * INTO pr FROM public.products WHERE id = NULLIF(it->>'product_id', '')::uuid AND store_id = p_store AND is_active;
        IF NOT FOUND THEN RAISE EXCEPTION 'Produto indisponível nesta loja'; END IF;
        v_qty := COALESCE(NULLIF(it->>'quantity', '')::integer, 0);
        IF v_qty < 1 OR v_qty > 1000 THEN RAISE EXCEPTION 'Quantidade inválida'; END IF;

        v_addons := '[]'::jsonb;
        v_addon_sum := 0;
        IF p_allow_addons AND jsonb_typeof(it->'addons') = 'array' THEN
            FOR ad IN SELECT * FROM jsonb_array_elements(it->'addons') LOOP
                SELECT pa.id, pa.name, pa.price INTO ar FROM public.product_addons pa
                 WHERE pa.id = NULLIF(ad->>'id', '')::uuid AND pa.product_id = pr.id AND pa.is_active;
                IF NOT FOUND THEN RAISE EXCEPTION 'Adicional indisponível'; END IF;
                v_addons := v_addons || jsonb_build_array(jsonb_build_object('id', ar.id, 'name', ar.name, 'price', ar.price));
                v_addon_sum := v_addon_sum + ar.price;
            END LOOP;
        END IF;

        product_id := pr.id;
        product_name := pr.name;
        quantity := v_qty;
        unit_price := pr.price + v_addon_sum;
        total_price := (pr.price + v_addon_sum) * v_qty;
        comment := left(NULLIF(btrim(COALESCE(it->>'comment', '')), ''), 500);
        addons := CASE WHEN jsonb_array_length(v_addons) > 0 THEN v_addons ELSE NULL END;
        RETURN NEXT;
    END LOOP;
END;
$function$;

-- @@ 50|function _purge_rows(regclass,text,text[],integer)
CREATE OR REPLACE FUNCTION public._purge_rows(p_table regclass, p_key_col text, p_vals text[], p_depth integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    fk record;
    parent_vals text[];
    child_pk text;
    child_vals text[];
BEGIN
    IF p_vals IS NULL OR coalesce(array_length(p_vals, 1), 0) = 0 THEN RETURN; END IF;
    IF p_depth > 10 THEN RAISE EXCEPTION 'Exclusão em cascata profunda demais em %', p_table; END IF;

    FOR fk IN
        SELECT c.conrelid::regclass AS child, a.attname AS child_col, ra.attname AS parent_col
        FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
        JOIN pg_attribute ra ON ra.attrelid = c.confrelid AND ra.attnum = c.confkey[1]
        WHERE c.contype = 'f'
          AND c.confrelid = p_table
          AND array_length(c.conkey, 1) = 1
          AND c.confdeltype NOT IN ('n', 'd')
          AND c.conrelid <> p_table
    LOOP
        EXECUTE format('SELECT array_agg(%I::text) FROM %s WHERE %I::text = ANY($1)', fk.parent_col, p_table, p_key_col)
            INTO parent_vals USING p_vals;
        CONTINUE WHEN parent_vals IS NULL;

        SELECT a.attname INTO child_pk
        FROM pg_index i
        JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0]
        WHERE i.indrelid = fk.child AND i.indisprimary AND i.indnatts = 1;

        IF child_pk IS NOT NULL THEN
            EXECUTE format('SELECT array_agg(%I::text) FROM %s WHERE %I::text = ANY($1)', child_pk, fk.child, fk.child_col)
                INTO child_vals USING parent_vals;
            PERFORM public._purge_rows(fk.child, child_pk, child_vals, p_depth + 1);
        END IF;

        EXECUTE format('DELETE FROM %s WHERE %I::text = ANY($1)', fk.child, fk.child_col) USING parent_vals;
    END LOOP;
END;
$function$;

-- @@ 50|function _scope_rank(text)
CREATE OR REPLACE FUNCTION public._scope_rank(p_scope text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE p_scope
        WHEN 'all' THEN 4
        WHEN 'network' THEN 3
        WHEN 'direct_downline' THEN 2
        WHEN 'direct_invite' THEN 1
        ELSE 0
    END;
$function$;

-- @@ 50|function _service_request_title(uuid)
CREATE OR REPLACE FUNCTION public._service_request_title(p_request uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE(NULLIF(left(btrim(description), 60), ''), NULLIF(custom_service, ''), service_type)
    FROM public.service_requests WHERE id = p_request;
$function$;

-- @@ 50|function _slug_taken(text,uuid)
CREATE OR REPLACE FUNCTION public._slug_taken(p_slug text, p_except_vehicle uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p_slug = ANY (ARRAY[
        'modeloinicial','modoprestador','painel-perfil','painel-loja','veiculo','admin','api','auth','carrinho','login','registro',
        'lojas','conversas','produtos','publicacoes','radar','convite','compromissos','compromisso','social','comunidade',
        'pedir-motorista','solicitar-servico','procurar-servico','aceitar-corridas','painel-motorista','painel-prestador',
        'minhas-corridas','planos','meus-servicos','administrador','perfil','loja','app'
    ])
    OR EXISTS (SELECT 1 FROM public.profiles WHERE lower("profileSlug") = p_slug)
    OR EXISTS (SELECT 1 FROM public.stores WHERE lower("storeSlug") = p_slug)
    OR EXISTS (SELECT 1 FROM public.driver_vehicles v WHERE lower(v.vehicle_slug) = p_slug AND (p_except_vehicle IS NULL OR v.id <> p_except_vehicle));
$function$;

-- @@ 50|function _slugify(text)
CREATE OR REPLACE FUNCTION public._slugify(p_text text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT left(trim(both '-' from regexp_replace(
        lower(translate(coalesce(p_text, ''), 'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ', 'aaaaaeeeeiiiiooooouuuucaaaaaeeeeiiiiooooouuuuc')),
        '[^a-z0-9]+', '-', 'g')), 60);
$function$;

-- @@ 50|function _start_order_delivery_dispatch(uuid)
CREATE OR REPLACE FUNCTION public._start_order_delivery_dispatch(p_order uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    o public.orders;
    s public.stores;
    cfg public.delivery_dispatch_settings;
    est public.delivery_estimates;
    v_existing uuid;
    v_ride uuid;
    v_dispatch uuid;
    v_dist numeric;
    v_items text;
    v_fee numeric;
    v_platform numeric;
    v_v2 boolean;
    v_round uuid;
BEGIN
    SELECT * INTO o FROM public.orders WHERE id = p_order;
    IF NOT FOUND THEN RETURN NULL; END IF;
    v_v2 := o.delivery_flow_version = 2;
    SELECT id INTO v_existing FROM public.order_delivery_dispatches WHERE order_id = p_order;
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;

    SELECT * INTO s FROM public.stores WHERE id = o.store_id;
    IF NOT FOUND OR NOT s.iuser_delivery_enabled THEN
        IF v_v2 THEN RAISE EXCEPTION 'A loja não usa mais o entregador iUser; não é possível aceitar este pedido' USING ERRCODE = '22023'; END IF;
        RETURN NULL;
    END IF;
    IF o.delivery_address IS NULL OR COALESCE(o.delivery_fee, 0) <= 0 THEN
        IF v_v2 THEN RAISE EXCEPTION 'Pedido sem endereço ou frete válido' USING ERRCODE = '22023'; END IF;
        RETURN NULL;
    END IF;
    IF s.address IS NULL OR s.store_lat IS NULL OR s.store_lng IS NULL THEN
        IF v_v2 THEN RAISE EXCEPTION 'A loja não tem endereço cadastrado' USING ERRCODE = '22023'; END IF;
        RETURN NULL;
    END IF;

    IF v_v2 THEN
        SELECT * INTO est FROM public.delivery_estimates WHERE order_id = o.id;
        IF NOT FOUND OR est.estimated_freight IS DISTINCT FROM o.delivery_fee THEN
            RAISE EXCEPTION 'Pedido V2 sem estimativa oficial vinculada' USING ERRCODE = '22023';
        END IF;
    END IF;

    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    v_fee := o.delivery_fee;
    -- V2: a plataforma NÃO desconta percentual do frete do motorista (decisão comercial); V1 segue a configuração
    v_platform := CASE WHEN v_v2 THEN 0 ELSE round(v_fee * cfg.platform_fee_percent / 100, 2) END;

    IF o.delivery_lat IS NOT NULL AND o.delivery_lng IS NOT NULL THEN
        v_dist := round(public.haversine_km(s.store_lat, s.store_lng, o.delivery_lat, o.delivery_lng) * 1.3, 1);
    END IF;

    SELECT string_agg(quantity || 'x ' || product_name, ', ') INTO v_items FROM public.order_items WHERE order_id = o.id;

    -- corrida antiga do pedido (chamada manual de antes): reaproveita
    SELECT id INTO v_ride FROM public.ride_requests WHERE order_id = o.id AND status <> 'cancelled' LIMIT 1;
    IF v_ride IS NULL THEN
        INSERT INTO public.ride_requests (
            requester_id, ride_type, vehicle_type, origin_address, origin_lat, origin_lng,
            destination_address, destination_lat, destination_lng, distance_km, object_description,
            sender_name, recipient_name, offered_price, order_id, store_id, visible_radius_km
        ) VALUES (
            s.owner_id, 'objeto', 'moto', s.address, s.store_lat, s.store_lng,
            o.delivery_address, o.delivery_lat, o.delivery_lng, v_dist,
            left('Pedido da loja ' || s.name || COALESCE(': ' || v_items, ''), 300),
            s.name, o.buyer_name, v_fee - v_platform, o.id, s.id, cfg.initial_radius_km
        ) RETURNING id INTO v_ride;
    END IF;

    IF v_v2 THEN
        -- estimated_freight é a estimativa original e nunca mais muda; a oferta (final_freight) parte dela
        INSERT INTO public.order_delivery_dispatches (order_id, ride_request_id, store_id, customer_id, original_freight, final_freight, radius_km,
                                                      flow_version, phase, estimated_freight, estimate_id,
                                                      price_limit, last_price_change_at, offer_expires_at)
        VALUES (o.id, v_ride, s.id, o.buyer_id, v_fee, v_fee, cfg.initial_radius_km,
                2, 'PROCURANDO_ENTREGADOR', est.estimated_freight, est.id,
                public._v2_auto_limit(est.estimated_freight, cfg), now(), now() + make_interval(secs => cfg.offer_duration_seconds))
        RETURNING id INTO v_dispatch;
    ELSE
        INSERT INTO public.order_delivery_dispatches (order_id, ride_request_id, store_id, customer_id, original_freight, final_freight, radius_km)
        VALUES (o.id, v_ride, s.id, o.buyer_id, v_fee, v_fee, cfg.initial_radius_km)
        RETURNING id INTO v_dispatch;
    END IF;

    IF v_v2 THEN
        -- rodada 1 = a estimativa que o cliente viu ao enviar o pedido, no raio inicial; os motoristas são avisados pela fila
        INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status,
                                                  authorized_at, authorized_by, strategy, action, automatic, offer_expires_at, price_limit)
        VALUES (v_dispatch, 1, 'initial', v_fee, 0, v_fee, 0, v_fee, cfg.initial_radius_km, 'authorized', now(), o.buyer_id,
                cfg.search_strategy, 'initial', true, now() + make_interval(secs => cfg.offer_duration_seconds), public._v2_auto_limit(est.estimated_freight, cfg))
        RETURNING id INTO v_round;
        INSERT INTO public.order_delivery_events (dispatch_id, kind, old_radius, new_radius, round_id, data)
        VALUES (v_dispatch, 'round_started', NULL, cfg.initial_radius_km, v_round,
                jsonb_build_object('action', 'initial', 'round', 1, 'price', v_fee, 'price_changed', true, 'radius_changed', true));
        PERFORM public._ping_delivery_events();
    ELSE
        INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status, authorized_at, authorized_by)
        VALUES (v_dispatch, 1, 'initial', v_fee, 0, v_fee, v_platform, v_fee - v_platform, cfg.initial_radius_km, 'authorized', now(), o.buyer_id);
    END IF;

    RETURN v_dispatch;
END;
$function$;

-- @@ 50|function _upline_would_cycle(uuid,uuid)
CREATE OR REPLACE FUNCTION public._upline_would_cycle(p_user uuid, p_upline uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH RECURSIVE chain AS (
        SELECT id, upline_id, 1 AS depth FROM public.profiles WHERE id = p_upline
        UNION ALL
        SELECT p.id, p.upline_id, c.depth + 1
        FROM public.profiles p JOIN chain c ON p.id = c.upline_id
        WHERE c.depth < 100
    )
    SELECT EXISTS (SELECT 1 FROM chain WHERE id = p_user);
$function$;

-- @@ 50|function _v2_auto_limit(numeric,delivery_dispatch_settings)
CREATE OR REPLACE FUNCTION public._v2_auto_limit(p_estimated numeric, cfg delivery_dispatch_settings)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE v numeric := p_estimated;
BEGIN
    IF cfg.auto_increase_enabled THEN
        v := cfg.max_freight;
        IF cfg.auto_increase_cap_amount IS NOT NULL THEN v := LEAST(v, p_estimated + cfg.auto_increase_cap_amount); END IF;
        IF cfg.auto_increase_cap_percent IS NOT NULL THEN v := LEAST(v, floor(p_estimated * (1 + cfg.auto_increase_cap_percent / 100) * 100) / 100); END IF;
    END IF;
    RETURN round(GREATEST(p_estimated, v), 2);
END;
$function$;

-- @@ 50|function _v2_decide(order_delivery_dispatches,delivery_dispatch_settings)
CREATE OR REPLACE FUNCTION public._v2_decide(d order_delivery_dispatches, cfg delivery_dispatch_settings)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_radius_ok boolean := d.radius_km < cfg.max_radius_km;
    v_new_radius numeric := LEAST(cfg.max_radius_km, d.radius_km + cfg.radius_step_km);
    v_next numeric := public._v2_next_price(d.final_freight, cfg);
    v_can_price boolean := d.price_adjustments < cfg.max_price_adjustments AND v_next > d.final_freight;
    v_interval_ok boolean := now() >= COALESCE(d.last_price_change_at, d.created_at) + make_interval(mins => cfg.price_adjust_interval_minutes);
    v_price text;
    v_action text;
BEGIN
    IF NOT v_can_price THEN v_price := 'none';
    ELSIF NOT v_interval_ok THEN v_price := 'wait';
    ELSIF v_next <= d.price_limit THEN v_price := 'now';
    ELSE v_price := 'needs_auth';
    END IF;

    IF cfg.search_strategy = 'EXPANDIR_RAIO_PRIMEIRO' THEN
        v_action := CASE WHEN v_radius_ok THEN 'radius' WHEN v_price = 'now' THEN 'price' WHEN v_price = 'wait' THEN 'hold'
                         WHEN v_price = 'needs_auth' THEN 'ask' ELSE 'end' END;
    ELSIF cfg.search_strategy = 'AUMENTAR_PRECO_PRIMEIRO' THEN
        v_action := CASE WHEN v_price = 'now' THEN 'price' WHEN v_price = 'wait' THEN 'hold' WHEN v_radius_ok THEN 'radius'
                         WHEN v_price = 'needs_auth' THEN 'ask' ELSE 'end' END;
    ELSE   -- RAIO_E_PRECO_SIMULTANEAMENTE
        v_action := CASE WHEN v_radius_ok AND v_price = 'now' THEN 'radius_price' WHEN v_radius_ok THEN 'radius' WHEN v_price = 'now' THEN 'price'
                         WHEN v_price = 'wait' THEN 'hold' WHEN v_price = 'needs_auth' THEN 'ask' ELSE 'end' END;
    END IF;
    RETURN jsonb_build_object('action', v_action, 'price_state', v_price, 'new_radius', v_new_radius, 'next_price', v_next);
END;
$function$;

-- @@ 50|function _v2_end_search(uuid,text)
CREATE OR REPLACE FUNCTION public._v2_end_search(p_dispatch uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d public.order_delivery_dispatches;
BEGIN
    PERFORM set_config('app.delivery_actor', 'system', true);
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.status <> 'searching' THEN RETURN; END IF;
    UPDATE public.order_delivery_dispatches
       SET status = 'cancelled', phase = 'SEM_ENTREGADOR', search_end_reason = p_reason, offer_expires_at = NULL, updated_at = now()
     WHERE id = d.id;
    UPDATE public.ride_requests SET status = 'cancelled', cancelled_by = 'requester' WHERE id = d.ride_request_id AND status = 'pending';
END;
$function$;

-- @@ 50|function _v2_expire_reservation(uuid)
CREATE OR REPLACE FUNCTION public._v2_expire_reservation(p_dispatch uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d public.order_delivery_dispatches; cfg public.delivery_dispatch_settings; v_ok boolean;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 OR d.status <> 'accepted' OR d.reservation_released_at IS NOT NULL OR d.reserved_until IS NULL OR now() < d.reserved_until THEN
        RETURN 'skip';
    END IF;
    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    IF cfg.reservation_expiry_action = 'CANCEL_DELIVERY' THEN
        v_ok := public._v2_release_reservation(d.id, 'customer_timeout', 'cancel');
        RETURN CASE WHEN v_ok THEN 'expired:cancelled' ELSE 'skip' END;
    END IF;
    v_ok := public._v2_release_reservation(d.id, 'customer_timeout', 'reopen');
    IF v_ok AND now() >= d.created_at + make_interval(mins => cfg.max_search_minutes) THEN
        PERFORM public._v2_end_search(d.id, 'timeout');
        RETURN 'expired:no_driver';
    END IF;
    RETURN CASE WHEN v_ok THEN 'expired:reopened' ELSE 'skip' END;
END;
$function$;

-- @@ 50|function _v2_financial_timeout(uuid)
CREATE OR REPLACE FUNCTION public._v2_financial_timeout(p_dispatch uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d public.order_delivery_dispatches; v_owner uuid; v_driver uuid;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 OR d.status <> 'accepted'
       OR d.phase NOT IN ('LOJA_INFORMOU_RECEBIMENTO', 'AGUARDANDO_PAGAMENTO_ENTREGADOR', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR')
       OR d.reserved_until IS NULL OR now() < d.reserved_until THEN
        RETURN 'skip';
    END IF;
    SELECT owner_id INTO v_owner FROM public.stores WHERE id = d.store_id;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;
    PERFORM set_config('app.delivery_actor', 'system', true);
    UPDATE public.order_delivery_dispatches SET phase = 'PAGAMENTO_EM_VERIFICACAO', updated_at = now() WHERE id = d.id;
    INSERT INTO public.delivery_incidents (dispatch_id, order_id, ride_request_id, store_id, driver_id, kind, description, opened_by, opened_role)
    VALUES (d.id, d.order_id, d.ride_request_id, d.store_id, v_driver, 'operational',
            'O prazo do fluxo financeiro terminou sem a conclusão do pagamento ao entregador. Nada foi liberado nem devolvido automaticamente.', v_owner, 'system');
    INSERT INTO public.delivery_payment_events (dispatch_id, order_id, store_id, ride_request_id, driver_id, kind, amount, declared_by, declared_role, metadata)
    VALUES (d.id, d.order_id, d.store_id, d.ride_request_id, v_driver, 'sent_for_verification', d.frozen_freight, v_owner, 'system', jsonb_build_object('reason', 'financial_window_expired', 'from_phase', d.phase));
    INSERT INTO public.order_delivery_events (dispatch_id, kind, data)
    VALUES (d.id, 'reservation_notice', jsonb_build_object('reason', 'in_verification', 'driver_id', v_driver));
    RETURN 'timeout:verification';
END;
$function$;

-- @@ 50|function _v2_next_price(numeric,delivery_dispatch_settings)
CREATE OR REPLACE FUNCTION public._v2_next_price(p_current numeric, cfg delivery_dispatch_settings)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_c integer := round(p_current * 100)::integer;
    v_max integer := round(cfg.max_freight * 100)::integer;
    v_unit integer := GREATEST(1, round(cfg.freight_rounding_step * 100)::integer);
    v_step integer;
    v_new integer;
BEGIN
    IF v_c >= v_max THEN RETURN p_current; END IF;
    v_step := CASE cfg.increase_kind WHEN 'percent' THEN round(v_c * cfg.increase_value / 100)::integer ELSE round(cfg.increase_value * 100)::integer END;
    IF v_step <= 0 THEN RETURN p_current; END IF;
    v_new := public._freight_round_cents(v_c + v_step, v_unit, cfg.freight_rounding_mode);
    IF v_new <= v_c THEN v_new := v_c + v_unit; END IF;
    RETURN round(LEAST(v_new, v_max)::numeric / 100, 2);
END;
$function$;

-- @@ 50|function _v2_phase_money(text)
CREATE OR REPLACE FUNCTION public._v2_phase_money(p_phase text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT p_phase IN ('LOJA_INFORMOU_RECEBIMENTO', 'AGUARDANDO_PAGAMENTO_ENTREGADOR', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', 'PAGAMENTO_EM_VERIFICACAO',
                          'ENTREGADOR_CONFIRMOU_RECEBIMENTO', 'ENTREGA_LIBERADA', 'A_CAMINHO_DA_LOJA', 'CHEGOU_NA_LOJA', 'PEDIDO_RETIRADO', 'A_CAMINHO_DO_CLIENTE') $function$;

-- @@ 50|function _v2_phase_released(text)
CREATE OR REPLACE FUNCTION public._v2_phase_released(p_phase text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT p_phase IN ('ENTREGA_LIBERADA', 'A_CAMINHO_DA_LOJA', 'CHEGOU_NA_LOJA', 'PEDIDO_RETIRADO', 'A_CAMINHO_DO_CLIENTE', 'ENTREGUE', 'CONCLUIDO') $function$;

-- @@ 50|function _v2_projected_limit(numeric,integer,delivery_dispatch_settings)
CREATE OR REPLACE FUNCTION public._v2_projected_limit(p_current numeric, p_used integer, cfg delivery_dispatch_settings)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE v numeric := p_current; n numeric; i integer;
BEGIN
    FOR i IN 1 .. GREATEST(0, cfg.max_price_adjustments - p_used) LOOP
        n := public._v2_next_price(v, cfg);
        EXIT WHEN n <= v;
        v := n;
    END LOOP;
    RETURN v;
END;
$function$;

-- @@ 50|function _v2_release_reservation(uuid,text,text,boolean)
CREATE OR REPLACE FUNCTION public._v2_release_reservation(p_dispatch uuid, p_reason text, p_mode text, p_skip_ride boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    d public.order_delivery_dispatches;
    cfg public.delivery_dispatch_settings;
    v_driver uuid;
    v_round uuid;
    v_expires timestamptz;
BEGIN
    PERFORM set_config('app.delivery_actor', 'system', true);
    PERFORM set_config('app.delivery_v2_engine', '1', true);
    PERFORM set_config('app.delivery_v2_release', '1', true);
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 OR d.status <> 'accepted' OR d.reserved_at IS NULL OR d.reservation_released_at IS NOT NULL
       OR d.phase NOT IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE') THEN
        PERFORM set_config('app.delivery_v2_release', '', true);
        RETURN false;                                           -- já liberada / não está reservada: repetir não faz nada
    END IF;
    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;

    IF p_mode = 'reopen' THEN
        v_expires := now() + make_interval(secs => cfg.offer_duration_seconds);
        -- frozen_freight volta a NULL: não pode ser confundido com o frete definitivo de um motorista futuro (a história fica nos eventos)
        UPDATE public.order_delivery_dispatches
           SET status = 'searching', stage = 'searching', phase = 'PROCURANDO_ENTREGADOR', frozen_freight = NULL, freight_frozen_at = NULL,
               reservation_released_at = now(), reservation_release_reason = p_reason, search_end_reason = NULL,
               round = d.round + 1, round_started_at = now(), offer_expires_at = v_expires, updated_at = now()
         WHERE id = d.id;
        INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status,
                                                  authorized_at, strategy, action, automatic, offer_expires_at, price_limit)
        VALUES (d.id, d.round + 1, 'hold', d.original_freight, d.final_freight - d.original_freight, d.final_freight, 0, d.final_freight, d.radius_km, 'authorized',
                now(), cfg.search_strategy, 'reopen', true, v_expires, d.price_limit)
        RETURNING id INTO v_round;
        PERFORM public._v2_set_order_freight(d.order_id, COALESCE(d.estimated_freight, d.original_freight));
        IF NOT p_skip_ride THEN
            UPDATE public.ride_requests SET status = 'pending', driver_id = NULL, cancelled_by = NULL, share_closed_at = NULL
             WHERE id = d.ride_request_id AND status IN ('accepted', 'cancelled');
        END IF;
        -- quem perdeu a disputa pelo aceite (rejeitado só porque a corrida fechou) volta a poder aceitar a nova oferta
        DELETE FROM public.ride_applications WHERE ride_request_id = d.ride_request_id AND status = 'rejected' AND applicant_id IS DISTINCT FROM v_driver;
        IF v_driver IS NOT NULL THEN
            IF p_reason = 'driver_cancelled' THEN
                UPDATE public.ride_applications SET status = 'rejected' WHERE ride_request_id = d.ride_request_id AND applicant_id = v_driver;
            ELSE
                DELETE FROM public.ride_applications WHERE ride_request_id = d.ride_request_id AND applicant_id = v_driver;   -- não foi culpa dele: pode aceitar de novo
            END IF;
        END IF;
        INSERT INTO public.order_delivery_events (dispatch_id, kind, old_radius, new_radius, round_id, data)
        VALUES (d.id, 'round_started', d.radius_km, d.radius_km, v_round,
                jsonb_build_object('action', 'reopen', 'round', d.round + 1, 'price', d.final_freight, 'price_changed', true, 'radius_changed', true));
    ELSE
        UPDATE public.order_delivery_dispatches
           SET status = 'cancelled', phase = 'CANCELADO', reservation_released_at = now(), reservation_release_reason = p_reason,
               search_end_reason = p_reason, offer_expires_at = NULL, updated_at = now()
         WHERE id = d.id;
        PERFORM public._v2_set_order_freight(d.order_id, COALESCE(d.estimated_freight, d.original_freight));
        IF NOT p_skip_ride THEN
            UPDATE public.ride_requests SET status = 'cancelled', cancelled_by = 'requester' WHERE id = d.ride_request_id AND status = 'accepted';
        END IF;
    END IF;

    INSERT INTO public.order_delivery_events (dispatch_id, kind, data)
    VALUES (d.id, 'reservation_notice', jsonb_build_object('reason', p_reason, 'mode', p_mode, 'driver_id', v_driver, 'released_frozen_freight', d.frozen_freight));
    PERFORM set_config('app.delivery_v2_release', '', true);      -- a marca vale só durante a liberação (a transação pode continuar)
    PERFORM public._ping_delivery_events();
    RETURN true;
END;
$function$;

-- @@ 50|function _v2_set_order_freight(uuid,numeric)
CREATE OR REPLACE FUNCTION public._v2_set_order_freight(p_order uuid, p_fee numeric)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    UPDATE public.orders SET total_amount = total_amount - COALESCE(delivery_fee, 0) + p_fee, delivery_fee = p_fee WHERE id = p_order
$function$;

-- @@ 50|function _v2_state_code(text,text)
CREATE OR REPLACE FUNCTION public._v2_state_code(p_phase text, p_status text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT CASE
        WHEN p_phase = 'PROCURANDO_ENTREGADOR' THEN 'searching'
        WHEN p_phase = 'AGUARDANDO_AUTORIZACAO_REAJUSTE' THEN 'awaiting_authorization'
        WHEN p_phase = 'ENTREGADOR_RESERVADO' THEN 'driver_reserved'
        WHEN p_phase = 'AGUARDANDO_PAGAMENTO_CLIENTE' THEN 'awaiting_payment'
        WHEN p_phase = 'LOJA_INFORMOU_RECEBIMENTO' THEN 'customer_payment_reported'
        WHEN p_phase = 'AGUARDANDO_PAGAMENTO_ENTREGADOR' THEN 'awaiting_driver_payment'
        WHEN p_phase = 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR' THEN 'driver_payment_reported'
        WHEN p_phase = 'PAGAMENTO_EM_VERIFICACAO' THEN 'payment_in_verification'
        WHEN p_phase = 'ENTREGADOR_CONFIRMOU_RECEBIMENTO' THEN 'receipt_confirmed'
        WHEN p_phase = 'SEM_ENTREGADOR' THEN 'no_driver'
        WHEN p_phase = 'CANCELADO' THEN 'cancelled'
        WHEN public._v2_phase_released(p_phase) THEN 'released'
        ELSE lower(p_phase)
    END
$function$;

-- @@ 50|function _validate_levels()
CREATE OR REPLACE FUNCTION public._validate_levels()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_first public.network_levels;
    v_prev_min integer := -1;
    r public.network_levels;
BEGIN
    SELECT * INTO v_first FROM public.network_levels WHERE is_active ORDER BY level_order LIMIT 1;
    IF v_first.id IS NULL THEN
        RAISE EXCEPTION 'É preciso ter pelo menos um nível ativo.';
    END IF;
    IF v_first.min_direct_referrals <> 0 THEN
        RAISE EXCEPTION 'O primeiro nível (inicial) precisa exigir 0 indicados — todo mundo começa nele.';
    END IF;
    FOR r IN SELECT * FROM public.network_levels WHERE is_active ORDER BY level_order LOOP
        IF r.min_direct_referrals < v_prev_min THEN
            RAISE EXCEPTION 'O nível "%" exige menos indicados do que o nível anterior. A quantidade precisa crescer (ou ficar igual) a cada nível.', r.name;
        END IF;
        v_prev_min := r.min_direct_referrals;
    END LOOP;
END $function$;

-- @@ 50|function _vehicle_slug_default()
CREATE OR REPLACE FUNCTION public._vehicle_slug_default()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.vehicle_slug IS NULL OR NEW.vehicle_slug = '' THEN
        NEW.vehicle_slug := public._build_vehicle_slug(NEW.car_model, NEW.car_plate, NEW.vehicle_kind, NEW.driver_id, NEW.id);
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function accrue_driver_postpaid_ride_fee()
CREATE OR REPLACE FUNCTION public.accrue_driver_postpaid_ride_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed'
       AND NEW.driver_id IS NOT NULL AND public.is_postpaid_user(NEW.driver_id) THEN
        INSERT INTO public.driver_postpaid_charges (driver_id, ride_request_id, type, amount)
        VALUES (NEW.driver_id, NEW.id, 'ride_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'ride_fee'))
        ON CONFLICT (ride_request_id) WHERE type = 'ride_fee' DO NOTHING;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function accrue_postpaid_appointment_fee()
CREATE OR REPLACE FUNCTION public.accrue_postpaid_appointment_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid;
BEGIN
    IF NEW.status = 'confirmed' AND OLD.status IS DISTINCT FROM 'confirmed' AND NEW.direction = 'outgoing' THEN
        IF NEW.store_id IS NOT NULL THEN
            SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
        ELSE
            v_owner := NEW.provider_profile_id;
        END IF;
        IF v_owner IS NOT NULL AND NEW.customer_id IS DISTINCT FROM v_owner AND public.is_postpaid_user(v_owner) THEN
            INSERT INTO public.driver_postpaid_charges (driver_id, appointment_id, type, amount)
            VALUES (v_owner, NEW.id, 'appointment_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'appointment_fee'))
            ON CONFLICT (appointment_id) WHERE type = 'appointment_fee' DO NOTHING;
        END IF;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function accrue_postpaid_order_fee()
CREATE OR REPLACE FUNCTION public.accrue_postpaid_order_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_owner uuid;
BEGIN
    IF NEW.status = 'paid' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'paid') THEN
        SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
        IF v_owner IS NOT NULL AND public.is_postpaid_user(v_owner) THEN
            IF NEW.buyer_id IS NULL THEN
                INSERT INTO public.driver_postpaid_charges (driver_id, order_id, type, amount)
                VALUES (v_owner, NEW.id, 'in_person_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'in_person_fee'))
                ON CONFLICT (order_id) WHERE type = 'in_person_fee' DO NOTHING;
            ELSE
                INSERT INTO public.driver_postpaid_charges (driver_id, order_id, type, amount)
                VALUES (v_owner, NEW.id, 'order_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'order_fee'))
                ON CONFLICT (order_id) WHERE type = 'order_fee' DO NOTHING;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function accrue_postpaid_product_fee()
CREATE OR REPLACE FUNCTION public.accrue_postpaid_product_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_owner uuid;
    v_type text;
BEGIN
    IF NEW.store_id IS NOT NULL THEN
        SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
    ELSE
        v_owner := NEW.owner_id;
    END IF;

    v_type := CASE NEW.listing_type
        WHEN 'publication' THEN 'publication_fee'
        WHEN 'service_offer' THEN 'service_listing_fee'
        ELSE 'product_fee'
    END;

    IF v_owner IS NOT NULL AND public.is_postpaid_user(v_owner) THEN
        INSERT INTO public.driver_postpaid_charges (driver_id, product_id, type, amount)
        VALUES (v_owner, NEW.id, v_type,
                COALESCE((SELECT postpaid_price FROM public.service_pricing WHERE service_type = v_type), 0.50))
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function accrue_postpaid_service_fee()
CREATE OR REPLACE FUNCTION public.accrue_postpaid_service_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status = 'accepted' AND OLD.status IS DISTINCT FROM 'accepted'
       AND public.is_postpaid_user(NEW.applicant_id) THEN
        INSERT INTO public.driver_postpaid_charges (driver_id, service_application_id, type, amount)
        VALUES (NEW.applicant_id, NEW.id, 'service_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'service_fee'))
        ON CONFLICT (service_application_id) WHERE type = 'service_fee' DO NOTHING;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function admin_clear_custom_commission(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.admin_clear_custom_commission(p_admin uuid, p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old public.user_network_state;
BEGIN
    SELECT * INTO v_old FROM public.user_network_state WHERE user_id = p_user FOR UPDATE;
    IF v_old.user_id IS NULL OR NOT v_old.custom_commission_enabled THEN
        RAISE EXCEPTION 'Essa pessoa não tem comissão personalizada ativa.';
    END IF;
    UPDATE public.user_network_state
       SET custom_commission_enabled = false, custom_commission_prepaid_bp = NULL, custom_commission_postpaid_bp = NULL, updated_at = now()
     WHERE user_id = p_user;
    PERFORM public._log(p_admin, p_user, 'custom_commission_cleared', 'user_network_state', NULL,
        jsonb_build_object('enabled', true, 'prepaid_bp', v_old.custom_commission_prepaid_bp, 'postpaid_bp', v_old.custom_commission_postpaid_bp), NULL, p_reason);
END $function$;

-- @@ 50|function admin_delete_profile(uuid)
CREATE OR REPLACE FUNCTION public.admin_delete_profile(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    s record;
BEGIN
    UPDATE public.profiles SET upline_id = NULL WHERE upline_id = p_user_id;
    FOR s IN SELECT id FROM public.stores WHERE owner_id = p_user_id LOOP
        PERFORM public.admin_delete_store(s.id);
    END LOOP;
    PERFORM public._purge_rows('public.profiles'::regclass, 'id', ARRAY[p_user_id::text]);
    DELETE FROM public.profiles WHERE id = p_user_id;
END;
$function$;

-- @@ 50|function admin_delete_store(uuid)
CREATE OR REPLACE FUNCTION public.admin_delete_store(p_store_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    PERFORM public._purge_rows('public.stores'::regclass, 'id', ARRAY[p_store_id::text]);
    DELETE FROM public.stores WHERE id = p_store_id;
END;
$function$;

-- @@ 50|function admin_get_user_graduation(uuid)
CREATE OR REPLACE FUNCTION public.admin_get_user_graduation(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_p record; v_s public.user_network_state; v_eff_pre jsonb; v_eff_pos jsonb; v_level public.network_levels; v_high public.network_levels; v_manual public.network_levels;
BEGIN
    SELECT id, name, email, "profileSlug" AS slug, avatar_url, created_at, upline_id INTO v_p FROM public.profiles WHERE id = p_user;
    IF v_p.id IS NULL THEN RAISE EXCEPTION 'Pessoa não encontrada.'; END IF;
    SELECT * INTO v_s FROM public.user_network_state WHERE user_id = p_user;
    v_eff_pre := public.get_effective_commission(p_user, 'prepaid');
    v_eff_pos := public.get_effective_commission(p_user, 'postpaid');
    SELECT * INTO v_level FROM public.network_levels WHERE id = (v_eff_pre ->> 'level_id')::uuid;
    SELECT * INTO v_high FROM public.network_levels WHERE id = v_s.highest_level_id;
    SELECT * INTO v_manual FROM public.network_levels WHERE id = v_s.manual_level_id;
    RETURN jsonb_build_object(
        'user', jsonb_build_object('id', v_p.id, 'name', v_p.name, 'email', v_p.email, 'profileSlug', v_p.slug, 'avatarUrl', v_p.avatar_url,
                                   'createdAt', v_p.created_at, 'uplineId', v_p.upline_id),
        'current_level', to_jsonb(v_level),
        'highest_level', CASE WHEN v_high.id IS NULL THEN NULL ELSE to_jsonb(v_high) END,
        'manual_level', CASE WHEN v_manual.id IS NULL THEN NULL ELSE to_jsonb(v_manual) END,
        'level_achieved_at', v_s.level_achieved_at,
        'direct_referrals', public._count_valid_directs(p_user),
        'total_network', public._count_network(p_user),
        'standard_prepaid_bp', v_level.commission_prepaid_bp,
        'standard_postpaid_bp', v_level.commission_postpaid_bp,
        'custom_enabled', COALESCE(v_s.custom_commission_enabled, false),
        'custom_prepaid_bp', v_s.custom_commission_prepaid_bp,
        'custom_postpaid_bp', v_s.custom_commission_postpaid_bp,
        'effective_prepaid', v_eff_pre,
        'effective_postpaid', v_eff_pos,
        'history', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('type', h.change_type, 'reason', h.reason, 'at', h.created_at,
                     'previous', pl.name, 'new', nl.name, 'by', cb.name) ORDER BY h.created_at DESC)
            FROM (SELECT * FROM public.user_level_history WHERE user_id = p_user ORDER BY created_at DESC LIMIT 20) h
            LEFT JOIN public.network_levels pl ON pl.id = h.previous_level_id
            LEFT JOIN public.network_levels nl ON nl.id = h.new_level_id
            LEFT JOIN public.profiles cb ON cb.id = h.changed_by
        ), '[]'::jsonb)
    );
END $function$;

-- @@ 50|function admin_grant_level(uuid,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.admin_grant_level(p_admin uuid, p_user uuid, p_level_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before uuid; v_after uuid; v_old uuid;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user) THEN RAISE EXCEPTION 'Pessoa não encontrada.'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.network_levels WHERE id = p_level_id AND is_active) THEN
        RAISE EXCEPTION 'Esse nível não existe ou está desativado.';
    END IF;
    INSERT INTO public.user_network_state (user_id) VALUES (p_user) ON CONFLICT DO NOTHING;
    v_before := public._effective_level_id(p_user);
    SELECT manual_level_id INTO v_old FROM public.user_network_state WHERE user_id = p_user FOR UPDATE;
    UPDATE public.user_network_state
       SET manual_level_id = p_level_id, level_achieved_at = COALESCE(level_achieved_at, now()), updated_at = now()
     WHERE user_id = p_user;
    v_after := public._effective_level_id(p_user);
    INSERT INTO public.user_level_history (user_id, previous_level_id, new_level_id, change_type, reason, changed_by)
    VALUES (p_user, v_before, v_after, 'manual_grant', NULLIF(btrim(COALESCE(p_reason, '')), ''), p_admin);
    PERFORM public._log(p_admin, p_user, 'level_granted', 'user_network_state', NULL, to_jsonb(v_old), to_jsonb(p_level_id), p_reason);
END $function$;

-- @@ 50|function admin_levels_overview()
CREATE OR REPLACE FUNCTION public.admin_levels_overview()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    WITH eff AS (SELECT public._effective_level_id(p.id) AS lid FROM public.profiles p),
         cnt AS (SELECT lid, count(*) AS n FROM eff GROUP BY lid)
    SELECT jsonb_build_object(
        'settings', (SELECT to_jsonb(s) FROM public.network_settings s WHERE id),
        'plans', (SELECT jsonb_agg(jsonb_build_object('code', code, 'name', name, 'price_cents', round(price * 100)::bigint)) FROM public.plans WHERE code IN ('pre_pago', 'pos_pago')),
        'levels', COALESCE((
            SELECT jsonb_agg(to_jsonb(l) || jsonb_build_object('users', COALESCE(c.n, 0)) ORDER BY l.level_order)
            FROM public.network_levels l LEFT JOIN cnt c ON c.lid = l.id
        ), '[]'::jsonb)
    );
$function$;

-- @@ 50|function admin_list_system_logs(uuid,integer)
CREATE OR REPLACE FUNCTION public.admin_list_system_logs(p_user uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', g.id, 'action', g.action, 'entity', g.entity, 'old', g.old_value, 'new', g.new_value, 'reason', g.reason,
        'at', g.created_at, 'actor', a.name, 'actorSlug', a."profileSlug", 'target', t.name, 'targetSlug', t."profileSlug"
    ) ORDER BY g.created_at DESC), '[]'::jsonb)
    FROM (SELECT * FROM public.system_logs WHERE p_user IS NULL OR target_user_id = p_user ORDER BY created_at DESC LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200)) g
    LEFT JOIN public.profiles a ON a.id = g.actor_id
    LEFT JOIN public.profiles t ON t.id = g.target_user_id;
$function$;

-- @@ 50|function admin_remove_manual_level(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.admin_remove_manual_level(p_admin uuid, p_user uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_before uuid; v_after uuid; v_old uuid;
BEGIN
    SELECT manual_level_id INTO v_old FROM public.user_network_state WHERE user_id = p_user FOR UPDATE;
    IF v_old IS NULL THEN RAISE EXCEPTION 'Essa pessoa não tem nível concedido manualmente.'; END IF;
    v_before := public._effective_level_id(p_user);
    UPDATE public.user_network_state SET manual_level_id = NULL, updated_at = now() WHERE user_id = p_user;
    v_after := public._effective_level_id(p_user);
    INSERT INTO public.user_level_history (user_id, previous_level_id, new_level_id, change_type, reason, changed_by)
    VALUES (p_user, v_before, v_after, 'admin_change', COALESCE(NULLIF(btrim(COALESCE(p_reason, '')), ''), 'Concessão manual removida'), p_admin);
    PERFORM public._log(p_admin, p_user, 'level_grant_removed', 'user_network_state', NULL, to_jsonb(v_old), NULL, p_reason);
END $function$;

-- @@ 50|function admin_reorder_levels(uuid,uuid[])
CREATE OR REPLACE FUNCTION public.admin_reorder_levels(p_admin uuid, p_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old jsonb;
BEGIN
    IF (SELECT count(*) FROM public.network_levels) <> COALESCE(array_length(p_ids, 1), 0)
       OR EXISTS (SELECT 1 FROM unnest(p_ids) i WHERE NOT EXISTS (SELECT 1 FROM public.network_levels WHERE id = i)) THEN
        RAISE EXCEPTION 'A nova ordem precisa conter todos os níveis, uma vez cada.';
    END IF;
    SELECT jsonb_agg(id ORDER BY level_order) INTO v_old FROM public.network_levels;
    UPDATE public.network_levels l SET level_order = o.ord
      FROM unnest(p_ids) WITH ORDINALITY AS o(id, ord) WHERE l.id = o.id;
    PERFORM public._validate_levels();
    PERFORM public._log(p_admin, NULL, 'levels_reordered', 'network_levels', NULL, v_old, to_jsonb(p_ids), NULL);
    PERFORM public.recheck_all_levels();
END $function$;

-- @@ 50|function admin_set_custom_commission(uuid,uuid,integer,integer,text)
CREATE OR REPLACE FUNCTION public.admin_set_custom_commission(p_admin uuid, p_user uuid, p_prepaid_bp integer, p_postpaid_bp integer, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_max integer; v_old public.user_network_state;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user) THEN RAISE EXCEPTION 'Pessoa não encontrada.'; END IF;
    IF p_prepaid_bp IS NULL AND p_postpaid_bp IS NULL THEN RAISE EXCEPTION 'Informe a comissão do pré-pago, do pós-pago ou das duas.'; END IF;
    SELECT max_commission_bp INTO v_max FROM public.network_settings WHERE id;
    IF p_prepaid_bp < 0 OR p_postpaid_bp < 0 OR p_prepaid_bp > v_max OR p_postpaid_bp > v_max THEN
        RAISE EXCEPTION 'A comissão personalizada precisa ficar entre 0%% e % %% (teto do sistema).', round(v_max / 100.0, 2);
    END IF;
    INSERT INTO public.user_network_state (user_id) VALUES (p_user) ON CONFLICT DO NOTHING;
    SELECT * INTO v_old FROM public.user_network_state WHERE user_id = p_user FOR UPDATE;
    UPDATE public.user_network_state
       SET custom_commission_enabled = true,
           custom_commission_prepaid_bp = p_prepaid_bp,
           custom_commission_postpaid_bp = p_postpaid_bp,
           updated_at = now()
     WHERE user_id = p_user;
    PERFORM public._log(p_admin, p_user, 'custom_commission_set', 'user_network_state', NULL,
        jsonb_build_object('enabled', v_old.custom_commission_enabled, 'prepaid_bp', v_old.custom_commission_prepaid_bp, 'postpaid_bp', v_old.custom_commission_postpaid_bp),
        jsonb_build_object('enabled', true, 'prepaid_bp', p_prepaid_bp, 'postpaid_bp', p_postpaid_bp), p_reason);
END $function$;

-- @@ 50|function admin_set_network_settings(uuid,integer,integer)
CREATE OR REPLACE FUNCTION public.admin_set_network_settings(p_admin uuid, p_max_bp integer, p_postpaid_reference_cents integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old public.network_settings; v_top integer;
BEGIN
    SELECT * INTO v_old FROM public.network_settings WHERE id FOR UPDATE;
    p_max_bp := COALESCE(p_max_bp, v_old.max_commission_bp);
    p_postpaid_reference_cents := COALESCE(p_postpaid_reference_cents, v_old.postpaid_reference_cents);
    IF p_max_bp < 0 OR p_max_bp > 10000 THEN RAISE EXCEPTION 'O teto precisa ficar entre 0%% e 100%%.'; END IF;
    IF p_postpaid_reference_cents <= 0 THEN RAISE EXCEPTION 'O valor de referência do pós-pago precisa ser positivo.'; END IF;
    SELECT GREATEST(max(commission_prepaid_bp), max(commission_postpaid_bp)) INTO v_top FROM public.network_levels;
    IF v_top > p_max_bp THEN
        RAISE EXCEPTION 'Existe nível com % %%. Reduza os níveis antes de baixar o teto para % %%.', round(v_top / 100.0, 2), round(p_max_bp / 100.0, 2);
    END IF;
    UPDATE public.network_settings SET max_commission_bp = p_max_bp, postpaid_reference_cents = p_postpaid_reference_cents,
                                       updated_at = now(), updated_by = p_admin WHERE id;
    PERFORM public._log(p_admin, NULL, 'network_settings_changed', 'network_settings', NULL,
                        to_jsonb(v_old), jsonb_build_object('max_commission_bp', p_max_bp, 'postpaid_reference_cents', p_postpaid_reference_cents), NULL);
END $function$;

-- @@ 50|function admin_update_delivery_settings(uuid,jsonb)
CREATE OR REPLACE FUNCTION public.admin_update_delivery_settings(p_admin uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    cur public.delivery_dispatch_settings;
    v_allowed text[] := ARRAY['retry_interval_minutes','increase_kind','increase_value','initial_radius_km','radius_step_km','max_freight','max_rounds','platform_fee_percent','min_freight','freight_rounding_step','freight_rounding_mode','max_radius_km','offer_duration_seconds','max_search_minutes','auto_increase_enabled','auto_increase_cap_amount','auto_increase_cap_percent','max_price_adjustments','price_adjust_interval_minutes','customer_authorization_timeout_minutes','search_strategy','reservation_timeout_minutes','reservation_expiry_action','driver_counter_enabled','driver_counter_max_amount','driver_counter_max_percent_over_offer','driver_counter_max_per_ride','cancel_customer_during_search','cancel_customer_during_reservation','cancel_driver_after_reservation','cancel_after_receipt_policy','cancel_reason_required','admin_review_after_payment','admin_review_after_pickup','admin_review_payment_dispute','block_driver_open_obligation','obligation_block_min_amount','obligation_unblock_on_settlement','obligation_unblock_needs_admin','new_delivery_flow_enabled'];
    v_bad text;
    v_filtered jsonb;
BEGIN
    IF p_admin IS NULL THEN RAISE EXCEPTION 'Administrador não informado' USING ERRCODE = '42501'; END IF;
    SELECT key INTO v_bad FROM jsonb_object_keys(p_changes) AS key WHERE key <> ALL (v_allowed) LIMIT 1;
    IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'Configuração desconhecida ou não editável: %', v_bad USING ERRCODE = '22023'; END IF;
    PERFORM set_config('app.config_admin', p_admin::text, true);
    SELECT * INTO cur FROM public.delivery_dispatch_settings WHERE id FOR UPDATE;
    UPDATE public.delivery_dispatch_settings s SET
        retry_interval_minutes = n.retry_interval_minutes,
        increase_kind = n.increase_kind,
        increase_value = n.increase_value,
        initial_radius_km = n.initial_radius_km,
        radius_step_km = n.radius_step_km,
        max_freight = n.max_freight,
        max_rounds = n.max_rounds,
        platform_fee_percent = n.platform_fee_percent,
        min_freight = n.min_freight,
        freight_rounding_step = n.freight_rounding_step,
        freight_rounding_mode = n.freight_rounding_mode,
        max_radius_km = n.max_radius_km,
        offer_duration_seconds = n.offer_duration_seconds,
        max_search_minutes = n.max_search_minutes,
        auto_increase_enabled = n.auto_increase_enabled,
        auto_increase_cap_amount = n.auto_increase_cap_amount,
        auto_increase_cap_percent = n.auto_increase_cap_percent,
        max_price_adjustments = n.max_price_adjustments,
        price_adjust_interval_minutes = n.price_adjust_interval_minutes,
        customer_authorization_timeout_minutes = n.customer_authorization_timeout_minutes,
        search_strategy = n.search_strategy,
        reservation_timeout_minutes = n.reservation_timeout_minutes,
        reservation_expiry_action = n.reservation_expiry_action,
        driver_counter_enabled = n.driver_counter_enabled,
        driver_counter_max_amount = n.driver_counter_max_amount,
        driver_counter_max_percent_over_offer = n.driver_counter_max_percent_over_offer,
        driver_counter_max_per_ride = n.driver_counter_max_per_ride,
        cancel_customer_during_search = n.cancel_customer_during_search,
        cancel_customer_during_reservation = n.cancel_customer_during_reservation,
        cancel_driver_after_reservation = n.cancel_driver_after_reservation,
        cancel_after_receipt_policy = n.cancel_after_receipt_policy,
        cancel_reason_required = n.cancel_reason_required,
        admin_review_after_payment = n.admin_review_after_payment,
        admin_review_after_pickup = n.admin_review_after_pickup,
        admin_review_payment_dispute = n.admin_review_payment_dispute,
        block_driver_open_obligation = n.block_driver_open_obligation,
        obligation_block_min_amount = n.obligation_block_min_amount,
        obligation_unblock_on_settlement = n.obligation_unblock_on_settlement,
        obligation_unblock_needs_admin = n.obligation_unblock_needs_admin,
        new_delivery_flow_enabled = n.new_delivery_flow_enabled
      FROM (SELECT (jsonb_populate_record(cur, p_changes)).*) n
     WHERE s.id;
    RETURN to_jsonb((SELECT s FROM public.delivery_dispatch_settings s WHERE s.id));
END;
$function$;

-- @@ 50|function admin_upsert_level(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.admin_upsert_level(p_admin uuid, p_id uuid, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_old public.network_levels;
    v_new public.network_levels;
    v_id uuid := p_id;
    v_colors text[];
    v_next_order integer;
BEGIN
    IF p_data ? 'requirements' AND p_data -> 'requirements' <> '{}'::jsonb THEN
        RAISE EXCEPTION 'Esse critério ainda não está disponível: hoje só a quantidade de indicados diretos vale.';
    END IF;
    IF p_data ? 'border_colors' THEN
        SELECT COALESCE(array_agg(c), '{}') INTO v_colors FROM jsonb_array_elements_text(p_data -> 'border_colors') c;
        IF EXISTS (SELECT 1 FROM unnest(v_colors) c WHERE c !~ '^#[0-9a-fA-F]{6}$') THEN
            RAISE EXCEPTION 'Cores da borda precisam estar no formato #RRGGBB.';
        END IF;
    END IF;

    IF p_id IS NULL THEN
        SELECT COALESCE(max(level_order), 0) + 1 INTO v_next_order FROM public.network_levels;
        INSERT INTO public.network_levels (name, level_order, commission_prepaid_bp, commission_postpaid_bp, min_direct_referrals,
                                           is_active, border_style, border_color, border_colors, background_style, badge_style, icon, description)
        VALUES (
            btrim(p_data ->> 'name'),
            COALESCE((p_data ->> 'level_order')::integer, v_next_order),
            (p_data ->> 'commission_prepaid_bp')::integer,
            COALESCE((p_data ->> 'commission_postpaid_bp')::integer, (p_data ->> 'commission_prepaid_bp')::integer),
            COALESCE((p_data ->> 'min_direct_referrals')::integer, 0),
            COALESCE((p_data ->> 'is_active')::boolean, true),
            COALESCE(p_data ->> 'border_style', 'solid'),
            COALESCE(p_data ->> 'border_color', '#94a3b8'),
            COALESCE(v_colors, '{}'),
            COALESCE(p_data ->> 'background_style', 'none'),
            COALESCE(p_data ->> 'badge_style', 'pill'),
            NULLIF(btrim(COALESCE(p_data ->> 'icon', '')), ''),
            NULLIF(btrim(COALESCE(p_data ->> 'description', '')), '')
        ) RETURNING id INTO v_id;
        SELECT * INTO v_new FROM public.network_levels WHERE id = v_id;
        PERFORM public._validate_levels();
        PERFORM public._log(p_admin, NULL, 'level_created', 'network_levels', v_id, NULL, to_jsonb(v_new), NULL);
    ELSE
        SELECT * INTO v_old FROM public.network_levels WHERE id = p_id FOR UPDATE;
        IF v_old.id IS NULL THEN RAISE EXCEPTION 'Nível não encontrado.'; END IF;
        UPDATE public.network_levels SET
            name = COALESCE(btrim(p_data ->> 'name'), name),
            commission_prepaid_bp = COALESCE((p_data ->> 'commission_prepaid_bp')::integer, commission_prepaid_bp),
            commission_postpaid_bp = COALESCE((p_data ->> 'commission_postpaid_bp')::integer, commission_postpaid_bp),
            min_direct_referrals = COALESCE((p_data ->> 'min_direct_referrals')::integer, min_direct_referrals),
            is_active = COALESCE((p_data ->> 'is_active')::boolean, is_active),
            border_style = COALESCE(p_data ->> 'border_style', border_style),
            border_color = COALESCE(p_data ->> 'border_color', border_color),
            border_colors = COALESCE(v_colors, border_colors),
            background_style = COALESCE(p_data ->> 'background_style', background_style),
            badge_style = COALESCE(p_data ->> 'badge_style', badge_style),
            icon = CASE WHEN p_data ? 'icon' THEN NULLIF(btrim(COALESCE(p_data ->> 'icon', '')), '') ELSE icon END,
            description = CASE WHEN p_data ? 'description' THEN NULLIF(btrim(COALESCE(p_data ->> 'description', '')), '') ELSE description END
        WHERE id = p_id;
        SELECT * INTO v_new FROM public.network_levels WHERE id = p_id;
        PERFORM public._validate_levels();
        PERFORM public._log(p_admin, NULL, 'level_updated', 'network_levels', p_id, to_jsonb(v_old), to_jsonb(v_new), NULL);
    END IF;

    PERFORM public.recheck_all_levels();   -- requisito mudou? quem já merece sobe (ninguém desce)
    RETURN v_id;
END $function$;

-- @@ 50|function apply_iuser_delivery_tariff()
CREATE OR REPLACE FUNCTION public.apply_iuser_delivery_tariff()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    t record;
BEGIN
    IF NEW.iuser_delivery_enabled AND NOT COALESCE(NEW.accepts_delivery, false) THEN
        NEW.iuser_delivery_enabled := false;
    END IF;
    IF NEW.iuser_delivery_enabled THEN
        SELECT base_distance_km, base_fee + extra_fee_objeto AS base_fee, price_per_km
          INTO t FROM public.platform_tariffs WHERE vehicle_kind = 'moto';
        IF FOUND THEN
            NEW.delivery_type := 'distance';
            NEW.delivery_fee := NULL;
            NEW.delivery_base_distance := t.base_distance_km;
            NEW.delivery_base_fee := t.base_fee;
            NEW.delivery_fee_per_km := t.price_per_km;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function audit_delivery_settings_change()
CREATE OR REPLACE FUNCTION public.audit_delivery_settings_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    k text;
    v_admin uuid := NULLIF(current_setting('app.config_admin', true), '')::uuid;
    o jsonb := to_jsonb(OLD);
    n jsonb := to_jsonb(NEW);
BEGIN
    FOR k IN SELECT key FROM jsonb_each(n) WHERE key <> 'updated_at' LOOP
        IF n->k IS DISTINCT FROM o->k THEN
            INSERT INTO public.admin_config_audit (scope, setting, old_value, new_value, changed_by)
            VALUES ('delivery_dispatch_settings', k, o->k, n->k, v_admin);
        END IF;
    END LOOP;
    NEW.updated_at := now();
    RETURN NEW;
END;
$function$;

-- @@ 50|function audit_dispatch_changes()
CREATE OR REPLACE FUNCTION public.audit_dispatch_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor uuid := auth.uid();
    v_role text := NULLIF(current_setting('app.delivery_actor', true), '');
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_to, actor_id, actor_role, data, processed_at)
        VALUES (NEW.id, 'estimate_recorded', NEW.phase, v_actor, COALESCE(v_role, 'system'),
                jsonb_build_object('estimated_freight', NEW.estimated_freight, 'original_freight', CASE WHEN NEW.flow_version = 1 THEN NEW.original_freight END,
                                   'radius_km', NEW.radius_km, 'flow_version', NEW.flow_version, 'estimate_id', NEW.estimate_id,
                                   'order_id', NEW.order_id,
                                   'calculation_version', (SELECT e.calculation_version FROM public.delivery_estimates e WHERE e.id = NEW.estimate_id),
                                   'estimate_snapshot', (SELECT e.snapshot FROM public.delivery_estimates e WHERE e.id = NEW.estimate_id)), now());
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_from, phase_to, actor_id, actor_role, data, processed_at)
        VALUES (NEW.id, 'phase_change', NULL, NEW.phase, v_actor, COALESCE(v_role, 'system'),
                jsonb_build_object('status', NEW.status, 'stage', NEW.stage, 'flow_version', NEW.flow_version), now());
        RETURN NEW;
    END IF;

    IF NEW.phase IS DISTINCT FROM OLD.phase THEN
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_from, phase_to, actor_id, actor_role, data, processed_at)
        VALUES (NEW.id, CASE WHEN NEW.phase = 'CANCELADO' THEN 'cancelled' ELSE 'phase_change' END, OLD.phase, NEW.phase, v_actor, COALESCE(v_role, 'system'),
                jsonb_build_object('status', NEW.status, 'stage', NEW.stage, 'flow_version', NEW.flow_version), now());
    END IF;
    IF NEW.frozen_freight IS NOT NULL AND OLD.frozen_freight IS NULL THEN
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_to, actor_id, actor_role, data, processed_at)
        VALUES (NEW.id, 'freight_frozen', NEW.phase, v_actor, COALESCE(v_role, 'system'),
                jsonb_build_object('frozen_freight', NEW.frozen_freight, 'estimated_freight', NEW.estimated_freight, 'authorized_extra', NEW.authorized_extra), now());
    END IF;
    IF NEW.reserved_at IS NOT NULL AND NEW.reserved_at IS DISTINCT FROM OLD.reserved_at THEN
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_to, actor_id, actor_role, data, processed_at)
        VALUES (NEW.id, 'driver_reserved', NEW.phase, v_actor, COALESCE(v_role, 'system'),
                jsonb_build_object('reserved_until', NEW.reserved_until, 'frozen_freight', NEW.frozen_freight,
                                   'driver_id', (SELECT driver_id FROM public.ride_requests WHERE id = NEW.ride_request_id)), now());
    END IF;
    IF NEW.reservation_released_at IS NOT NULL AND NEW.reservation_released_at IS DISTINCT FROM OLD.reservation_released_at THEN
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_to, actor_id, actor_role, data, processed_at)
        VALUES (NEW.id, 'reservation_released', NEW.phase, v_actor, COALESCE(v_role, 'system'),
                jsonb_build_object('reason', NEW.reservation_release_reason, 'released_frozen_freight', OLD.frozen_freight,
                                   'driver_id', (SELECT driver_id FROM public.ride_requests WHERE id = NEW.ride_request_id)), now());
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function auto_accept_store_delivery_application()
CREATE OR REPLACE FUNCTION public.auto_accept_store_delivery_application()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_offered numeric;
    v_order uuid;
    v_updated integer;
BEGIN
    SELECT offered_price, order_id INTO v_offered, v_order FROM public.ride_requests WHERE id = NEW.ride_request_id;
    IF v_order IS NOT NULL AND v_offered IS NOT NULL AND NEW.proposed_price = v_offered THEN
        UPDATE public.ride_requests
        SET status = 'accepted', driver_id = NEW.applicant_id
        WHERE id = NEW.ride_request_id AND status = 'pending';
        GET DIAGNOSTICS v_updated = ROW_COUNT;
        IF v_updated > 0 THEN
            UPDATE public.ride_applications SET status = 'accepted' WHERE id = NEW.id;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function bind_upline(uuid,uuid)
CREATE OR REPLACE FUNCTION public.bind_upline(p_user_id uuid, p_upline_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Atualizar o upline_id do usuário
    UPDATE profiles 
    SET upline_id = p_upline_id
    WHERE id = p_user_id;
    
    RETURN TRUE;
END;
$function$;

-- @@ 50|function block_appointment_for_store_in_debt()
CREATE OR REPLACE FUNCTION public.block_appointment_for_store_in_debt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid;
BEGIN
    IF NEW.store_id IS NULL OR NEW.direction IS DISTINCT FROM 'outgoing' THEN RETURN NEW; END IF;
    SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
    IF v_owner IS NOT NULL AND NEW.customer_id IS DISTINCT FROM v_owner
       AND public.get_driver_postpaid_debt(v_owner) >= 50 THEN
        RAISE EXCEPTION 'Esta loja está temporariamente sem receber agendamentos.';
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function block_orders_for_store_in_debt()
CREATE OR REPLACE FUNCTION public.block_orders_for_store_in_debt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_owner uuid;
BEGIN
    SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
    IF v_owner IS NOT NULL AND public.get_driver_postpaid_debt(v_owner) >= 50 THEN
        IF NEW.buyer_id IS NULL THEN
            RAISE EXCEPTION 'Sua dívida do pós-pago chegou a R$ 50. Quite pra registrar vendas presenciais.';
        END IF;
        RAISE EXCEPTION 'Esta loja está temporariamente sem receber novos pedidos.';
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function block_product_for_store_in_debt()
CREATE OR REPLACE FUNCTION public.block_product_for_store_in_debt()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid;
BEGIN
    IF NEW.store_id IS NOT NULL THEN
        SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
    ELSE
        v_owner := NEW.owner_id;
    END IF;
    IF v_owner IS NOT NULL AND public.get_driver_postpaid_debt(v_owner) >= 50 THEN
        RAISE EXCEPTION 'Sua dívida do pós-pago chegou a R$ 50. Quite pra cadastrar produtos e publicações.';
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function bump_ride_applicant_count()
CREATE OR REPLACE FUNCTION public.bump_ride_applicant_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE public.ride_requests SET applicant_count = applicant_count + 1 WHERE id = NEW.ride_request_id;
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE public.ride_requests SET applicant_count = GREATEST(0, applicant_count - 1) WHERE id = OLD.ride_request_id;
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function calculate_commissions(uuid)
CREATE OR REPLACE FUNCTION public.calculate_commissions(user_id uuid)
 RETURNS TABLE(total_indicados bigint, comissao_total numeric, comissao_nivel1 numeric, comissao_nivel2 numeric, comissao_nivel3 numeric, comissao_breakaway numeric)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_comissao_total DECIMAL := 0;
    v_comissao_n1 DECIMAL := 0;
    v_comissao_n2 DECIMAL := 0;
    v_comissao_n3 DECIMAL := 0;
    v_comissao_breakaway DECIMAL := 0;
    v_indicado RECORD;
    v_downline_count INTEGER;
BEGIN
    -- Percorrer todos os indicados diretos
    FOR v_indicado IN 
        SELECT 
            p.id,
            p.view_count as volume,
            (SELECT COUNT(*) FROM profiles WHERE upline_id = p.id) as downline_count
        FROM profiles p
        WHERE p.upline_id = user_id
    LOOP
        -- Comissão Nível 1: 15% do volume do indicado direto
        v_comissao_n1 := v_comissao_n1 + (v_indicado.volume * 0.15);
        
        -- Se o indicado tem mais de 5 pessoas na rede, é líder (breakaway)
        IF v_indicado.downline_count >= 5 THEN
            -- Breakaway: 3% do volume total da rede do indicado
            v_comissao_breakaway := v_comissao_breakaway + 
                (COALESCE((SELECT SUM(view_count) FROM profiles WHERE upline_id = v_indicado.id), 0) * 0.03);
        END IF;
    END LOOP;
    
    -- Nível 2: 10% dos indicados dos indicados
    FOR v_indicado IN 
        SELECT p.view_count as volume
        FROM profiles p
        WHERE p.upline_id IN (SELECT id FROM profiles WHERE upline_id = user_id)
    LOOP
        v_comissao_n2 := v_comissao_n2 + (v_indicado.volume * 0.10);
    END LOOP;
    
    -- Nível 3: 7% dos indicados dos indicados dos indicados
    FOR v_indicado IN 
        SELECT p.view_count as volume
        FROM profiles p
        WHERE p.upline_id IN (
            SELECT id FROM profiles 
            WHERE upline_id IN (SELECT id FROM profiles WHERE upline_id = user_id)
        )
    LOOP
        v_comissao_n3 := v_comissao_n3 + (v_indicado.volume * 0.07);
    END LOOP;
    
    -- Total
    v_comissao_total := v_comissao_n1 + v_comissao_n2 + v_comissao_n3 + v_comissao_breakaway;
    
    RETURN QUERY
    SELECT 
        (SELECT COUNT(*) FROM profiles WHERE upline_id = user_id) as total_indicados,
        v_comissao_total as comissao_total,
        v_comissao_n1 as comissao_nivel1,
        v_comissao_n2 as comissao_nivel2,
        v_comissao_n3 as comissao_nivel3,
        v_comissao_breakaway as comissao_breakaway;
END;
$function$;

-- @@ 50|function calculate_user_level(uuid)
CREATE OR REPLACE FUNCTION public.calculate_user_level(user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_level INTEGER := 0;
    v_current_id UUID := user_id;
    v_upline_id UUID;
BEGIN
    LOOP
        SELECT upline_id INTO v_upline_id
        FROM public.profiles
        WHERE id = v_current_id;
        
        IF v_upline_id IS NULL THEN
            EXIT;
        END IF;
        
        v_level := v_level + 1;
        v_current_id := v_upline_id;
    END LOOP;
    
    RETURN v_level;
END;
$function$;

-- @@ 50|function can_act_on_user(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.can_act_on_user(p_actor uuid, p_target uuid, p_permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_scope text;
BEGIN
    v_scope := public.get_permission_scope(p_actor, p_permission);
    IF v_scope IS NULL THEN RETURN false; END IF;
    RETURN public.is_in_scope(p_actor, p_target, v_scope);
END;
$function$;

-- @@ 50|function can_apply_to_ride(uuid)
CREATE OR REPLACE FUNCTION public.can_apply_to_ride(p_ride uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.ride_requests rr
        WHERE rr.id = p_ride AND rr.status = 'pending' AND rr.requester_id <> auth.uid() AND rr.applicant_count < 5
    )
$function$;

-- @@ 50|function can_grant_plan(uuid,uuid)
CREATE OR REPLACE FUNCTION public.can_grant_plan(p_actor uuid, p_plan_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
