$function$;

-- @@ 50|function cancel_order_delivery(uuid)
CREATE OR REPLACE FUNCTION public.cancel_order_delivery(p_dispatch uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    d public.order_delivery_dispatches;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.customer_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
    -- V2 com motorista reservado e ainda sem pagamento: o cliente pode cancelar se o admin permitir; o motorista é liberado e não nasce cobrança
    IF d.flow_version = 2 AND d.status = 'accepted' AND d.phase IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE') THEN
        IF NOT (SELECT cancel_customer_during_reservation FROM public.delivery_dispatch_settings WHERE id) THEN
            RAISE EXCEPTION 'O cancelamento durante a reserva não está liberado' USING ERRCODE = '42501';
        END IF;
        PERFORM public._v2_release_reservation(d.id, 'customer_cancelled', 'cancel');
        RETURN;
    END IF;
    IF d.flow_version = 2 AND d.status = 'accepted' AND public._v2_phase_money(d.phase) THEN
        RAISE EXCEPTION 'Há pagamento informado nesta entrega: o cancelamento simples não é possível. Abra uma ocorrência.' USING ERRCODE = '42501', HINT = 'cancel_blocked_after_payment';
    END IF;
    IF d.status <> 'searching' THEN RAISE EXCEPTION 'A entrega já tem motorista ou foi encerrada'; END IF;
    UPDATE public.ride_requests SET status = 'cancelled', cancelled_by = 'requester' WHERE id = d.ride_request_id AND status = 'pending';
    UPDATE public.order_delivery_rounds SET status = 'expired' WHERE dispatch_id = d.id AND status = 'pending_customer';
    UPDATE public.order_delivery_dispatches SET status = 'cancelled', updated_at = now() WHERE id = d.id;
END;
$function$;

-- @@ 50|function charge_profile_scheduling_activation()
CREATE OR REPLACE FUNCTION public.charge_profile_scheduling_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    NEW.scheduling_activated_at := OLD.scheduling_activated_at;

    IF NEW.allow_scheduling IS TRUE AND OLD.allow_scheduling IS NOT TRUE THEN
        IF public.get_driver_postpaid_debt(NEW.id) >= 50 THEN
            RAISE EXCEPTION 'Sua dívida do pós-pago chegou a R$ 50. Quite pra ativar a agenda.';
        END IF;
    END IF;

    IF NEW.allow_scheduling IS TRUE AND NEW.scheduling_activated_at IS NULL THEN
        IF public.is_postpaid_user(NEW.id) THEN
            INSERT INTO public.driver_postpaid_charges (driver_id, type, amount)
            VALUES (NEW.id, 'schedule_activation_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'schedule_activation_fee'))
            ON CONFLICT (driver_id) WHERE type = 'schedule_activation_fee' AND store_id IS NULL DO NOTHING;
        END IF;
        NEW.scheduling_activated_at := now();
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function charge_store_scheduling_activation()
CREATE OR REPLACE FUNCTION public.charge_store_scheduling_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    NEW.scheduling_activated_at := OLD.scheduling_activated_at;

    IF NEW.allow_scheduling IS TRUE AND NEW.scheduling_activated_at IS NULL THEN
        IF NEW.owner_id IS NOT NULL AND public.is_postpaid_user(NEW.owner_id) THEN
            IF public.get_driver_postpaid_debt(NEW.owner_id) >= 50 THEN
                RAISE EXCEPTION 'Sua dívida do pós-pago chegou a R$ 50. Quite pra ativar a agenda.';
            END IF;
            INSERT INTO public.driver_postpaid_charges (driver_id, store_id, type, amount)
            VALUES (NEW.owner_id, NEW.id, 'schedule_activation_fee', (SELECT postpaid_price FROM public.service_pricing WHERE service_type = 'schedule_activation_fee'))
            ON CONFLICT (store_id) WHERE type = 'schedule_activation_fee' DO NOTHING;
        END IF;
        NEW.scheduling_activated_at := now();
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function check_and_upgrade_user_level(uuid)
CREATE OR REPLACE FUNCTION public.check_and_upgrade_user_level(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_state public.user_network_state;
    v_base_order integer;
    v_prev uuid;
    v_level public.network_levels;
    v_new uuid;
    v_directs integer;
BEGIN
    IF p_user IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_user) THEN
        RETURN jsonb_build_object('upgraded', false);
    END IF;

    INSERT INTO public.user_network_state (user_id) VALUES (p_user) ON CONFLICT DO NOTHING;
    SELECT * INTO v_state FROM public.user_network_state WHERE user_id = p_user FOR UPDATE;

    v_directs := public._count_valid_directs(p_user);
    -- Ponto de partida: o conquistado (ou o inicial). Só olhamos níveis ACIMA dele.
    v_prev := COALESCE(v_state.highest_level_id, public._initial_level_id());
    SELECT level_order INTO v_base_order FROM public.network_levels WHERE id = v_prev;

    FOR v_level IN
        SELECT * FROM public.network_levels
         WHERE is_active AND level_order > COALESCE(v_base_order, 0)
         ORDER BY level_order
    LOOP
        EXIT WHEN NOT public._level_requirements_met(p_user, v_level);   -- os níveis atingidos formam um prefixo da escada
        INSERT INTO public.user_level_history (user_id, previous_level_id, new_level_id, change_type, reason)
        VALUES (p_user, v_prev, v_level.id, 'automatic_upgrade', format('Chegou a %s indicações diretas válidas', v_directs));
        v_prev := v_level.id;
        v_new := v_level.id;
    END LOOP;

    IF v_new IS NOT NULL THEN
        UPDATE public.user_network_state
           SET highest_level_id = v_new, level_achieved_at = now(), updated_at = now()
         WHERE user_id = p_user;
        PERFORM public._log(NULL, p_user, 'level_auto_upgrade', 'user_network_state', NULL,
                            to_jsonb(v_state.highest_level_id), to_jsonb(v_new), format('%s indicações diretas válidas', v_directs));
    END IF;

    RETURN jsonb_build_object('upgraded', v_new IS NOT NULL, 'level_id', v_new, 'directs', v_directs);
END $function$;

-- @@ 50|function check_follows_following_id()
CREATE OR REPLACE FUNCTION public.check_follows_following_id()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.following_id)
       AND NOT EXISTS (SELECT 1 FROM public.stores WHERE id = NEW.following_id) THEN
        RAISE EXCEPTION 'following_id % não corresponde a nenhum perfil ou loja', NEW.following_id;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function check_store_open(jsonb)
CREATE OR REPLACE FUNCTION public.check_store_open(business_hours jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    today_key text;
    today_hours jsonb;
    curr_time time;
    open_time time;
    close_time time;
BEGIN
    today_key := CASE EXTRACT(DOW FROM NOW())
        WHEN 0 THEN 'sun'
        WHEN 1 THEN 'mon'
        WHEN 2 THEN 'tue'
        WHEN 3 THEN 'wed'
        WHEN 4 THEN 'thu'
        WHEN 5 THEN 'fri'
        WHEN 6 THEN 'sat'
    END;
    
    today_hours := business_hours -> today_key;
    
    IF today_hours IS NULL THEN
        RETURN false;
    END IF;
    
    curr_time := CURRENT_TIME;
    open_time := (today_hours ->> 'open')::time;
    close_time := (today_hours ->> 'close')::time;
    
    IF open_time IS NULL OR close_time IS NULL THEN
        RETURN false;
    END IF;
    
    IF close_time = '00:00:00'::time THEN
        RETURN curr_time >= open_time;
    ELSE
        RETURN curr_time >= open_time AND curr_time <= close_time;
    END IF;
END;
$function$;

-- @@ 50|function claim_avatar_border(text)
CREATE OR REPLACE FUNCTION public.claim_avatar_border(p_slug text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user uuid := auth.uid();
    v_id uuid;
    v_reason text;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra resgatar'; END IF;
    SELECT id INTO v_id FROM public.avatar_borders WHERE slug = p_slug AND is_active;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Essa borda não está disponível'; END IF;
    v_reason := public._avatar_border_block_reason(v_user, v_id);
    IF v_reason IS NOT NULL THEN RAISE EXCEPTION '%', v_reason; END IF;
    INSERT INTO public.user_avatar_borders (profile_id, border_id, source) VALUES (v_user, v_id, 'claim') ON CONFLICT DO NOTHING;
    RETURN v_id;
END; $function$;

-- @@ 50|function close_all_community_rounds()
CREATE OR REPLACE FUNCTION public.close_all_community_rounds()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; n integer := 0;
BEGIN
    FOR c IN
        SELECT DISTINCT cand.community_id
        FROM public.community_photo_candidates cand
        WHERE cand.outcome IS NULL AND cand.round_day < public._community_today(cand.community_id)
    LOOP
        PERFORM public._community_close_rounds(c.community_id);
        n := n + 1;
    END LOOP;
    RETURN n;
END; $function$;

-- @@ 50|function commission_cents(bigint,integer)
CREATE OR REPLACE FUNCTION public.commission_cents(p_base_cents bigint, p_rate_bp integer)
 RETURNS bigint
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT (p_base_cents * p_rate_bp + 5000) / 10000;
$function$;

-- @@ 50|function complete_ride(uuid,double precision,double precision)
CREATE OR REPLACE FUNCTION public.complete_ride(p_ride uuid, p_lat double precision, p_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    r public.ride_requests;
    v_m numeric;
BEGIN
    SELECT * INTO r FROM public.ride_requests WHERE id = p_ride FOR UPDATE;
    IF NOT FOUND OR r.driver_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF r.status <> 'accepted' THEN RAISE EXCEPTION 'Essa corrida não está em andamento'; END IF;
    IF r.ride_started_at IS NULL THEN RAISE EXCEPTION 'Inicie a corrida antes de concluir.'; END IF;
    IF r.destination_lat IS NULL OR r.destination_lng IS NULL THEN
        RAISE EXCEPTION 'Não dá pra confirmar a chegada: esse pedido não tem coordenadas de destino.';
    END IF;
    IF p_lat IS NULL OR p_lng IS NULL THEN RAISE EXCEPTION 'Não conseguimos confirmar sua localização.'; END IF;
    v_m := public.haversine_km(r.destination_lat, r.destination_lng, p_lat, p_lng) * 1000;
    IF v_m > 100 THEN
        RAISE EXCEPTION 'Você está a % m do destino. Chegue a até 100 m pra concluir.', round(v_m);
    END IF;
    IF r.order_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.orders WHERE id = r.order_id AND status = 'rejected') THEN
        RAISE EXCEPTION 'O pedido desta entrega foi recusado';
    END IF;

    -- (o gatilho existente exige as paradas concluídas; e o de R$ 0,50 / sync da entrega disparam como sempre)
    UPDATE public.ride_requests SET status = 'completed' WHERE id = p_ride AND status = 'accepted';
    RETURN jsonb_build_object('ok', true);
END;
$function$;

-- @@ 50|function complete_service_application(uuid)
CREATE OR REPLACE FUNCTION public.complete_service_application(p_application uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); a public.service_applications; r public.service_requests;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    SELECT * INTO a FROM public.service_applications WHERE id = p_application;
    IF NOT FOUND THEN RAISE EXCEPTION 'Candidatura não encontrada'; END IF;
    SELECT * INTO r FROM public.service_requests WHERE id = a.service_request_id;
    IF r.requester_id <> v_user THEN RAISE EXCEPTION 'Só quem pediu o serviço pode marcá-lo como feito'; END IF;
    IF a.status <> 'accepted' THEN RAISE EXCEPTION 'Esse profissional ainda não foi escolhido'; END IF;
    IF a.completed_at IS NOT NULL THEN RETURN true; END IF;

    UPDATE public.service_applications SET completed_at = now() WHERE id = a.id;
    UPDATE public.service_requests SET status = 'completed'
    WHERE id = r.id AND NOT EXISTS (
        SELECT 1 FROM public.service_applications x WHERE x.service_request_id = r.id AND x.status = 'accepted' AND x.completed_at IS NULL
    );
    BEGIN
        PERFORM public._notify(a.applicant_id, 'service_completed', v_user, r.id,
            jsonb_build_object('title', public._service_request_title(r.id)), 'svcdone:' || a.id);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN true;
END; $function$;

-- @@ 50|function complete_transaction(uuid,text,jsonb)
CREATE OR REPLACE FUNCTION public.complete_transaction(p_transaction_id uuid, p_external_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID;
    v_amount DECIMAL;
    v_type TEXT;
    v_balance_before DECIMAL;
    v_balance_after DECIMAL;
BEGIN
    -- Buscar dados da transação
    SELECT 
        user_id,
        amount,
        type,
        balance_before
    INTO 
        v_user_id,
        v_amount,
        v_type,
        v_balance_before
    FROM public.transactions
    WHERE id = p_transaction_id AND status = 'PENDING';
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Transação não encontrada ou já processada';
    END IF;
    
    -- Calcular saldo após
    CASE v_type
        WHEN 'DEPOSIT', 'COMMISSION', 'REFUND', 'BONUS' THEN
            v_balance_after := COALESCE(v_balance_before, 0) + v_amount;
        WHEN 'WITHDRAWAL', 'PAYMENT' THEN
            v_balance_after := COALESCE(v_balance_before, 0) - v_amount;
        ELSE
            v_balance_after := COALESCE(v_balance_before, 0);
    END CASE;
    
    -- Atualizar transação
    UPDATE public.transactions
    SET 
        status = 'COMPLETED',
        completed_at = NOW(),
        external_id = COALESCE(p_external_id, external_id),
        balance_after = v_balance_after,
        metadata = metadata || p_metadata,
        updated_at = NOW()
    WHERE id = p_transaction_id;
    
    RETURN FOUND;
END;
$function$;

-- @@ 50|function confirm_appointment(uuid)
CREATE OR REPLACE FUNCTION public.confirm_appointment(incoming_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  incoming_record appointments%ROWTYPE;
BEGIN
  -- Seleciona o registro incoming
  SELECT * INTO incoming_record FROM appointments WHERE id = incoming_id AND direction = 'incoming' AND status = 'pending';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Convite não encontrado ou já confirmado/recusado';
  END IF;

  -- Atualiza o incoming para confirmed
  UPDATE appointments SET status = 'confirmed', updated_at = NOW() WHERE id = incoming_id;

  -- Atualiza o registro outgoing correspondente do remetente (mesmo store_id, date, time, owner_id)
  UPDATE appointments
  SET status = 'confirmed', updated_at = NOW()
  WHERE store_id = incoming_record.store_id
    AND date = incoming_record.date
    AND time = incoming_record.time
    AND owner_id = incoming_record.owner_id
    AND customer_id = incoming_record.owner_id
    AND direction = 'outgoing'
    AND status = 'pending';
END;
$function$;

-- @@ 50|function consume_campaign_code(text,uuid,text)
CREATE OR REPLACE FUNCTION public.consume_campaign_code(p_code text, p_order_id uuid, p_via text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_updated integer;
BEGIN
    IF p_via NOT IN ('cart', 'in_person') THEN
        RAISE EXCEPTION 'Via inválida';
    END IF;

    UPDATE public.store_campaign_redemptions
        SET status = 'redeemed', redeemed_at = now(), redeemed_via = p_via, order_id = p_order_id
        WHERE code = upper(trim(p_code)) AND status = 'available';

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN v_updated > 0;
END;
$function$;

-- @@ 50|function count_downline(uuid)
CREATE OR REPLACE FUNCTION public.count_downline(user_id uuid)
 RETURNS TABLE(total_diretos bigint, total_indiretos bigint, total_geral bigint, total_lideres bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        (SELECT COUNT(*) FROM profiles WHERE upline_id = user_id) as total_diretos,
        (SELECT COUNT(*) FROM profiles WHERE upline_id IN (SELECT id FROM profiles WHERE upline_id = user_id)) as total_indiretos,
        (SELECT COUNT(*) FROM profiles WHERE upline_id = user_id OR upline_id IN (SELECT id FROM profiles WHERE upline_id = user_id)) as total_geral,
        (SELECT COUNT(*) FROM profiles WHERE upline_id = user_id AND (SELECT COUNT(*) FROM profiles WHERE upline_id = profiles.id) >= 5) as total_lideres;
END;
$function$;

-- @@ 50|function create_community(text,text,text,text,boolean,text,text)
CREATE OR REPLACE FUNCTION public.create_community(p_name text, p_description text, p_scope text, p_place text, p_listed boolean, p_password text, p_image_url text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_user uuid := auth.uid(); v_slug text; v_base text; v_try int := 0; v_id uuid; v_count int;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra criar uma comunidade'; END IF;
    IF btrim(COALESCE(p_name, '')) = '' THEN RAISE EXCEPTION 'Dê um nome à comunidade'; END IF;
    IF p_scope NOT IN ('city', 'state', 'country') THEN RAISE EXCEPTION 'Escolha onde a comunidade aparece'; END IF;
    IF btrim(COALESCE(p_place, '')) = '' THEN RAISE EXCEPTION 'Não achei o lugar. Defina seu local primeiro'; END IF;
    SELECT count(*) INTO v_count FROM public.communities WHERE creator_id = v_user AND kind = 'custom';
    IF v_count >= 3 THEN RAISE EXCEPTION 'Você já criou o máximo de 3 comunidades'; END IF;

    v_base := regexp_replace(lower(public.unaccent(btrim(p_name))), '[^a-z0-9]+', '-', 'g');
    v_base := btrim(v_base, '-');
    IF v_base = '' THEN v_base := 'comunidade'; END IF;
    v_slug := v_base;
    WHILE EXISTS (SELECT 1 FROM public.communities WHERE slug = v_slug) LOOP
        v_try := v_try + 1;
        v_slug := v_base || '-' || (v_try + 1);
    END LOOP;

    INSERT INTO public.communities (slug, name, city, description, creator_id, scope, is_listed, requires_password, image_url, kind)
    VALUES (v_slug, btrim(p_name), btrim(p_place), NULLIF(btrim(COALESCE(p_description, '')), ''), v_user, p_scope,
            COALESCE(p_listed, true), COALESCE(btrim(p_password), '') <> '', NULLIF(p_image_url, ''), 'custom')
    RETURNING id INTO v_id;

    IF COALESCE(btrim(p_password), '') <> '' THEN
        INSERT INTO public.community_secrets (community_id, password_hash) VALUES (v_id, crypt(btrim(p_password), gen_salt('bf')));
    END IF;
    INSERT INTO public.community_members (community_id, profile_id) VALUES (v_id, v_user);
    RETURN v_slug;
END; $function$;

-- @@ 50|function create_delivery_counter(uuid,uuid,numeric)
CREATE OR REPLACE FUNCTION public.create_delivery_counter(p_ride uuid, p_driver uuid, p_amount numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    d public.order_delivery_dispatches;
    cfg public.delivery_dispatch_settings;
    r record;
    dp record;
    v_platform numeric;
    v_id uuid;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE ride_request_id = p_ride FOR UPDATE;
    IF NOT FOUND OR d.status <> 'searching' THEN RAISE EXCEPTION 'Essa entrega não está mais em busca'; END IF;
    IF d.flow_version = 2 THEN
        RAISE EXCEPTION 'A contraproposta ("Minha tarifa") ainda não está disponível no novo fluxo de entregas' USING ERRCODE = '42501';
    END IF;
    SELECT requester_id, status, origin_lat, origin_lng, visible_radius_km INTO r FROM public.ride_requests WHERE id = p_ride;
    IF r.status <> 'pending' THEN RAISE EXCEPTION 'Essa entrega não está mais disponível'; END IF;
    IF r.requester_id = p_driver THEN RAISE EXCEPTION 'Você não pode propor na sua própria entrega'; END IF;

    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    IF p_amount <= d.final_freight THEN RAISE EXCEPTION 'A sua tarifa não é maior que o frete oferecido: aceite o frete'; END IF;
    IF p_amount > cfg.max_freight THEN RAISE EXCEPTION 'Valor acima do máximo permitido para entregas'; END IF;

    IF NOT (SELECT has_driver FROM public.get_active_plan_grants(p_driver)) THEN RAISE EXCEPTION 'Você precisa do plano de motorista'; END IF;
    IF public.get_driver_postpaid_debt(p_driver) >= 50 THEN RAISE EXCEPTION 'Quite sua pendência para aceitar corridas'; END IF;

    SELECT live_lat, live_lng, live_updated_at, delivery_radius_km INTO dp FROM public.driver_pricing WHERE driver_id = p_driver;
    IF r.visible_radius_km IS NOT NULL AND r.origin_lat IS NOT NULL AND dp.live_lat IS NOT NULL AND dp.live_updated_at > now() - interval '30 minutes'
       AND public.haversine_km(r.origin_lat, r.origin_lng, dp.live_lat, dp.live_lng) > LEAST(r.visible_radius_km, COALESCE(dp.delivery_radius_km, r.visible_radius_km)) THEN
        RAISE EXCEPTION 'Essa entrega está fora do seu raio' USING ERRCODE = '42501';
    END IF;

    v_platform := round(p_amount * cfg.platform_fee_percent / 100, 2);
    INSERT INTO public.order_delivery_counters (dispatch_id, driver_id, amount, platform_fee, driver_offer)
    VALUES (d.id, p_driver, p_amount, v_platform, p_amount - v_platform)
    RETURNING id INTO v_id;
    RETURN v_id;
EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'Você já enviou uma proposta para essa entrega';
END;
$function$;

-- @@ 50|function create_group_conversation(text,uuid[])
CREATE OR REPLACE FUNCTION public.create_group_conversation(p_title text, p_members uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user uuid := auth.uid(); v_id uuid; v_title text := btrim(COALESCE(p_title, ''));
    v_members uuid[]; m uuid;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra criar um grupo'; END IF;
    IF char_length(v_title) < 1 OR char_length(v_title) > 60 THEN RAISE EXCEPTION 'Dê um nome ao grupo (até 60 letras)'; END IF;
    SELECT array_agg(DISTINCT x) INTO v_members FROM unnest(COALESCE(p_members, ARRAY[]::uuid[])) x
    WHERE x IS NOT NULL AND x <> v_user AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = x);
    IF COALESCE(array_length(v_members, 1), 0) < 2 THEN RAISE EXCEPTION 'Escolha pelo menos 2 pessoas (com uma só, é uma conversa normal)'; END IF;
    IF array_length(v_members, 1) > 29 THEN RAISE EXCEPTION 'Um grupo tem no máximo 30 pessoas'; END IF;
    IF (SELECT count(*) FROM public.conversations WHERE kind = 'group' AND customer_id = v_user AND created_at > now() - interval '1 day') >= 20 THEN
        RAISE EXCEPTION 'Muitos grupos criados hoje. Tente de novo amanhã.';
    END IF;

    INSERT INTO public.conversations (customer_id, kind, title) VALUES (v_user, 'group', left(v_title, 60)) RETURNING id INTO v_id;
    INSERT INTO public.conversation_members (conversation_id, profile_id, role, status, joined_at)
    VALUES (v_id, v_user, 'admin', 'active', now());
    FOREACH m IN ARRAY v_members LOOP
        INSERT INTO public.conversation_members (conversation_id, profile_id, role, status, invited_by)
        VALUES (v_id, m, 'member', 'invited', v_user);
        BEGIN
            PERFORM public._notify(m, 'group_invite', v_user, v_id, jsonb_build_object('title', left(v_title, 60)), 'ginv:' || v_id || ':' || m);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
    END LOOP;
    RETURN v_id;
END; $function$;

-- @@ 50|function create_in_person_sale(uuid,jsonb,text,text,text)
CREATE OR REPLACE FUNCTION public.create_in_person_sale(p_store_id uuid, p_items jsonb, p_buyer_name text, p_payment_method text, p_discount_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    s public.stores;
    v_priced jsonb;
    v_items_total numeric;
    v_discount numeric := 0;
    v_total numeric;
    v_order uuid;
BEGIN
    SELECT * INTO s FROM public.stores WHERE id = p_store_id;
    IF NOT FOUND OR s.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF p_payment_method NOT IN ('dinheiro', 'pix', 'credito', 'debito') THEN RAISE EXCEPTION 'Forma de pagamento inválida'; END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb), COALESCE(sum(x.total_price), 0)
      INTO v_priced, v_items_total
      FROM public._price_order_items(p_store_id, p_items, false) x;

    INSERT INTO public.orders (
        checkout_id, store_id, buyer_name, buyer_profile_slug, total_amount, delivery_fee, delivery_option, payment_method,
        delivery_address, delivery_lat, delivery_lng, status
    ) VALUES (
        gen_random_uuid(), p_store_id, COALESCE(NULLIF(btrim(p_buyer_name), ''), 'Cliente presencial'), '', 0, 0, 'pickup', p_payment_method,
        '', NULL, NULL, 'paid'
    ) RETURNING id INTO v_order;

    INSERT INTO public.order_items (order_id, product_id, product_name, quantity, unit_price, total_price)
    SELECT v_order, x.product_id, x.product_name, x.quantity, x.unit_price, x.total_price
      FROM public._price_order_items(p_store_id, p_items, false) x;

    IF p_discount_code IS NOT NULL AND btrim(p_discount_code) <> '' THEN
        v_discount := public._apply_campaign_discount(p_discount_code, p_store_id, v_order, 'in_person', v_priced);
    END IF;
    v_total := GREATEST(0, v_items_total - v_discount);
    UPDATE public.orders SET total_amount = v_total WHERE id = v_order;

    RETURN jsonb_build_object('order_id', v_order, 'items_total', v_items_total, 'discount', v_discount, 'total_amount', v_total);
END;
$function$;

-- @@ 50|function create_like_activity()
CREATE OR REPLACE FUNCTION public.create_like_activity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  post_owner uuid;
begin

  select user_id
  into post_owner
  from posts
  where id = new.post_id;

  if post_owner is not null and post_owner <> new.user_id then
    insert into activities (
      type,
      actor_id,
      recipient_id,
      post_id
    )
    values (
      'like',
      new.user_id,
      post_owner,
      new.post_id
    );
  end if;

  return new;

end;
$function$;

-- @@ 50|function create_notification(uuid,text,text,text,text,text,text,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.create_notification(p_user_id uuid, p_type text, p_title text, p_message text, p_priority text DEFAULT 'NORMAL'::text, p_action_url text DEFAULT NULL::text, p_action_label text DEFAULT NULL::text, p_data jsonb DEFAULT '{}'::jsonb, p_sender_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_notification_id UUID;
BEGIN
    INSERT INTO public.notifications (
        user_id,
        sender_id,
        type,
        title,
        message,
        priority,
        action_url,
        action_label,
        data,
        is_sent,
        sent_at
    ) VALUES (
        p_user_id,
        p_sender_id,
        p_type,
        p_title,
        p_message,
        p_priority,
        p_action_url,
        p_action_label,
        p_data,
        TRUE,
        NOW()
    )
    RETURNING id INTO v_notification_id;
    
    RETURN v_notification_id;
END;
$function$;

-- @@ 50|function create_or_update_profile(uuid,text,text,text,double precision,double precision)
CREATE OR REPLACE FUNCTION public.create_or_update_profile(user_id uuid, name text, name_page text, image text, longitude double precision, latitude double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    INSERT INTO public.profiles (id, name, name_page, image, location)
    VALUES (user_id, name, name_page, image, ST_SetSRID(ST_MakePoint(longitude, latitude), 4326))
    ON CONFLICT (id)
    DO UPDATE SET
        name = EXCLUDED.name,
        name_page = EXCLUDED.name_page,
        image = EXCLUDED.image,
        location = EXCLUDED.location;
END;
$function$;

-- @@ 50|function create_order(uuid,uuid)
CREATE OR REPLACE FUNCTION public.create_order(p_product_id uuid, p_buyer_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_store_id uuid;
  v_seller_id uuid;
  v_delivery_person_id uuid;
  v_order_id uuid;
BEGIN
  -- 1. Obter loja e dono
  SELECT store_id, s.owner_id INTO v_store_id, v_seller_id
  FROM public.products p
  JOIN public.stores s ON s.id = p.store_id
  WHERE p.id = p_product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  -- 2. Buscar um entregador disponível
  SELECT id INTO v_delivery_person_id
  FROM public.delivery_persons
  WHERE is_available = true
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No delivery person available';
  END IF;

  -- 3. Criar pedido
  INSERT INTO public.delivery_orders (product_id, store_id, buyer_id, seller_id, delivery_person_id, status)
  VALUES (p_product_id, v_store_id, p_buyer_id, v_seller_id, v_delivery_person_id, 'requested')
  RETURNING id INTO v_order_id;

  RETURN v_order_id;
END;
$function$;

-- @@ 50|function create_store_order(uuid,jsonb,text,text,text,double precision,double precision,numeric,boolean,text,uuid,uuid)
CREATE OR REPLACE FUNCTION public.create_store_order(p_store_id uuid, p_items jsonb, p_delivery_option text, p_payment_method text, p_address text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_cash_change_for numeric DEFAULT NULL::numeric, p_card_is_contactless boolean DEFAULT NULL::boolean, p_discount_code text DEFAULT NULL::text, p_checkout_id uuid DEFAULT NULL::uuid, p_estimate_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    s public.stores;
    pf record;
    v_priced jsonb;
    v_items_total numeric;
    v_fee numeric := 0;
    v_discount numeric := 0;
    v_total numeric;
    v_order uuid;
    v_checkout uuid := COALESCE(p_checkout_id, gen_random_uuid());
    v_option text;
    v_v2 boolean := false;
    v_est public.delivery_estimates;
    v_pay text := p_payment_method;
BEGIN
    IF v_uid IS NULL THEN RAISE EXCEPTION 'Entre na sua conta para fazer o pedido' USING ERRCODE = '42501'; END IF;
    SELECT * INTO s FROM public.stores WHERE id = p_store_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Loja não encontrada'; END IF;
    IF p_payment_method NOT IN ('pix', 'cartao', 'dinheiro', 'combinar') THEN RAISE EXCEPTION 'Forma de pagamento inválida'; END IF;
    v_option := CASE WHEN p_delivery_option IN ('retirada', 'pickup') THEN 'retirada' WHEN p_delivery_option = 'entrega' THEN 'entrega' ELSE NULL END;
    IF v_option IS NULL THEN RAISE EXCEPTION 'Escolha como deseja receber o pedido'; END IF;

    SELECT COALESCE(NULLIF(btrim(name), ''), 'Cliente') AS name, COALESCE(NULLIF(btrim("profileSlug"), ''), v_uid::text) AS slug
      INTO pf FROM public.profiles WHERE id = v_uid;
    IF NOT FOUND THEN pf.name := 'Cliente'; pf.slug := v_uid::text; END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb), COALESCE(sum(x.total_price), 0)
      INTO v_priced, v_items_total
      FROM public._price_order_items(p_store_id, p_items, true) x;

    IF v_option = 'entrega' THEN
        IF NOT COALESCE(s.accepts_delivery, false) THEN RAISE EXCEPTION 'Esta loja não faz entrega'; END IF;
        IF p_address IS NULL OR btrim(p_address) = '' THEN RAISE EXCEPTION 'Informe o endereço de entrega'; END IF;
        -- A versão do fluxo é decisão do SERVIDOR (chave global E da loja). O app nunca escolhe nem envia a versão.
        v_v2 := COALESCE(s.iuser_delivery_enabled, false) AND public.store_uses_delivery_flow_v2(p_store_id);
        IF v_v2 THEN
            -- V2: o frete é a estimativa oficial já apresentada (validada e consumida aqui); nada de frete vindo do app
            IF p_estimate_id IS NULL THEN
                RAISE EXCEPTION 'Solicite a estimativa da entrega antes de enviar o pedido' USING ERRCODE = '22023', HINT = 'estimate_required';
            END IF;
            v_est := public._consume_delivery_estimate(p_estimate_id, v_uid, p_store_id, p_address, p_lat, p_lng);
            v_fee := v_est.estimated_freight;
            v_pay := 'combinar';      -- ainda não há pagamento: o pedido só aguarda a decisão da loja
        ELSE
            v_fee := round(public._compute_store_delivery_fee(p_store_id, p_lat, p_lng), 2);
        END IF;
    ELSE
        IF NOT COALESCE(s.accepts_pickup, true) THEN RAISE EXCEPTION 'Esta loja não tem retirada no local'; END IF;
    END IF;

    INSERT INTO public.orders (
        store_id, buyer_id, buyer_name, buyer_profile_slug, total_amount, delivery_fee, delivery_option, payment_method,
        delivery_address, delivery_lat, delivery_lng, cash_change_for, card_is_contactless, status, checkout_id, delivery_flow_version
    ) VALUES (
        p_store_id, v_uid, pf.name, pf.slug, 0, v_fee, v_option, v_pay,
        CASE WHEN v_option = 'entrega' THEN btrim(p_address) ELSE 'Retirada no local' END,
        CASE WHEN v_option = 'entrega' THEN p_lat::numeric END,
        CASE WHEN v_option = 'entrega' THEN p_lng::numeric END,
        CASE WHEN p_payment_method = 'dinheiro' AND p_cash_change_for IS NOT NULL AND p_cash_change_for >= 0 THEN p_cash_change_for END,
        CASE WHEN p_payment_method = 'cartao' THEN p_card_is_contactless END,
        'pending', v_checkout, CASE WHEN v_v2 THEN 2 ELSE 1 END
    ) RETURNING id INTO v_order;

    IF v_v2 THEN
        UPDATE public.delivery_estimates SET order_id = v_order WHERE id = v_est.id;   -- estimativa consumida por este pedido
    END IF;

    INSERT INTO public.order_items (order_id, product_id, product_name, quantity, unit_price, total_price, comment, addons)
    SELECT v_order, x.product_id, x.product_name, x.quantity, x.unit_price, x.total_price, x.comment, x.addons
      FROM public._price_order_items(p_store_id, p_items, true) x;

    IF p_discount_code IS NOT NULL AND btrim(p_discount_code) <> '' THEN
        v_discount := public._apply_campaign_discount(p_discount_code, p_store_id, v_order, 'cart', v_priced);
    END IF;

    v_total := GREATEST(0, v_items_total - v_discount + v_fee);
    UPDATE public.orders SET total_amount = v_total WHERE id = v_order;

    RETURN jsonb_build_object('order_id', v_order, 'checkout_id', v_checkout, 'items_total', v_items_total,
                              'discount', v_discount, 'delivery_fee', v_fee, 'total_amount', v_total,
                              'flow_version', CASE WHEN v_v2 THEN 2 ELSE 1 END);
END;
$function$;

-- @@ 50|function create_store_with_access(jsonb)
CREATE OR REPLACE FUNCTION public.create_store_with_access(p_store jsonb)
 RETURNS stores
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_has_store boolean;
    v_store public.stores;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
    END IF;

    SELECT has_store INTO v_has_store FROM public.get_active_plan_grants(auth.uid());

    IF NOT v_has_store THEN
        RAISE EXCEPTION 'Assine o plano Loja ou Combo pra criar sua loja.';
    END IF;

    INSERT INTO public.stores (
        name, "storeSlug", description, logo_url, owner_id,
        location, address, store_lat, store_lng,
        address_number, address_complement, category, whatsapp,
        access_granted_at
    ) VALUES (
        p_store->>'name',
        p_store->>'storeSlug',
        p_store->>'description',
        p_store->>'logo_url',
        auth.uid(),
        CASE WHEN p_store->>'store_lat' IS NOT NULL AND p_store->>'store_lng' IS NOT NULL
            THEN ('POINT(' || (p_store->>'store_lng') || ' ' || (p_store->>'store_lat') || ')')::geography
            ELSE NULL END,
        p_store->>'address',
        NULLIF(p_store->>'store_lat', '')::double precision,
        NULLIF(p_store->>'store_lng', '')::double precision,
        p_store->>'address_number',
        p_store->>'address_complement',
        p_store->>'category',
        p_store->>'whatsapp',
        now()
    ) RETURNING * INTO v_store;

    RETURN v_store;
END;
$function$;

-- @@ 50|function create_transaction(uuid,text,numeric,text,text,text,text,uuid,text,jsonb)
CREATE OR REPLACE FUNCTION public.create_transaction(p_user_id uuid, p_type text, p_amount numeric, p_description text DEFAULT NULL::text, p_payment_method text DEFAULT NULL::text, p_payment_provider text DEFAULT NULL::text, p_external_id text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_reference_table text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_transaction_id UUID;
    v_current_balance DECIMAL;
BEGIN
    -- Buscar saldo atual do usuário
    SELECT COALESCE(available_balance, 0) INTO v_current_balance
    FROM public.profiles
    WHERE id = p_user_id;
    
    -- Validar saldo para saques
    IF p_type = 'WITHDRAWAL' AND v_current_balance < p_amount THEN
        RAISE EXCEPTION 'Saldo insuficiente. Disponível: %, Solicitado: %', v_current_balance, p_amount;
    END IF;
    
    -- Inserir transação
    INSERT INTO public.transactions (
        user_id,
        type,
        amount,
        fee,
        balance_before,
        description,
        payment_method,
        payment_provider,
        external_id,
        reference_id,
        reference_table,
        status,
        metadata
    ) VALUES (
        p_user_id,
        p_type,
        p_amount,
        0, -- Fee inicial
        v_current_balance,
        p_description,
        p_payment_method,
        p_payment_provider,
        p_external_id,
        p_reference_id,
        p_reference_table,
        'PENDING',
        p_metadata
    )
    RETURNING id INTO v_transaction_id;
    
    -- Registrar no log
    PERFORM public.log_event(
        'TRANSACTION_CREATED',
        p_user_id,
        NULL,
        auth.uid(),
        jsonb_build_object(
            'transaction_id', v_transaction_id,
            'type', p_type,
            'amount', p_amount,
            'balance_before', v_current_balance
        )
    );
    
    RETURN v_transaction_id;
END;
$function$;

-- @@ 50|function deactivate_old_relationships(uuid)
CREATE OR REPLACE FUNCTION public.deactivate_old_relationships(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Desativar todos os relacionamentos ativos do usuário
    UPDATE public.network_relationships
    SET 
        is_active = FALSE,
        deactivated_at = NOW(),
        deactivated_reason = 'Novo relacionamento criado',
        updated_at = NOW()
    WHERE user_id = p_user_id 
    AND is_active = TRUE;
END;
$function$;

-- @@ 50|function decrement_post_likes()
CREATE OR REPLACE FUNCTION public.decrement_post_likes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  update posts
  set likes = likes - 1
  where id = old.post_id;

  return old;
end;
$function$;

-- @@ 50|function delete_like_activity()
CREATE OR REPLACE FUNCTION public.delete_like_activity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin

  delete from activities
  where post_id = old.post_id
  and actor_id = old.user_id
  and type = 'like';

  return old;

end;
$function$;

-- @@ 50|function delivery_estimates_immutable()
CREATE OR REPLACE FUNCTION public.delivery_estimates_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- valor, distância, destino e snapshot nunca mudam; só o vínculo com o pedido (nulo→pedido, pedido→nulo se o pedido for apagado
    -- antes de a loja agir) e a invalidação (nulo→data) podem mudar
    IF (to_jsonb(NEW) - 'order_id' - 'invalidated_at') IS DISTINCT FROM (to_jsonb(OLD) - 'order_id' - 'invalidated_at')
       OR (OLD.order_id IS NOT NULL AND NEW.order_id IS NOT NULL AND NEW.order_id IS DISTINCT FROM OLD.order_id)
       OR (OLD.invalidated_at IS NOT NULL AND NEW.invalidated_at IS DISTINCT FROM OLD.invalidated_at) THEN
        RAISE EXCEPTION 'A estimativa é histórica e não pode ser alterada' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function delivery_payment_events_append_only()
CREATE OR REPLACE FUNCTION public.delivery_payment_events_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'delivery_payment_events é append-only: registre uma nova declaração em vez de alterar ou apagar' USING ERRCODE = '42501';
END;
$function$;

-- @@ 50|function delivery_rounds_v2_fence()
CREATE OR REPLACE FUNCTION public.delivery_rounds_v2_fence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF EXISTS (SELECT 1 FROM public.order_delivery_dispatches d WHERE d.id = NEW.dispatch_id AND d.flow_version = 2) THEN
        IF NEW.kind <> 'initial' AND COALESCE(current_setting('app.delivery_v2_engine', true), '') <> '1' THEN
            RAISE EXCEPTION 'As rodadas do novo fluxo só são criadas pela busca automática' USING ERRCODE = '42501';
        END IF;
        IF NEW.platform_fee <> 0 OR NEW.driver_offer <> NEW.final_freight THEN
            RAISE EXCEPTION 'No novo fluxo o motorista recebe o frete integral (sem taxa sobre o frete)' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function delivery_touch_updated_at()
CREATE OR REPLACE FUNCTION public.delivery_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN NEW.updated_at := now(); RETURN NEW; END;
$function$;

-- @@ 50|function dispatch_estimate_immutable()
CREATE OR REPLACE FUNCTION public.dispatch_estimate_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.estimated_freight IS NOT NULL AND NEW.estimated_freight IS DISTINCT FROM OLD.estimated_freight THEN
        RAISE EXCEPTION 'A estimativa inicial da entrega é histórica e não muda quando a oferta sobe' USING ERRCODE = '42501';
    END IF;
    IF OLD.estimate_id IS NOT NULL AND NEW.estimate_id IS DISTINCT FROM OLD.estimate_id THEN
        RAISE EXCEPTION 'A estimativa que originou a entrega não muda' USING ERRCODE = '42501';
    END IF;
    IF OLD.frozen_freight IS NOT NULL AND (NEW.frozen_freight IS DISTINCT FROM OLD.frozen_freight OR NEW.freight_frozen_at IS DISTINCT FROM OLD.freight_frozen_at)
       -- única exceção: a liberação da reserva (o motorista que aceitou saiu) zera o congelado; a história fica nos eventos
       AND NOT (OLD.flow_version = 2 AND COALESCE(current_setting('app.delivery_v2_release', true), '') = '1'
                AND NEW.frozen_freight IS NULL AND NEW.freight_frozen_at IS NULL AND NEW.reservation_released_at IS NOT NULL) THEN
        RAISE EXCEPTION 'O frete definitivo (aceito pelo motorista) não muda' USING ERRCODE = '42501';
    END IF;
    IF OLD.flow_version = 2 AND OLD.frozen_freight IS NOT NULL AND NEW.final_freight IS DISTINCT FROM OLD.final_freight THEN
        RAISE EXCEPTION 'A oferta não muda depois que o frete foi congelado' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function dispatch_flow_gate()
CREATE OR REPLACE FUNCTION public.dispatch_flow_gate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.flow_version = 2 THEN
        IF NEW.estimate_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.id = NEW.order_id AND o.delivery_flow_version = 2) THEN
            RAISE EXCEPTION 'Entrega do novo fluxo exige pedido do novo fluxo e estimativa vinculada' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function dispatch_phase_maintain()
CREATE OR REPLACE FUNCTION public.dispatch_phase_maintain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_actor text;
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.flow_version <> NEW.flow_version THEN
        RAISE EXCEPTION 'A versão do fluxo da entrega não muda depois de criada' USING ERRCODE = '42501';
    END IF;
    IF NEW.flow_version = 1 THEN
        -- fluxo atual: a fase é só um espelho de status/stage; ninguém decide por ela
        NEW.phase := public._legacy_delivery_phase(NEW.status, NEW.stage);
        IF TG_OP = 'INSERT' THEN
            NEW.estimated_freight := COALESCE(NEW.estimated_freight, NEW.original_freight);
        END IF;
        IF NEW.status IN ('accepted', 'completed') AND NEW.frozen_freight IS NULL THEN
            NEW.frozen_freight := NEW.final_freight;
            NEW.freight_frozen_at := now();
        END IF;
        IF TG_OP = 'INSERT' OR NEW.phase IS DISTINCT FROM OLD.phase THEN
            NEW.phase_changed_at := now();
        END IF;
    ELSE
        -- fluxo novo (ainda não criado por nada): fase obrigatória e só transições previstas para quem age
        IF NEW.phase IS NULL THEN RAISE EXCEPTION 'Entrega do novo fluxo exige a fase inicial'; END IF;
        -- frete definitivo: NULL até o motorista aceitar; no aceite recebe EXATAMENTE a oferta vigente (final_freight) e não muda mais
        IF TG_OP = 'INSERT' THEN
            IF NEW.frozen_freight IS NOT NULL OR NEW.freight_frozen_at IS NOT NULL THEN
                RAISE EXCEPTION 'O frete definitivo só é gravado no aceite do motorista' USING ERRCODE = '42501';
            END IF;
        ELSIF OLD.frozen_freight IS NULL THEN
            IF NEW.status IN ('accepted', 'completed') THEN
                NEW.frozen_freight := NEW.final_freight;
                NEW.freight_frozen_at := now();
            ELSIF NEW.frozen_freight IS NOT NULL OR NEW.freight_frozen_at IS NOT NULL THEN
                RAISE EXCEPTION 'O frete definitivo só é gravado no aceite do motorista' USING ERRCODE = '42501';
            END IF;
        END IF;
        IF TG_OP = 'UPDATE' AND NEW.phase IS DISTINCT FROM OLD.phase THEN
            v_actor := COALESCE(NULLIF(current_setting('app.delivery_actor', true), ''), 'system');
            IF NOT EXISTS (
                SELECT 1 FROM public.delivery_phase_transitions
                 WHERE from_phase = OLD.phase AND to_phase = NEW.phase AND actor_role = v_actor
            ) THEN
                RAISE EXCEPTION 'Transição de fase não permitida: % -> % (%)', OLD.phase, NEW.phase, v_actor USING ERRCODE = '42501';
            END IF;
            NEW.phase_changed_at := now();
        ELSIF TG_OP = 'INSERT' THEN
            NEW.phase_changed_at := now();
        END IF;
        -- a oferta nunca passa do limite que o cliente autorizou (nem do teto)
        IF NEW.price_limit IS NOT NULL AND NEW.final_freight > NEW.price_limit THEN
            RAISE EXCEPTION 'A oferta não pode passar do limite autorizado pelo cliente' USING ERRCODE = '42501';
        END IF;
        -- a busca terminou por fora do motor (motorista aceitou ou cliente cancelou): a fase acompanha
        IF TG_OP = 'UPDATE' AND OLD.status = 'searching' AND NEW.phase = OLD.phase
           AND OLD.phase IN ('PROCURANDO_ENTREGADOR', 'AGUARDANDO_AUTORIZACAO_REAJUSTE') THEN
            IF NEW.status = 'accepted' THEN
                NEW.phase := 'ENTREGADOR_RESERVADO';      -- motorista definido; a reserva operacional/pagamento é a próxima etapa
                NEW.phase_changed_at := now();
                NEW.offer_expires_at := NULL;
                NEW.search_end_reason := COALESCE(NEW.search_end_reason, 'driver_accepted');
                -- reserva real: o motorista vencedor fica preso por reservation_timeout_minutes (a janela de pagamento da próxima etapa)
                NEW.reserved_at := now();
                NEW.reserved_until := now() + make_interval(mins => (SELECT reservation_timeout_minutes FROM public.delivery_dispatch_settings WHERE id));
                NEW.reservation_released_at := NULL;
                NEW.reservation_release_reason := NULL;
            ELSIF NEW.status = 'cancelled' THEN
                NEW.phase := 'CANCELADO';
                NEW.phase_changed_at := now();
                NEW.offer_expires_at := NULL;
                NEW.search_end_reason := COALESCE(NEW.search_end_reason, 'cancelled');
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function dispatch_v2_closed()
CREATE OR REPLACE FUNCTION public.dispatch_v2_closed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_reason text;
BEGIN
    IF NEW.flow_version = 2 AND OLD.status = 'searching' AND NEW.status <> 'searching' THEN
        v_reason := COALESCE(NEW.search_end_reason, CASE NEW.status WHEN 'accepted' THEN 'driver_accepted' ELSE 'cancelled' END);
        UPDATE public.order_delivery_rounds
           SET status = CASE WHEN NEW.status = 'accepted' THEN 'accepted' ELSE 'expired' END, ended_at = now(), end_reason = v_reason
         WHERE dispatch_id = NEW.id AND round = NEW.round AND ended_at IS NULL;
        UPDATE public.delivery_reajust_authorizations SET status = 'cancelled', decided_at = now() WHERE dispatch_id = NEW.id AND status = 'pending';
        INSERT INTO public.order_delivery_events (dispatch_id, kind, phase_from, phase_to, data, processed_at)
        VALUES (NEW.id, 'search_ended', OLD.phase, NEW.phase,
                jsonb_build_object('reason', v_reason, 'round', NEW.round, 'final_freight', NEW.final_freight, 'frozen_freight', NEW.frozen_freight), now());
        IF NEW.phase = 'SEM_ENTREGADOR' THEN
            INSERT INTO public.order_delivery_events (dispatch_id, kind, data) VALUES (NEW.id, 'reservation_notice', jsonb_build_object('reason', 'no_driver', 'detail', v_reason));
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function dispatch_v2_reserved()
CREATE OR REPLACE FUNCTION public.dispatch_v2_reserved()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.flow_version = 2 AND NEW.phase = 'ENTREGADOR_RESERVADO' AND OLD.phase IS DISTINCT FROM NEW.phase AND NEW.frozen_freight IS NOT NULL THEN
        PERFORM public._v2_set_order_freight(NEW.order_id, NEW.frozen_freight);       -- produtos − descontos + frete aceito, no servidor
        INSERT INTO public.order_delivery_events (dispatch_id, kind, data)
        VALUES (NEW.id, 'reservation_notice', jsonb_build_object('reason', 'reserved', 'frozen_freight', NEW.frozen_freight, 'reserved_until', NEW.reserved_until,
                                                                  'driver_id', (SELECT driver_id FROM public.ride_requests WHERE id = NEW.ride_request_id)));
        PERFORM set_config('app.delivery_actor', 'system', true);
        UPDATE public.order_delivery_dispatches SET phase = 'AGUARDANDO_PAGAMENTO_CLIENTE' WHERE id = NEW.id;
        PERFORM public._ping_delivery_events();
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function dispatch_v2_sync_ride()
CREATE OR REPLACE FUNCTION public.dispatch_v2_sync_ride()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.flow_version = 2 AND NEW.status = 'searching'
       AND (NEW.final_freight IS DISTINCT FROM OLD.final_freight OR NEW.radius_km IS DISTINCT FROM OLD.radius_km) THEN
        UPDATE public.ride_requests SET offered_price = NEW.final_freight, visible_radius_km = NEW.radius_km
         WHERE id = NEW.ride_request_id AND status = 'pending'
           AND (offered_price IS DISTINCT FROM NEW.final_freight OR visible_radius_km IS DISTINCT FROM NEW.radius_km);
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function distribute_commissions()
CREATE OR REPLACE FUNCTION public.distribute_commissions()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    upline_record RECORD;
BEGIN
    FOR upline_record IN 
        SELECT p.id, cl.percentage, cl.amount
        FROM public.profiles p
        JOIN public.profiles buyer ON buyer.path <@ p.path AND buyer.id != p.id AND buyer.id = NEW.user_id
        JOIN public.commission_levels cl ON cl.level = nlevel(buyer.path) - nlevel(p.path)
        WHERE nlevel(buyer.path) - nlevel(p.path) <= 5
        ORDER BY nlevel(p.path) DESC
    LOOP
        INSERT INTO public.commissions (sale_id, earner_id, amount, level)
        VALUES (
            NEW.id, 
            upline_record.id, 
            upline_record.amount, 
            nlevel((SELECT path FROM public.profiles WHERE id = NEW.user_id)) - nlevel((SELECT path FROM public.profiles WHERE id = upline_record.id))
        );
    END LOOP;

    RETURN NEW;
END;
$function$;

-- @@ 50|function dra_immutable()
CREATE OR REPLACE FUNCTION public.dra_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF (to_jsonb(NEW) - 'status' - 'decided_at' - 'decided_by') IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'decided_at' - 'decided_by')
       OR (OLD.status <> 'pending' AND NEW.status IS DISTINCT FROM OLD.status) THEN
        RAISE EXCEPTION 'A solicitação de autorização é histórica e não pode ser alterada' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function driver_report_receipt(uuid,boolean,numeric)
CREATE OR REPLACE FUNCTION public.driver_report_receipt(p_dispatch uuid, p_received boolean, p_amount numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    d public.order_delivery_dispatches;
    v_driver uuid; v_owner uuid;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;
    IF v_uid IS NULL OR v_driver IS DISTINCT FROM v_uid OR d.status <> 'accepted' THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'store_declared_driver_payment') THEN
        RAISE EXCEPTION 'A loja ainda não informou o envio do pagamento' USING ERRCODE = '22023', HINT = 'store_not_reported';
    END IF;

    IF COALESCE(p_received, false) THEN
        IF EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'driver_confirmed_receipt') THEN
            RETURN jsonb_build_object('ok', true, 'duplicate', true, 'phase', d.phase);
        END IF;
        IF d.phase NOT IN ('LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', 'PAGAMENTO_EM_VERIFICACAO') THEN
            RAISE EXCEPTION 'Esta entrega não está aguardando a sua confirmação' USING ERRCODE = '22023', HINT = 'wrong_phase';
        END IF;
        IF p_amount IS NOT NULL AND p_amount IS DISTINCT FROM d.frozen_freight THEN
            RAISE EXCEPTION 'O valor declarado pela loja é R$ %', to_char(d.frozen_freight, 'FM999990D00') USING ERRCODE = '22023', HINT = 'amount_mismatch';
        END IF;
        INSERT INTO public.delivery_payment_events (dispatch_id, order_id, store_id, ride_request_id, driver_id, kind, amount, declared_by, declared_role, metadata)
        VALUES (d.id, d.order_id, d.store_id, d.ride_request_id, v_driver, 'driver_confirmed_receipt', d.frozen_freight, v_uid, 'driver',
                jsonb_build_object('from_phase', d.phase, 'declaratory', true));
        PERFORM set_config('app.delivery_actor', 'driver', true);
        UPDATE public.order_delivery_dispatches SET phase = 'ENTREGADOR_CONFIRMOU_RECEBIMENTO', updated_at = now() WHERE id = d.id;
        PERFORM set_config('app.delivery_actor', 'system', true);
        UPDATE public.order_delivery_dispatches SET phase = 'ENTREGA_LIBERADA', updated_at = now() WHERE id = d.id;      -- só aqui a barreira da 2.6 abre
        UPDATE public.delivery_incidents SET status = 'resolved', resolution = 'O entregador confirmou o recebimento.', resolved_by = v_uid, resolved_at = now(), updated_at = now()
         WHERE dispatch_id = d.id AND status IN ('open', 'under_review') AND kind IN ('driver_not_received', 'operational');
        SELECT owner_id INTO v_owner FROM public.stores WHERE id = d.store_id;
        INSERT INTO public.order_delivery_events (dispatch_id, kind, data) VALUES (d.id, 'reservation_notice', jsonb_build_object('reason', 'released', 'driver_id', v_driver));
        PERFORM public._ping_delivery_events();
        RETURN jsonb_build_object('ok', true, 'phase', 'ENTREGA_LIBERADA');
    END IF;

    -- "não recebi"
    IF EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'driver_declared_not_received') THEN
        RETURN jsonb_build_object('ok', true, 'duplicate', true, 'phase', d.phase);
    END IF;
    IF EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'driver_confirmed_receipt') OR d.phase <> 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR' THEN
        RAISE EXCEPTION 'Esta entrega não está aguardando a sua confirmação' USING ERRCODE = '22023', HINT = 'wrong_phase';
    END IF;
    INSERT INTO public.delivery_payment_events (dispatch_id, order_id, store_id, ride_request_id, driver_id, kind, amount, declared_by, declared_role, metadata)
    VALUES (d.id, d.order_id, d.store_id, d.ride_request_id, v_driver, 'driver_declared_not_received', d.frozen_freight, v_uid, 'driver', jsonb_build_object('declaratory', true));
    PERFORM set_config('app.delivery_actor', 'driver', true);
    UPDATE public.order_delivery_dispatches SET phase = 'PAGAMENTO_EM_VERIFICACAO', updated_at = now() WHERE id = d.id;
    INSERT INTO public.delivery_incidents (dispatch_id, order_id, ride_request_id, store_id, driver_id, kind, description, opened_by, opened_role)
    VALUES (d.id, d.order_id, d.ride_request_id, d.store_id, v_driver, 'driver_not_received',
            'O entregador informou que NÃO recebeu o pagamento do frete declarado pela loja. Nada foi decidido automaticamente.', v_uid, 'driver');
    INSERT INTO public.order_delivery_events (dispatch_id, kind, data) VALUES (d.id, 'reservation_notice', jsonb_build_object('reason', 'in_verification', 'driver_id', v_driver));
    PERFORM public._ping_delivery_events();
    RETURN jsonb_build_object('ok', true, 'phase', 'PAGAMENTO_EM_VERIFICACAO');
END;
$function$;

-- @@ 50|function enforce_delivery_radius()
CREATE OR REPLACE FUNCTION public.enforce_delivery_radius()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    rr record;
    dp record;
    v_km numeric;
    v_limit numeric;
BEGIN
    IF current_setting('app.skip_delivery_radius', true) = '1' THEN RETURN NEW; END IF;
    SELECT order_id, visible_radius_km, origin_lat, origin_lng INTO rr FROM public.ride_requests WHERE id = NEW.ride_request_id;
    IF rr.order_id IS NULL OR rr.visible_radius_km IS NULL OR rr.origin_lat IS NULL THEN RETURN NEW; END IF;
    SELECT live_lat, live_lng, live_updated_at, delivery_radius_km INTO dp FROM public.driver_pricing WHERE driver_id = NEW.applicant_id;
    IF dp.live_lat IS NULL OR dp.live_lng IS NULL OR dp.live_updated_at IS NULL OR dp.live_updated_at < now() - interval '30 minutes' THEN
        RETURN NEW;
    END IF;
    v_limit := LEAST(rr.visible_radius_km, COALESCE(dp.delivery_radius_km, rr.visible_radius_km));
    v_km := public.haversine_km(rr.origin_lat, rr.origin_lng, dp.live_lat, dp.live_lng);
    IF v_km > v_limit THEN
        RAISE EXCEPTION 'Essa entrega está fora do seu raio (% km da loja, raio atual de % km)', round(v_km, 1), v_limit
            USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function equip_avatar_border(uuid)
CREATE OR REPLACE FUNCTION public.equip_avatar_border(p_border_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid();
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF p_border_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.user_avatar_borders WHERE profile_id = v_user AND border_id = p_border_id
    ) THEN
        RAISE EXCEPTION 'Você ainda não tem essa borda';
    END IF;
    UPDATE public.profiles SET avatar_border_id = p_border_id WHERE id = v_user;
END; $function$;

-- @@ 50|function find_grant_targets(text)
CREATE OR REPLACE FUNCTION public.find_grant_targets(p_query text)
 RETURNS TABLE(id uuid, name text, profile_slug text, avatar_url text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    v_scope text;
    v_q text := btrim(COALESCE(p_query, ''));
BEGIN
    IF v_uid IS NULL OR length(v_q) < 2 THEN RETURN; END IF;

    SELECT e.scope INTO v_scope
    FROM public.get_effective_permissions(v_uid) e
    WHERE e.permission LIKE 'grant\_%'
    ORDER BY public._scope_rank(e.scope) DESC
    LIMIT 1;
    IF v_scope IS NULL THEN RETURN; END IF;

    RETURN QUERY
    SELECT p.id, p.name, p."profileSlug", p.avatar_url
    FROM public.profiles p
    WHERE p.id <> v_uid
      AND (p.name ILIKE '%' || v_q || '%' OR p."profileSlug" ILIKE '%' || v_q || '%')
      AND public.is_in_scope(v_uid, p.id, v_scope)
    ORDER BY p.name
    LIMIT 10;
END;
$function$;

-- @@ 50|function gate_appointment_accept()
CREATE OR REPLACE FUNCTION public.gate_appointment_accept()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_owner uuid;
BEGIN
    IF NEW.status = 'confirmed' AND OLD.status IS DISTINCT FROM 'confirmed' AND NEW.direction = 'outgoing' THEN
        IF NEW.store_id IS NOT NULL THEN
            SELECT owner_id INTO v_owner FROM public.stores WHERE id = NEW.store_id;
        ELSE
            v_owner := NEW.provider_profile_id;
        END IF;
        IF v_owner IS NOT NULL AND NEW.customer_id IS DISTINCT FROM v_owner
           AND (auth.uid() IS NULL OR auth.uid() = v_owner)
           AND public.get_driver_postpaid_debt(v_owner) >= 50 THEN
            RAISE EXCEPTION 'Você está com R$ 50 ou mais em aberto no pós-pago. Quite a dívida pra aceitar agendamentos.';
        END IF;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function generate_clean_slug(text,uuid)
CREATE OR REPLACE FUNCTION public.generate_clean_slug(name_text text, user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    base_slug text;
    new_slug text;
    counter int := 1;
BEGIN
    -- unaccent + lowercase + letters/digits only
    base_slug := lower(unaccent(name_text));
    base_slug := regexp_replace(base_slug, '[^a-z0-9]+', '', 'g');
    
    new_slug := base_slug;
    
    -- Loop to prevent duplicate slug
    WHILE EXISTS (SELECT 1 FROM public.profiles WHERE "profileSlug" = new_slug AND id != user_id) LOOP
        new_slug := base_slug || counter::text;
        counter := counter + 1;
    END LOOP;

    RETURN new_slug;
END;
$function$;

-- @@ 50|function generate_network_path(uuid,uuid)
CREATE OR REPLACE FUNCTION public.generate_network_path(p_user_id uuid, p_upline_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_path TEXT;
    v_upline_path TEXT;
BEGIN
    -- Buscar caminho do upline
    SELECT path INTO v_upline_path
    FROM public.network_relationships
    WHERE user_id = p_upline_id AND is_active = TRUE
    ORDER BY created_at DESC
    LIMIT 1;
    
    -- Se o upline não tem caminho, começar novo
    IF v_upline_path IS NULL THEN
        v_path := p_user_id::TEXT;
    ELSE
        v_path := v_upline_path || '/' || p_user_id::TEXT;
    END IF;
    
    RETURN v_path;
END;
$function$;

-- @@ 50|function get_active_plan_grants(uuid)
CREATE OR REPLACE FUNCTION public.get_active_plan_grants(p_user_id uuid)
 RETURNS TABLE(has_driver boolean, has_provider boolean, has_store boolean, has_recruiter boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_email text;
BEGIN
    SELECT email INTO v_email FROM auth.users WHERE id = p_user_id;
    IF v_email = 'ncastelano@gmail.com' THEN
        RETURN QUERY SELECT true, true, true, true;
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        COALESCE(bool_or(p.grants_driver), false),
        COALESCE(bool_or(p.grants_provider), false),
        COALESCE(bool_or(p.grants_store), false),
        COALESCE(bool_or(p.grants_recruiter), false)
    FROM public.subscriptions s
    JOIN public.plans p ON p.id = s.plan_id
    WHERE s.user_id = p_user_id
        AND s.status = 'active'
        AND (s.starts_at IS NULL OR s.starts_at <= now())
        AND s.current_period_end > now();
END;
$function$;

-- @@ 50|function get_asaas_financial_overview()
CREATE OR REPLACE FUNCTION public.get_asaas_financial_overview()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT jsonb_build_object(
        -- Assinaturas ativas (MRR) e contagem por status.
        'mrr', COALESCE((
            SELECT sum(p.price) FROM public.subscriptions s
            JOIN public.plans p ON p.id = s.plan_id
            WHERE s.status = 'active' AND (s.current_period_end IS NULL OR s.current_period_end > now())
        ), 0),
        'active_subscriptions', (SELECT count(*) FROM public.subscriptions WHERE status = 'active'),
        'past_due_subscriptions', (SELECT count(*) FROM public.subscriptions WHERE status = 'past_due'),
        'canceled_subscriptions', (SELECT count(*) FROM public.subscriptions WHERE status = 'canceled'),

        -- Receita de assinatura já recebida (subscription_payments), total e mês corrente — BRUTO.
        'subscription_revenue_total', COALESCE((SELECT sum(amount) FROM public.subscription_payments), 0),
        'subscription_revenue_this_month', COALESCE((
            SELECT sum(amount) FROM public.subscription_payments WHERE created_at >= date_trunc('month', now())
        ), 0),

        -- Pós-pago já recebido (linhas type='payment', valor negativo no ledger), total e mês corrente — BRUTO.
        'postpaid_collected_total', COALESCE((
            SELECT -sum(amount) FROM public.driver_postpaid_charges WHERE type = 'payment'
        ), 0),
        'postpaid_collected_this_month', COALESCE((
            SELECT -sum(amount) FROM public.driver_postpaid_charges WHERE type = 'payment' AND created_at >= date_trunc('month', now())
        ), 0),

        -- Comissão de indicação creditada (repasse — não é receita da
        -- iUser, é dinheiro que já nasce devido a quem indicou), total e
        -- mês corrente. Subtrai do bruto acima pra achar o lucro real.
        'commission_credited_total', COALESCE((
            SELECT sum(amount) FROM public.wallet_transactions WHERE type = 'commission_credit'
        ), 0),
        'commission_credited_this_month', COALESCE((
            SELECT sum(amount) FROM public.wallet_transactions WHERE type = 'commission_credit' AND created_at >= date_trunc('month', now())
        ), 0),

        -- Carteira das pessoas: passivo total (quanto devemos, se todo mundo sacasse agora)
        -- e quantas pessoas têm saldo positivo pra sacar.
        'wallet_liability_total', COALESCE((SELECT sum(amount) FROM public.wallet_transactions), 0),
        'wallet_positive_users', (
            SELECT count(*) FROM (
                SELECT user_id FROM public.wallet_transactions GROUP BY user_id HAVING sum(amount) > 0
            ) t
        ),

        -- Saques já solicitados e ainda não pagos — passivo de curto prazo.
        'pending_withdrawals_total', COALESCE((SELECT sum(amount) FROM public.withdrawal_requests WHERE status = 'pending'), 0),
        'pending_withdrawals_count', (SELECT count(*) FROM public.withdrawal_requests WHERE status = 'pending'),

        -- O que cada pessoa ainda nos deve no pós-pago (dívida em aberto) e
        -- quantas estão bloqueadas (>= R$50, mesmo limiar de get_driver_postpaid_debt).
        'postpaid_debt_outstanding_total', COALESCE((
            SELECT sum(balance) FROM (
                SELECT sum(amount) AS balance FROM public.driver_postpaid_charges GROUP BY driver_id HAVING sum(amount) > 0
            ) t
        ), 0),
        'postpaid_debt_users_count', (
            SELECT count(*) FROM (
                SELECT driver_id FROM public.driver_postpaid_charges GROUP BY driver_id HAVING sum(amount) > 0
            ) t
        ),
        'postpaid_debt_blocked_count', (
            SELECT count(*) FROM (
                SELECT driver_id FROM public.driver_postpaid_charges GROUP BY driver_id HAVING sum(amount) >= 50
            ) t
        )
    );
$function$;

-- @@ 50|function get_avatar_borders_for(uuid[])
CREATE OR REPLACE FUNCTION public.get_avatar_borders_for(p_ids uuid[])
 RETURNS TABLE(profile_id uuid, colors text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, b.colors
    FROM public.profiles p
    JOIN public.avatar_borders b ON b.id = p.avatar_border_id AND b.is_active
    WHERE p.id = ANY (p_ids[1:200]);
$function$;

-- @@ 50|function get_benefit_history(integer,boolean)
CREATE OR REPLACE FUNCTION public.get_benefit_history(p_limit integer DEFAULT 100, p_only_granted boolean DEFAULT true)
 RETURNS TABLE(id uuid, target_user_id uuid, target_name text, target_slug text, actor_user_id uuid, actor_name text, plan_code text, plan_name text, outcome text, denial_reason text, reason text, starts_at timestamp with time zone, expires_at timestamp with time zone, created_at timestamp with time zone, is_active boolean, is_scheduled boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    v_scope text;
BEGIN
    IF v_uid IS NULL THEN RETURN; END IF;

    SELECT e.scope INTO v_scope
    FROM public.get_effective_permissions(v_uid) e
    WHERE e.permission LIKE 'grant\_%'
    ORDER BY public._scope_rank(e.scope) DESC
    LIMIT 1;

    RETURN QUERY
    SELECT l.id, l.target_user_id, t.name, t."profileSlug",
           l.actor_user_id, a.name, l.plan_code, pl.name,
           l.outcome, l.denial_reason, l.reason,
           l.starts_at, l.expires_at, l.created_at,
           COALESCE(l.outcome = 'granted' AND l.starts_at <= now() AND l.expires_at > now(), false),
           COALESCE(l.outcome = 'granted' AND l.starts_at > now(), false)
    FROM public.grant_audit_logs l
    LEFT JOIN public.profiles t ON t.id = l.target_user_id
    LEFT JOIN public.profiles a ON a.id = l.actor_user_id
    LEFT JOIN public.plans pl ON pl.id = l.plan_id
    WHERE l.action = 'grant_plan'
      AND (NOT p_only_granted OR l.outcome = 'granted')
      AND (
          l.actor_user_id = v_uid
          OR v_scope = 'all'
          OR (v_scope = 'network' AND public.is_in_scope(v_uid, l.target_user_id, 'network'))
      )
    ORDER BY l.created_at DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
END;
$function$;

-- @@ 50|function get_best_profiles(integer)
CREATE OR REPLACE FUNCTION public.get_best_profiles(p_limit integer DEFAULT 100)
 RETURNS TABLE(id uuid, points integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, COALESCE(pp.total, 0) AS points
    FROM public.profiles p
    LEFT JOIN public.profile_points pp ON pp.profile_id = p.id
    WHERE p.is_active
    ORDER BY COALESCE(pp.total, 0) DESC, COALESCE(p.view_count, 0) DESC, p.ratings_avg DESC NULLS LAST
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 100), 1), 200);
$function$;

-- @@ 50|function get_checkout_flow(uuid)
CREATE OR REPLACE FUNCTION public.get_checkout_flow(p_store uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT CASE WHEN EXISTS (SELECT 1 FROM public.stores s WHERE s.id = p_store AND COALESCE(s.accepts_delivery, false)
                                AND COALESCE(s.iuser_delivery_enabled, false)) AND public.store_uses_delivery_flow_v2(p_store)
                THEN 'v2' ELSE 'v1' END
$function$;

-- @@ 50|function get_closest_items(double precision,double precision,integer,integer)
CREATE OR REPLACE FUNCTION public.get_closest_items(p_lat double precision, p_lng double precision, max_distance integer DEFAULT 50000, limit_num integer DEFAULT 50)
 RETURNS TABLE(id uuid, type text, name text, description text, image_url text, distance double precision, lat double precision, lng double precision, rating double precision, slug text, store_slug text, price numeric)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
  SELECT * FROM (
    SELECT 
      s.id,
      'loja' AS type,
      s.name,
      s.description,
      s.logo_url AS image_url,
      ST_Distance(s.location, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)) AS distance,
      ST_Y(s.location::geometry) AS lat,
      ST_X(s.location::geometry) AS lng,
      0.0::FLOAT AS rating,
      s."storeSlug" AS slug,
      s."storeSlug" AS store_slug,
      0.0::NUMERIC AS price
    FROM stores s
    WHERE s.location IS NOT NULL

    UNION ALL

    SELECT 
      p.id,
      p.type::text AS type,
      p.name,
      p.description,
      p.image_url AS image_url,
      ST_Distance(p.location, ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)) AS distance,
      ST_Y(p.location::geometry) AS lat,
      ST_X(p.location::geometry) AS lng,
      0.0::FLOAT AS rating,
      p.slug AS slug,
      (SELECT "storeSlug" FROM stores WHERE id = p.store_id) AS store_slug,
      p.price AS price
    FROM products p
    WHERE p.location IS NOT NULL
  ) q
  WHERE q.distance <= max_distance
  ORDER BY q.distance ASC
  LIMIT limit_num;
END;
$function$;

-- @@ 50|function get_communities_activity(uuid[])
CREATE OR REPLACE FUNCTION public.get_communities_activity(p_ids uuid[])
 RETURNS TABLE(community_id uuid, last_message_at timestamp with time zone, photo_vote_active boolean, photo_candidates integer, photo_event_at timestamp with time zone, photo_thumbs text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT c.id,
           (SELECT max(m.created_at) FROM public.community_messages m WHERE m.community_id = c.id),
           COALESCE(ev.n, 0) > 0,
           COALESCE(ev.n, 0)::integer,
           ev.last_at,
           COALESCE(ev.thumbs, ARRAY[]::text[])
    FROM public.communities c
    LEFT JOIN LATERAL (
        SELECT count(*) AS n,
               max(cand.created_at) AS last_at,
               (array_agg(cand.image_url ORDER BY cand.created_at DESC))[1:3] AS thumbs
        FROM public.community_photo_candidates cand
        WHERE cand.community_id = c.id
          AND cand.outcome IS NULL
          AND cand.round_day = (now() AT TIME ZONE c.tz)::date
    ) ev ON true
    WHERE c.id = ANY(p_ids);
$function$;

-- @@ 50|function get_conversation_refs(uuid)
CREATE OR REPLACE FUNCTION public.get_conversation_refs(p_conv uuid)
 RETURNS TABLE(id uuid, name text, slug text, image_url text, owner_slug text, listing_type text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, p.name, p.slug, p.image_url,
           COALESCE(s."storeSlug", pr."profileSlug"), p.listing_type
    FROM public.products p
    LEFT JOIN public.stores s ON s.id = p.store_id
    LEFT JOIN public.profiles pr ON pr.id = p.owner_id
    WHERE public._can_access_conversation(p_conv, auth.uid())
      AND p.id IN (SELECT m.ref_product_id FROM public.direct_messages m WHERE m.conversation_id = p_conv AND m.ref_product_id IS NOT NULL);
$function$;

-- @@ 50|function get_conversation_request_refs(uuid)
CREATE OR REPLACE FUNCTION public.get_conversation_request_refs(p_conv uuid)
 RETURNS TABLE(id uuid, service_type text, custom_service text, description text, location_address text, photo_urls text[], status text, created_at timestamp with time zone, requester_slug text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT r.id, r.service_type, r.custom_service, r.description, r.location_address, r.photo_urls,
           CASE
               WHEN EXISTS (SELECT 1 FROM public.service_applications a WHERE a.service_request_id = r.id AND a.status = 'accepted' AND a.completed_at IS NOT NULL)
                   AND NOT EXISTS (SELECT 1 FROM public.service_applications a WHERE a.service_request_id = r.id AND a.status = 'accepted' AND a.completed_at IS NULL) THEN 'completed'
               WHEN EXISTS (SELECT 1 FROM public.service_applications a WHERE a.service_request_id = r.id AND a.status = 'accepted') THEN 'accepted'
               ELSE r.status
           END,
           r.created_at, pr."profileSlug"
    FROM public.service_requests r
    LEFT JOIN public.profiles pr ON pr.id = r.requester_id
    WHERE public._can_access_conversation(p_conv, auth.uid())
      AND r.id IN (SELECT m.ref_request_id FROM public.direct_messages m WHERE m.conversation_id = p_conv AND m.ref_request_id IS NOT NULL);
$function$;

-- @@ 50|function get_database_stats()
CREATE OR REPLACE FUNCTION public.get_database_stats()
 RETURNS json
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select json_build_object(
        'database_size_bytes', pg_database_size(current_database()),
        'database_size_pretty', pg_size_pretty(pg_database_size(current_database())),
        'top_tables', (
            select coalesce(json_agg(row_to_json(t)), '[]'::json) from (
                select
                    c.relname as table_name,
                    pg_total_relation_size(c.oid) as size_bytes,
                    pg_size_pretty(pg_total_relation_size(c.oid)) as size_pretty,
                    (select reltuples::bigint from pg_class where oid = c.oid) as approx_rows
                from pg_class c
                join pg_namespace n on n.oid = c.relnamespace
                where n.nspname = 'public' and c.relkind = 'r'
                order by pg_total_relation_size(c.oid) desc
                limit 10
            ) t
        ),
        'storage_size_bytes', (
            select coalesce(sum((metadata->>'size')::bigint), 0) from storage.objects
        ),
        'mau_last_30d', (
            select count(*) from auth.users where last_sign_in_at >= now() - interval '30 days'
        )
    );
$function$;

-- @@ 50|function get_default_upline_id()
CREATE OR REPLACE FUNCTION public.get_default_upline_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    SELECT p.id FROM public.profiles p JOIN auth.users u ON u.id = p.id
    WHERE lower(u.email) = 'ncastelano@gmail.com' LIMIT 1
$function$;

-- @@ 50|function get_delivery_payment_view(uuid)
CREATE OR REPLACE FUNCTION public.get_delivery_payment_view(p_dispatch uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    d public.order_delivery_dispatches; o public.orders; s public.stores; k public.driver_payout_keys; drv jsonb;
    v_role text; v_driver uuid;
    e_cust boolean; e_store boolean; e_conf boolean; e_deny boolean; v_incident boolean;
    out jsonb;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch;
    IF NOT FOUND OR d.flow_version <> 2 OR v_uid IS NULL THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT * INTO s FROM public.stores WHERE id = d.store_id;
    SELECT * INTO o FROM public.orders WHERE id = d.order_id;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;
    v_role := CASE WHEN v_uid = s.owner_id THEN 'store' WHEN v_uid = d.customer_id THEN 'customer' WHEN v_uid = v_driver AND d.status = 'accepted' THEN 'driver' END;
    IF v_role IS NULL THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;

    SELECT bool_or(kind = 'store_declared_customer_payment'), bool_or(kind = 'store_declared_driver_payment'),
           bool_or(kind = 'driver_confirmed_receipt'), bool_or(kind = 'driver_declared_not_received')
      INTO e_cust, e_store, e_conf, e_deny FROM public.delivery_payment_events WHERE dispatch_id = d.id;
    v_incident := EXISTS (SELECT 1 FROM public.delivery_incidents WHERE dispatch_id = d.id AND status IN ('open', 'under_review'));
    out := jsonb_build_object(
        'role', v_role, 'phase', d.phase, 'state', public._v2_state_code(d.phase, d.status),
        'frozen_freight', d.frozen_freight, 'estimated_freight', d.estimated_freight,
        'items_total', o.total_amount - COALESCE(o.delivery_fee, 0), 'delivery_fee', o.delivery_fee, 'total_amount', o.total_amount,
        'reserved_until', CASE WHEN d.reservation_released_at IS NULL THEN d.reserved_until END,
        'customer_payment_reported', COALESCE(e_cust, false), 'driver_payment_reported', COALESCE(e_store, false),
        'driver_confirmed', COALESCE(e_conf, false), 'driver_denied', COALESCE(e_deny, false), 'open_incident', v_incident);

    IF v_role = 'customer' THEN
        -- instruções para pagar a LOJA (nunca o Pix do motorista)
        out := out || jsonb_build_object('store', jsonb_build_object(
            'name', s.name, 'accepts_pix', COALESCE(s.accepts_pix, false), 'accepts_card', COALESCE(s.accepts_card, false), 'accepts_cash', COALESCE(s.accepts_cash, false),
            'pix_key_type', CASE WHEN d.phase = 'AGUARDANDO_PAGAMENTO_CLIENTE' AND COALESCE(s.accepts_pix, false) THEN s.pix_key_type END,
            'pix_key', CASE WHEN d.phase = 'AGUARDANDO_PAGAMENTO_CLIENTE' AND COALESCE(s.accepts_pix, false) THEN s.pix_key END));
    ELSIF v_role = 'store' THEN
        SELECT jsonb_build_object('slug', p."profileSlug", 'name', p.name) INTO drv FROM public.profiles p WHERE p.id = v_driver;
        SELECT * INTO k FROM public.driver_payout_keys WHERE driver_id = v_driver;
        out := out || jsonb_build_object('driver', drv, 'amount_to_pay_driver', d.frozen_freight,
            -- a chave do motorista só aparece quando a loja já declarou receber do cliente (hora de pagar o frete)
            'driver_pix_type', CASE WHEN d.phase IN ('AGUARDANDO_PAGAMENTO_ENTREGADOR', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', 'PAGAMENTO_EM_VERIFICACAO') THEN k.pix_key_type END,
            'driver_pix_key', CASE WHEN d.phase IN ('AGUARDANDO_PAGAMENTO_ENTREGADOR', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', 'PAGAMENTO_EM_VERIFICACAO') THEN k.pix_key END);
    ELSE
        out := out || jsonb_build_object('amount_to_receive', d.frozen_freight,
            'can_respond', d.phase IN ('LOJA_INFORMOU_PAGAMENTO_ENTREGADOR') OR (d.phase = 'PAGAMENTO_EM_VERIFICACAO' AND COALESCE(e_store, false) AND NOT COALESCE(e_conf, false)));
        out := out - 'items_total' - 'delivery_fee' - 'total_amount';           -- o motorista não precisa do total do pedido
    END IF;
    RETURN out;
END;
$function$;

-- @@ 50|function get_downline(uuid)
CREATE OR REPLACE FUNCTION public.get_downline(parent_id uuid)
 RETURNS TABLE(id uuid, name text, avatar_url text, level integer, created_at timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        d.id,
        d.name,
        d.avatar_url,
        (nlevel(d.path) - nlevel(p.path))::int AS level,
        d.created_at
    FROM public.profiles d
    JOIN public.profiles p ON d.path <@ p.path AND d.id != p.id
    WHERE p.id = parent_id
      AND (nlevel(d.path) - nlevel(p.path)) <= 5
    ORDER BY level ASC, d.created_at DESC;
END;
$function$;

-- @@ 50|function get_downline_tree(uuid,integer)
CREATE OR REPLACE FUNCTION public.get_downline_tree(user_id uuid, max_depth integer DEFAULT 10)
 RETURNS TABLE(id uuid, name text, profileslug text, avatar_url text, upline_id uuid, level integer, path ltree, created_at timestamp with time zone, downline_count bigint, total_volume numeric, is_leader boolean)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    WITH RECURSIVE downline AS (
        -- Passo 1: O usuário raiz
        SELECT 
            p.id,
            p.name,
            p."profileSlug",
            p.avatar_url,
            p.upline_id,
            0 as level,
            p.path,
            p.created_at,
            (SELECT COUNT(*) FROM profiles WHERE upline_id = p.id) as direct_count,
            p.view_count as monthly_volume,
            false as is_leader
        FROM profiles p
        WHERE p.id = user_id

        UNION ALL

        -- Passo 2: Os indicados (recursivo)
        SELECT 
            p.id,
            p.name,
            p."profileSlug",
            p.avatar_url,
            p.upline_id,
            d.level + 1,
            p.path,
            p.created_at,
            (SELECT COUNT(*) FROM profiles WHERE upline_id = p.id) as direct_count,
            p.view_count as monthly_volume,
            false as is_leader
        FROM profiles p
        INNER JOIN downline d ON p.upline_id = d.id
        WHERE d.level < max_depth
    )
    SELECT 
        d.id,
        d.name,
        d."profileSlug",
        d.avatar_url,
        d.upline_id,
        d.level,
        d.path,
        d.created_at,
        (SELECT COUNT(*) FROM profiles WHERE upline_id = d.id) as downline_count,
        COALESCE((SELECT SUM(view_count) FROM profiles WHERE upline_id = d.id), 0) as total_volume,
        CASE 
            WHEN d.level > 0 AND (SELECT COUNT(*) FROM profiles WHERE upline_id = d.id) >= 5 THEN true 
            ELSE false 
        END as is_leader
    FROM downline d
    WHERE d.level > 0 -- Remove o raiz da lista de resultados
    ORDER BY d.level, d.created_at;
END;
$function$;

-- @@ 50|function get_downline_with_commissions(uuid,integer)
CREATE OR REPLACE FUNCTION public.get_downline_with_commissions(user_id uuid, max_depth integer DEFAULT 10)
 RETURNS TABLE(id uuid, name text, email text, avatar_url text, user_type text, is_leader boolean, monthly_volume bigint, level integer, indicated_by uuid, created_at timestamp with time zone, profileslug text, store_name text, store_avatar text, total_downline bigint, total_volume numeric, leader_count bigint, store_count bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    WITH RECURSIVE downline_tree AS (
        SELECT 
            p.id,
            p.name,
            p."profileSlug",
            p.avatar_url,
            p.upline_id,
            0 as level,
            p.created_at,
            COALESCE(p.view_count, 0) as monthly_volume
        FROM profiles p
        WHERE p.id = user_id

        UNION ALL

        SELECT 
            p.id,
            p.name,
            p."profileSlug",
            p.avatar_url,
            p.upline_id,
            dt.level + 1,
            p.created_at,
            COALESCE(p.view_count, 0) as monthly_volume
        FROM profiles p
        INNER JOIN downline_tree dt ON p.upline_id = dt.id
        WHERE dt.level < max_depth
    )
    SELECT 
        dt.id,
        COALESCE(dt.name, 'Usuário') as name,
        ''::text as email,
        dt.avatar_url,
        'person'::text as user_type,
        false as is_leader,
        dt.monthly_volume,
        dt.level,
        dt.upline_id as indicated_by,
        dt.created_at,
        dt."profileSlug",
        NULL::text as store_name,
        NULL::text as store_avatar,
        0 as total_downline,
        0 as total_volume,
        0 as leader_count,
        0 as store_count
    FROM downline_tree dt
    WHERE dt.level > 0
    ORDER BY dt.level, dt.created_at;
END;
$function$;

-- @@ 50|function get_driver_delivery_gate(uuid)
CREATE OR REPLACE FUNCTION public.get_driver_delivery_gate(p_ride uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.ride_requests; d public.order_delivery_dispatches;
BEGIN
    SELECT * INTO r FROM public.ride_requests WHERE id = p_ride;
    IF NOT FOUND OR auth.uid() IS NULL OR r.driver_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE ride_request_id = p_ride;
    IF NOT FOUND OR d.flow_version <> 2 THEN RETURN jsonb_build_object('v2', false, 'released', true); END IF;
    RETURN jsonb_build_object('v2', true, 'dispatch_id', d.id, 'phase', d.phase, 'state', public._v2_state_code(d.phase, d.status),
                              'released', public._v2_phase_released(d.phase),
                              'reserved_until', CASE WHEN d.reservation_released_at IS NULL THEN d.reserved_until END,
                              'frozen_freight', d.frozen_freight);
END;
$function$;

-- @@ 50|function get_driver_postpaid_debt(uuid)
CREATE OR REPLACE FUNCTION public.get_driver_postpaid_debt(p_driver_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
