-- @@ 50|function get_driver_public_stats(uuid)
CREATE OR REPLACE FUNCTION public.get_driver_public_stats(p_driver uuid)
 RETURNS TABLE(rides_completed bigint, rating_avg numeric, rating_count bigint, member_since timestamp with time zone, store_name text, store_slug text, store_logo text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        (SELECT count(*) FROM public.ride_requests r WHERE r.driver_id = p_driver AND r.status = 'completed'),
        (SELECT round(avg(rv.rating)::numeric, 2) FROM public.ride_reviews rv WHERE rv.reviewee_id = p_driver),
        (SELECT count(*) FROM public.ride_reviews rv WHERE rv.reviewee_id = p_driver),
        (SELECT p.created_at FROM public.profiles p WHERE p.id = p_driver),
        s.name, s."storeSlug", s.logo_url
    FROM (SELECT 1) one
    LEFT JOIN LATERAL (
        SELECT name, "storeSlug", logo_url FROM public.stores
        WHERE owner_id = p_driver AND is_active ORDER BY created_at LIMIT 1
    ) s ON true;
$function$;

-- @@ 50|function get_driver_recent_rides(uuid,integer)
CREATE OR REPLACE FUNCTION public.get_driver_recent_rides(p_driver uuid, p_limit integer DEFAULT 6)
 RETURNS TABLE(ride_id uuid, rode_at timestamp with time zone, distance_km numeric, origin_address text, destination_address text, rating integer, comment text, reviewer_name text, reviewer_slug text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT r.id,
           COALESCE(r.ride_started_at, r.created_at),
           r.distance_km,
           COALESCE(public._coarse_address(r.origin_address), 'um local'),
           COALESCE(public._coarse_address(r.destination_address), 'um local'),
           rv.rating,
           NULLIF(btrim(rv.comment), ''),
           p.name,
           p."profileSlug"
    FROM public.ride_requests r
    LEFT JOIN public.ride_reviews rv ON rv.ride_request_id = r.id AND rv.reviewee_id = p_driver
    LEFT JOIN public.profiles p ON p.id = rv.reviewer_id
    WHERE r.driver_id = p_driver AND r.status = 'completed'
    ORDER BY COALESCE(r.ride_started_at, r.created_at) DESC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 6), 20))
$function$;

-- @@ 50|function get_effective_commission(uuid,text)
CREATE OR REPLACE FUNCTION public.get_effective_commission(p_user uuid, p_plan_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_state public.user_network_state;
    v_level public.network_levels;
    v_level_id uuid;
    v_max integer;
    v_standard integer;
    v_custom integer;
    v_rate integer;
    v_source text;
    v_manual_order integer;
    v_high_order integer;
BEGIN
    IF p_plan_type NOT IN ('prepaid', 'postpaid') THEN
        RAISE EXCEPTION 'Tipo de plano inválido: % (use prepaid ou postpaid).', p_plan_type;
    END IF;

    SELECT * INTO v_state FROM public.user_network_state WHERE user_id = p_user;
    v_level_id := public._effective_level_id(p_user);
    SELECT * INTO v_level FROM public.network_levels WHERE id = v_level_id;
    IF v_level.id IS NULL THEN
        RAISE EXCEPTION 'Nenhum nível de graduação cadastrado.';
    END IF;
    SELECT max_commission_bp INTO v_max FROM public.network_settings WHERE id;

    v_standard := CASE p_plan_type WHEN 'prepaid' THEN v_level.commission_prepaid_bp ELSE v_level.commission_postpaid_bp END;
    v_custom := CASE WHEN COALESCE(v_state.custom_commission_enabled, false)
                     THEN CASE p_plan_type WHEN 'prepaid' THEN v_state.custom_commission_prepaid_bp ELSE v_state.custom_commission_postpaid_bp END
                END;

    SELECT level_order INTO v_manual_order FROM public.network_levels WHERE id = v_state.manual_level_id;
    SELECT level_order INTO v_high_order FROM public.network_levels WHERE id = v_state.highest_level_id;

    IF v_custom IS NOT NULL THEN
        v_rate := v_custom;
        v_source := 'custom';
    ELSE
        v_rate := v_standard;
        v_source := CASE
            WHEN v_manual_order IS NOT NULL AND v_manual_order > COALESCE(v_high_order, 0) THEN 'manual_level'
            WHEN v_state.highest_level_id IS NOT NULL THEN 'achieved_level'
            ELSE 'initial_level'
        END;
    END IF;

    RETURN jsonb_build_object(
        'level_id', v_level.id,
        'level', v_level.name,
        'level_order', v_level.level_order,
        'standard_rate_bp', v_standard,
        'commission_rate_bp', LEAST(v_rate, v_max),
        'commission_rate_percent', round(LEAST(v_rate, v_max) / 100.0, 2),
        'commission_source', v_source,
        'is_custom', v_custom IS NOT NULL
    );
END $function$;

-- @@ 50|function get_effective_permissions(uuid)
CREATE OR REPLACE FUNCTION public.get_effective_permissions(p_user uuid)
 RETURNS TABLE(permission text, scope text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_status uuid;
BEGIN
    SELECT st.status_id INTO v_status FROM public._actor_status(p_user) st;

    RETURN QUERY
    WITH base AS (
        SELECT p.slug AS perm, sp.scope AS sc
        FROM public.status_permissions sp
        JOIN public.permissions p ON p.id = sp.permission_id
        WHERE sp.status_id = v_status
        UNION ALL
        SELECT p.slug, up.scope
        FROM public.user_permissions up
        JOIN public.permissions p ON p.id = up.permission_id
        WHERE up.profile_id = p_user AND up.effect = 'grant'
          AND (up.expires_at IS NULL OR up.expires_at > now())
    ),
    revoked AS (
        SELECT p.slug AS perm
        FROM public.user_permissions up
        JOIN public.permissions p ON p.id = up.permission_id
        WHERE up.profile_id = p_user AND up.effect = 'revoke'
          AND (up.expires_at IS NULL OR up.expires_at > now())
    )
    SELECT b.perm, (array_agg(b.sc ORDER BY public._scope_rank(b.sc) DESC))[1]
    FROM base b
    WHERE b.perm NOT IN (SELECT perm FROM revoked)
    GROUP BY b.perm;
END;
$function$;

-- @@ 50|function get_employee_deliveries(uuid,text)
CREATE OR REPLACE FUNCTION public.get_employee_deliveries(p_employee_id uuid, p_token text)
 RETURNS TABLE(assignment_id uuid, checkout_id uuid, sequence_order integer, status text, delivery_address text, delivery_lat double precision, delivery_lng double precision, buyer_name text, buyer_profile_slug text)
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Verificação básica do token (exemplo: token = md5(employee_id || 'minha-chave-secreta'))
  -- No MVP, podemos confiar que o front-end já validou, mas essa função garante.
  IF p_token != md5(p_employee_id::text || 'chave-secreta-entregador') THEN
    RAISE EXCEPTION 'Token inválido';
  END IF;

  RETURN QUERY
  SELECT
    da.id,
    da.checkout_id,
    da.sequence_order,
    da.status,
    ss.delivery_address,
    ss.delivery_lat,
    ss.delivery_lng,
    ss.buyer_name,
    ss.buyer_profile_slug
  FROM public.delivery_assignments da
  JOIN public.store_sales ss ON ss.checkout_id = da.checkout_id
  WHERE da.employee_id = p_employee_id
  ORDER BY da.sequence_order;
END;
$function$;

