-- @@ 50|function get_group_members(uuid)
CREATE OR REPLACE FUNCTION public.get_group_members(p_conv uuid)
 RETURNS TABLE(profile_id uuid, name text, profile_slug text, avatar_url text, role text, status text, muted boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, p.name, p."profileSlug", p.avatar_url, cm.role, cm.status,
           (cm.profile_id = auth.uid() AND cm.muted)
    FROM public.conversation_members cm
    JOIN public.profiles p ON p.id = cm.profile_id
    WHERE cm.conversation_id = p_conv
      AND public._is_active_member(p_conv, auth.uid())
      AND cm.status IN ('active', 'invited')
    ORDER BY (cm.role = 'admin') DESC, (cm.status = 'active') DESC, cm.joined_at NULLS LAST, cm.created_at;
$function$;

-- @@ 50|function get_items_in_bounds(double precision,double precision,double precision,double precision,text,text,integer)
CREATE OR REPLACE FUNCTION public.get_items_in_bounds(min_lat double precision, min_lng double precision, max_lat double precision, max_lng double precision, search_query text DEFAULT ''::text, filter_type text DEFAULT 'todos'::text, limit_num integer DEFAULT 50)
 RETURNS TABLE(id uuid, type text, name text, description text, image_url text, lat double precision, lng double precision, slug text, store_slug text, price numeric, is_open boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
  envelope geography;
  search_pattern TEXT;
BEGIN
  -- ST_MakeEnvelope (GeoESPACIAL)
  envelope := ST_MakeEnvelope(min_lng, min_lat, max_lng, max_lat, 4326)::geography;
  
  -- Prepara var pra ILIKE (Busca textual)
  search_pattern := '%' || search_query || '%';

  RETURN QUERY
  SELECT * FROM (
    
    -- BUSCA NAS LOJAS
    SELECT 
      s.id,
      'loja' AS type,
      s.name,
      s.description,
      s.logo_url AS image_url,
      ST_Y(s.location::geometry) AS lat,
      ST_X(s.location::geometry) AS lng,
      s."storeSlug" AS slug,
      s."storeSlug" AS store_slug,
      0.0::NUMERIC AS price,
      COALESCE(s.is_open, true) AS is_open
    FROM stores s
    WHERE s.location IS NOT NULL
      AND s.location && envelope
      AND (search_query = '' OR s.name ILIKE search_pattern)
      AND (filter_type = 'todos' OR filter_type = 'lojas')
      
    UNION ALL

    -- BUSCA NOS PRODUTOS
    SELECT 
      p.id,
      'produto' AS type,
      p.name,
      p.description,
      p.image_url AS image_url,
      ST_Y(p.location::geometry) AS lat,
      ST_X(p.location::geometry) AS lng,
      p.slug AS slug,
      (SELECT "storeSlug" FROM stores WHERE stores.id = p.store_id) AS store_slug,
      p.price AS price,
      true AS is_open
    FROM products p
    WHERE p.location IS NOT NULL
      AND p.location && envelope
      AND (search_query = '' OR p.name ILIKE search_pattern)
      AND (filter_type = 'todos' OR filter_type = 'produtos')
      
  ) q
  LIMIT limit_num;
END;
$function$;

-- @@ 50|function get_last_seen_for(uuid[])
CREATE OR REPLACE FUNCTION public.get_last_seen_for(p_ids uuid[])
 RETURNS TABLE(profile_id uuid, last_seen_at timestamp with time zone, online boolean, appears_offline boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT pr.profile_id,
           pr.last_seen_at,
           (pr.mode <> 'offline' AND pr.online AND pr.last_seen_at > now() - interval '150 seconds') AS online,
           (pr.mode = 'offline') AS appears_offline
    FROM public.profile_presence pr
    WHERE pr.profile_id = ANY (p_ids[1:200])
      AND (pr.last_seen_at IS NOT NULL OR pr.mode = 'offline')
      AND (
          pr.profile_id = auth.uid()
          OR pr.visibility = 'all'
          OR (pr.visibility = 'following' AND auth.uid() IS NOT NULL
              AND EXISTS (SELECT 1 FROM public.follows f WHERE f.follower_id = pr.profile_id AND f.following_id = auth.uid()))
      );
$function$;

-- @@ 50|function get_levels_for(uuid[])
CREATE OR REPLACE FUNCTION public.get_levels_for(p_ids uuid[])
 RETURNS TABLE(user_id uuid, level_id uuid, level_name text, level_order integer, border_style text, border_color text, border_colors text[], background_style text, badge_style text, icon text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, l.id, l.name, l.level_order, l.border_style, l.border_color, l.border_colors, l.background_style, l.badge_style, l.icon
      FROM public.profiles p JOIN public.network_levels l ON l.id = public._effective_level_id(p.id)
     WHERE p.id = ANY (p_ids[1:200]);
$function$;

-- @@ 50|function get_live_location_for(uuid[])
CREATE OR REPLACE FUNCTION public.get_live_location_for(p_ids uuid[])
 RETURNS TABLE(profile_id uuid, lat double precision, lng double precision, updated_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT l.profile_id, round(l.lat::numeric, 3)::double precision, round(l.lng::numeric, 3)::double precision, l.updated_at
    FROM public.profile_live_location l
    JOIN public.profiles p ON p.id = l.profile_id
    WHERE l.profile_id = ANY (p_ids[1:100])
      AND p.live_location AND COALESCE(p.show_location, true)
      AND l.updated_at > now() - interval '6 hours';
$function$;

-- @@ 50|function get_my_border_claim_status()
CREATE OR REPLACE FUNCTION public.get_my_border_claim_status()
 RETURNS TABLE(border_id uuid, block_reason text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT b.id, public._avatar_border_block_reason(auth.uid(), b.id)
    FROM public.avatar_borders b
    WHERE b.is_active AND auth.uid() IS NOT NULL;
$function$;

-- @@ 50|function get_my_chat_unread_total()
CREATE OR REPLACE FUNCTION public.get_my_chat_unread_total()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT count(*) FROM public.conversations c
    WHERE auth.uid() IS NOT NULL
      AND (
        (c.kind = 'direct'
          AND (c.customer_id = auth.uid() OR c.owner_profile_id = auth.uid()
               OR EXISTS (SELECT 1 FROM public.stores s WHERE s.id = c.store_id AND s.owner_id = auth.uid()))
          AND EXISTS (
              SELECT 1 FROM public.direct_messages m
              WHERE m.conversation_id = c.id AND m.sender_id <> auth.uid()
                AND m.created_at > CASE WHEN c.customer_id = auth.uid() THEN c.customer_read_at ELSE COALESCE(c.owner_read_at, 'epoch'::timestamptz) END))
        OR
        (c.kind = 'group' AND EXISTS (
            SELECT 1 FROM public.conversation_members cm
            WHERE cm.conversation_id = c.id AND cm.profile_id = auth.uid() AND cm.status = 'active'
              AND EXISTS (SELECT 1 FROM public.direct_messages m
                          WHERE m.conversation_id = c.id AND m.sender_id <> auth.uid() AND m.created_at > cm.last_read_at)))
      );
$function$;

-- @@ 50|function get_my_commissions(integer)
CREATE OR REPLACE FUNCTION public.get_my_commissions(p_limit integer DEFAULT 30)
 RETURNS TABLE(id uuid, created_at timestamp with time zone, plan_type text, base_amount_cents bigint, commission_rate_bp integer, commission_amount_cents bigint, level_name text, is_custom boolean, commission_source text, status text, source_name text, source_slug text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT c.id, c.created_at, c.plan_type, c.base_amount_cents, c.commission_rate_bp, c.commission_amount_cents,
           c.level_name_snapshot, c.is_custom_commission, c.commission_source, c.status, p.name, p."profileSlug"
      FROM public.commissions c LEFT JOIN public.profiles p ON p.id = c.source_user_id
     WHERE c.user_id = auth.uid()
     ORDER BY c.created_at DESC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 30), 1), 200);
$function$;

-- @@ 50|function get_my_conversations(text,uuid)
CREATE OR REPLACE FUNCTION public.get_my_conversations(p_scope text DEFAULT 'profile'::text, p_store uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, role text, store_id uuid, last_message text, last_message_at timestamp with time zone, last_sender_id uuid, unread bigint, other_id uuid, other_name text, other_slug text, other_avatar text, other_is_store boolean, is_group boolean, member_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid();
BEGIN
    IF v_user IS NULL THEN RETURN; END IF;
    IF p_scope = 'store' THEN
        IF NOT EXISTS (SELECT 1 FROM public.stores s WHERE s.id = p_store AND s.owner_id = v_user) THEN RETURN; END IF;
        RETURN QUERY
        SELECT c.id, 'store_owner'::text, c.store_id, c.last_message, c.last_message_at, c.last_sender_id,
               (SELECT count(*) FROM public.direct_messages m WHERE m.conversation_id = c.id AND m.sender_id <> v_user
                   AND m.created_at > COALESCE(c.owner_read_at, 'epoch'::timestamptz)),
               p.id, p.name, p."profileSlug", p.avatar_url, false, false, 0::bigint
        FROM public.conversations c JOIN public.profiles p ON p.id = c.customer_id
        WHERE c.store_id = p_store AND c.kind = 'direct'
        ORDER BY COALESCE(c.last_message_at, c.created_at) DESC;
    ELSE
        RETURN QUERY
        SELECT t.id, t.role, t.store_id, t.last_message, t.last_message_at, t.last_sender_id, t.unread,
               t.other_id, t.other_name, t.other_slug, t.other_avatar, t.other_is_store, t.is_group, t.member_count
        FROM (
            SELECT c.id,
                   (CASE WHEN c.customer_id = v_user THEN 'customer' ELSE 'profile_owner' END)::text AS role,
                   c.store_id, c.last_message, c.last_message_at, c.last_sender_id,
                   (SELECT count(*) FROM public.direct_messages m WHERE m.conversation_id = c.id AND m.sender_id <> v_user
                       AND m.created_at > CASE WHEN c.customer_id = v_user THEN c.customer_read_at ELSE COALESCE(c.owner_read_at, 'epoch'::timestamptz) END) AS unread,
                   CASE WHEN c.customer_id <> v_user THEN cp.id WHEN c.store_id IS NOT NULL THEN st.id ELSE op.id END AS other_id,
                   CASE WHEN c.customer_id <> v_user THEN cp.name WHEN c.store_id IS NOT NULL THEN st.name ELSE op.name END AS other_name,
                   CASE WHEN c.customer_id <> v_user THEN cp."profileSlug" WHEN c.store_id IS NOT NULL THEN st."storeSlug" ELSE op."profileSlug" END AS other_slug,
                   CASE WHEN c.customer_id <> v_user THEN cp.avatar_url WHEN c.store_id IS NOT NULL THEN st.logo_url ELSE op.avatar_url END AS other_avatar,
                   (c.customer_id = v_user AND c.store_id IS NOT NULL) AS other_is_store,
                   false AS is_group, 0::bigint AS member_count,
                   COALESCE(c.last_message_at, c.created_at) AS sort_at
            FROM public.conversations c
            JOIN public.profiles cp ON cp.id = c.customer_id
            LEFT JOIN public.profiles op ON op.id = c.owner_profile_id
            LEFT JOIN public.stores st ON st.id = c.store_id
            WHERE c.kind = 'direct' AND (c.customer_id = v_user OR c.owner_profile_id = v_user)
            UNION ALL
            SELECT c.id, 'member'::text, NULL::uuid, c.last_message, c.last_message_at, c.last_sender_id,
                   (SELECT count(*) FROM public.direct_messages m WHERE m.conversation_id = c.id AND m.sender_id <> v_user
                       AND m.created_at > cm.last_read_at),
                   c.id, c.title, NULL::text, c.avatar_url, false,
                   true, (SELECT count(*) FROM public.conversation_members x WHERE x.conversation_id = c.id AND x.status = 'active'),
                   COALESCE(c.last_message_at, c.created_at)
            FROM public.conversations c
            JOIN public.conversation_members cm ON cm.conversation_id = c.id AND cm.profile_id = v_user AND cm.status = 'active'
            WHERE c.kind = 'group'
        ) t
        ORDER BY t.sort_at DESC;
    END IF;
END; $function$;

-- @@ 50|function get_my_graduation()
CREATE OR REPLACE FUNCTION public.get_my_graduation()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_me uuid := auth.uid();
    v_s public.user_network_state;
    v_level public.network_levels;
    v_high public.network_levels;
    v_next public.network_levels;
    v_pre jsonb; v_pos jsonb;
    v_directs integer;
    v_settings public.network_settings;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Faça login para ver a sua graduação.' USING ERRCODE = '42501'; END IF;
    PERFORM public.check_and_upgrade_user_level(v_me);   -- garante que o nível está em dia
    SELECT * INTO v_s FROM public.user_network_state WHERE user_id = v_me;
    SELECT * INTO v_settings FROM public.network_settings WHERE id;
    v_pre := public.get_effective_commission(v_me, 'prepaid');
    v_pos := public.get_effective_commission(v_me, 'postpaid');
    SELECT * INTO v_level FROM public.network_levels WHERE id = (v_pre ->> 'level_id')::uuid;
    SELECT * INTO v_high FROM public.network_levels WHERE id = COALESCE(v_s.highest_level_id, public._initial_level_id());
    SELECT * INTO v_next FROM public.network_levels WHERE is_active AND level_order > v_level.level_order ORDER BY level_order LIMIT 1;
    v_directs := public._count_valid_directs(v_me);

    RETURN jsonb_build_object(
        'level', to_jsonb(v_level),
        'highest_level', to_jsonb(v_high),
        'level_achieved_at', v_s.level_achieved_at,
        'direct_referrals', v_directs,
        'total_network', public._count_network(v_me),
        'standard_prepaid_bp', v_level.commission_prepaid_bp,
        'standard_postpaid_bp', v_level.commission_postpaid_bp,
        'has_custom', COALESCE(v_s.custom_commission_enabled, false),
        'custom_prepaid_bp', v_s.custom_commission_prepaid_bp,
        'custom_postpaid_bp', v_s.custom_commission_postpaid_bp,
        'effective_prepaid', v_pre,
        'effective_postpaid', v_pos,
        'next_level', CASE WHEN v_next.id IS NULL THEN NULL ELSE to_jsonb(v_next) END,
        'progress_percent', CASE WHEN v_next.id IS NULL THEN 100
                                 WHEN v_next.min_direct_referrals <= 0 THEN 100
                                 ELSE LEAST(100, floor(v_directs * 100.0 / v_next.min_direct_referrals)) END,
        'levels', COALESCE((SELECT jsonb_agg(to_jsonb(l) ORDER BY l.level_order) FROM public.network_levels l WHERE l.is_active), '[]'::jsonb),
        'prepaid_price_cents', (SELECT round(price * 100)::bigint FROM public.plans WHERE code = 'pre_pago'),
        'postpaid_reference_cents', v_settings.postpaid_reference_cents,
        'history', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('type', h.change_type, 'reason', h.reason, 'at', h.created_at, 'previous', pl.name, 'new', nl.name) ORDER BY h.created_at DESC)
            FROM (SELECT * FROM public.user_level_history WHERE user_id = v_me ORDER BY created_at DESC LIMIT 10) h
            LEFT JOIN public.network_levels pl ON pl.id = h.previous_level_id
            LEFT JOIN public.network_levels nl ON nl.id = h.new_level_id
        ), '[]'::jsonb)
    );
END $function$;

-- @@ 50|function get_my_grantable_plans()
CREATE OR REPLACE FUNCTION public.get_my_grantable_plans()
 RETURNS TABLE(id uuid, code text, name text, description text, price numeric, permission_used text, scope text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
