$function$;

-- @@ 50|function get_my_group_invites()
CREATE OR REPLACE FUNCTION public.get_my_group_invites()
 RETURNS TABLE(conversation_id uuid, title text, invited_by uuid, inviter_name text, inviter_slug text, inviter_avatar text, member_count bigint, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT c.id, c.title, cm.invited_by, ip.name, ip."profileSlug", ip.avatar_url,
           (SELECT count(*) FROM public.conversation_members x WHERE x.conversation_id = c.id AND x.status = 'active'),
           cm.created_at
    FROM public.conversation_members cm
    JOIN public.conversations c ON c.id = cm.conversation_id AND c.kind = 'group'
    LEFT JOIN public.profiles ip ON ip.id = cm.invited_by
    WHERE cm.profile_id = auth.uid() AND cm.status = 'invited'
    ORDER BY cm.created_at DESC;
$function$;

-- @@ 50|function get_my_notifications(integer)
CREATE OR REPLACE FUNCTION public.get_my_notifications(p_limit integer DEFAULT 80)
 RETURNS TABLE(id uuid, kind text, ref_id uuid, meta jsonb, created_at timestamp with time zone, read_at timestamp with time zone, actor_id uuid, actor_name text, actor_slug text, actor_avatar text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT n.id, n.kind, n.ref_id, n.meta, n.created_at, n.read_at, a.id, a.name, a."profileSlug", a.avatar_url
    FROM public.profile_notifications n
    LEFT JOIN public.profiles a ON a.id = n.actor_id
    WHERE n.profile_id = auth.uid()
    ORDER BY n.created_at DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 80), 1), 200);
$function$;

-- @@ 50|function get_my_notifications_unread()
CREATE OR REPLACE FUNCTION public.get_my_notifications_unread()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
