$function$;

-- @@ 50|function get_my_payout_status()
CREATE OR REPLACE FUNCTION public.get_my_payout_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT jsonb_build_object(
        'required', COALESCE((SELECT new_delivery_flow_enabled FROM public.delivery_dispatch_settings WHERE id), false),
        'registered', k.driver_id IS NOT NULL, 'type', k.pix_key_type,
        'masked', CASE WHEN k.driver_id IS NOT NULL THEN public._pix_mask(k.pix_key_type, k.pix_key) END)
      FROM (SELECT auth.uid() AS uid) u LEFT JOIN public.driver_payout_keys k ON k.driver_id = u.uid
$function$;

-- @@ 50|function get_my_points()
CREATE OR REPLACE FUNCTION public.get_my_points()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT jsonb_build_object(
        'total', COALESCE((SELECT total FROM public.profile_points WHERE profile_id = auth.uid()), 0),
        'rules', COALESCE((SELECT jsonb_agg(jsonb_build_object('action', r.action, 'label', r.label, 'description', r.description,
                    'points', r.points, 'daily_limit', r.daily_limit) ORDER BY r.sort_order) FROM public.point_rules r WHERE r.is_active AND r.points > 0), '[]'::jsonb),
        'by_action', COALESCE((SELECT jsonb_agg(jsonb_build_object('action', e.action, 'times', e.times, 'points', e.pts)) FROM (
                    SELECT action, count(*) AS times, sum(points) AS pts FROM public.profile_points_events WHERE profile_id = auth.uid() GROUP BY action) e), '[]'::jsonb)
    ) WHERE auth.uid() IS NOT NULL;
$function$;

-- @@ 50|function get_my_status()
CREATE OR REPLACE FUNCTION public.get_my_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    v_status record;
BEGIN
    IF v_uid IS NULL THEN RETURN NULL; END IF;
    SELECT s.slug, s.name, s.level, st.description INTO v_status
    FROM public._actor_status(v_uid) s
    JOIN public.user_statuses st ON st.id = s.status_id;

    RETURN jsonb_build_object(
        'slug', COALESCE(v_status.slug, 'usuario'),
        'name', COALESCE(v_status.name, 'Usuário'),
        'level', COALESCE(v_status.level, 0),
        'description', v_status.description,
        'permissions', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('slug', e.permission, 'name', p.name, 'scope', e.scope) ORDER BY p.name)
            FROM public.get_effective_permissions(v_uid) e
            JOIN public.permissions p ON p.slug = e.permission
        ), '[]'::jsonb)
    );
END;
$function$;

-- @@ 50|function get_network_children(uuid,integer,integer)
CREATE OR REPLACE FUNCTION public.get_network_children(p_parent uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 30, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, name text, profile_slug text, avatar_url text, joined_at timestamp with time zone, is_valid boolean, direct_count integer, level_id uuid, level_name text, level_order integer, border_style text, border_color text, border_colors text[], background_style text, badge_style text, icon text, rate_prepaid_bp integer, rate_postpaid_bp integer, is_custom boolean, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me uuid := auth.uid(); v_parent uuid;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Faça login para ver a sua rede.' USING ERRCODE = '42501'; END IF;
    v_parent := COALESCE(p_parent, v_me);
    IF v_parent <> v_me AND NOT EXISTS (
        WITH RECURSIVE up AS (
            SELECT pr.id, pr.upline_id, 1 AS depth FROM public.profiles pr WHERE pr.id = v_parent
            UNION ALL
            SELECT pr.id, pr.upline_id, u.depth + 1 FROM public.profiles pr JOIN up u ON pr.id = u.upline_id WHERE u.depth < 50
        )
        SELECT 1 FROM up WHERE up.id = v_me AND up.id <> v_parent
    ) THEN
        RAISE EXCEPTION 'Você só pode ver a sua própria rede.' USING ERRCODE = '42501';
    END IF;
    RETURN QUERY SELECT * FROM public._network_children(v_parent, p_limit, p_offset);
END $function$;

-- @@ 50|function get_network_counts(uuid)
CREATE OR REPLACE FUNCTION public.get_network_counts(p_user_id uuid)
 RETURNS TABLE(level integer, count bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        (nlevel(d.path) - nlevel(p.path))::int AS level,
        COUNT(d.id)::bigint AS count
    FROM public.profiles d
    JOIN public.profiles p ON d.path <@ p.path AND d.id != p.id
    WHERE p.id = p_user_id
      AND (nlevel(d.path) - nlevel(p.path)) <= 5
    GROUP BY (nlevel(d.path) - nlevel(p.path));
END;
$function$;

-- @@ 50|function get_order_delivery_view(uuid)
CREATE OR REPLACE FUNCTION public.get_order_delivery_view(p_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE o public.orders; s public.stores; d public.order_delivery_dispatches; v_driver jsonb; v_uid uuid := auth.uid();
BEGIN
    SELECT * INTO o FROM public.orders WHERE id = p_order;
    IF NOT FOUND THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT * INTO s FROM public.stores WHERE id = o.store_id;
    IF v_uid IS NULL OR (o.buyer_id IS DISTINCT FROM v_uid AND s.owner_id IS DISTINCT FROM v_uid) THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE order_id = o.id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('flow_version', o.delivery_flow_version, 'has_delivery', false, 'order_status', o.status);
    END IF;
    IF d.flow_version = 2 AND d.status = 'accepted' THEN
        SELECT jsonb_build_object('slug', p."profileSlug", 'name', p.name) INTO v_driver
          FROM public.ride_requests r JOIN public.profiles p ON p.id = r.driver_id WHERE r.id = d.ride_request_id;
    END IF;
    RETURN jsonb_build_object(
        'flow_version', d.flow_version, 'has_delivery', true, 'order_status', o.status,
        'phase', d.phase, 'state', CASE WHEN d.flow_version = 2 THEN public._v2_state_code(d.phase, d.status) END,
        'estimated_freight', d.estimated_freight,
        'current_offer', CASE WHEN d.status = 'searching' THEN d.final_freight END,
        'frozen_freight', d.frozen_freight,
        'definitive', d.frozen_freight IS NOT NULL AND d.phase IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE'),
        'items_total', o.total_amount - COALESCE(o.delivery_fee, 0),
        'delivery_fee', o.delivery_fee, 'total_amount', o.total_amount,
        'reserved_until', CASE WHEN d.reservation_released_at IS NULL THEN d.reserved_until END,
        'reservation_released_at', d.reservation_released_at, 'reservation_release_reason', d.reservation_release_reason,
        'search_end_reason', d.search_end_reason, 'driver', v_driver);
END;
$function$;

-- @@ 50|function get_order_review_state(uuid)
CREATE OR REPLACE FUNCTION public.get_order_review_state(p_order uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); o public.orders; s public.stores; v_role text; cr public.customer_reviews; pr record;
BEGIN
    SELECT * INTO o FROM public.orders WHERE id = p_order;
    IF NOT FOUND THEN RETURN NULL; END IF;
    SELECT * INTO s FROM public.stores WHERE id = o.store_id;
    v_role := CASE WHEN s.owner_id = v_user THEN 'store' WHEN o.buyer_id = v_user THEN 'buyer' ELSE NULL END;
    IF v_role IS NULL THEN RETURN NULL; END IF;

    SELECT * INTO cr FROM public.customer_reviews WHERE order_id = o.id;
    SELECT rating, comment, is_anonymous INTO pr FROM public.product_reviews
    WHERE order_id = o.id AND store_id = s.id ORDER BY created_at DESC LIMIT 1;

    RETURN jsonb_build_object(
        'enabled', s.mutual_reviews,
        'role', v_role,
        'paid', o.status = 'paid',
        'store_name', s.name,
        'can_review', (v_role = 'store' AND s.mutual_reviews AND o.status = 'paid' AND o.buyer_id IS NOT NULL AND cr.id IS NULL),
        'store_review', CASE WHEN cr.id IS NULL THEN NULL
                             ELSE jsonb_build_object('rating', cr.rating, 'comment', cr.comment, 'created_at', cr.created_at) END,
        'buyer_review', CASE WHEN pr.rating IS NULL THEN NULL
                             ELSE jsonb_build_object('rating', pr.rating, 'comment', pr.comment) END
    );
END; $function$;

-- @@ 50|function get_people_on_map(integer)
CREATE OR REPLACE FUNCTION public.get_people_on_map(p_limit integer DEFAULT 200)
 RETURNS TABLE(id uuid, name text, profile_slug text, avatar_url text, lat double precision, lng double precision, is_live boolean, points integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, p.name, p."profileSlug", p.avatar_url,
           round(COALESCE(CASE WHEN live.ok THEN live.lat END, p.store_lat)::numeric, 3)::double precision,
           round(COALESCE(CASE WHEN live.ok THEN live.lng END, p.store_lng)::numeric, 3)::double precision,
           COALESCE(live.ok, false),
           COALESCE(pp.total, 0)
    FROM public.profiles p
    LEFT JOIN public.profile_points pp ON pp.profile_id = p.id
    LEFT JOIN LATERAL (
        SELECT true AS ok, l.lat, l.lng FROM public.profile_live_location l
        WHERE l.profile_id = p.id AND p.live_location AND l.updated_at > now() - interval '6 hours'
    ) live ON true
    WHERE p.is_active
      AND COALESCE(p.show_location, true)
      AND p.show_on_map
      AND COALESCE(CASE WHEN live.ok THEN live.lat END, p.store_lat) IS NOT NULL
      AND COALESCE(CASE WHEN live.ok THEN live.lng END, p.store_lng) IS NOT NULL
      AND p.id IS DISTINCT FROM auth.uid()
    ORDER BY COALESCE(pp.total, 0) DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 200), 1), 300);
$function$;

-- @@ 50|function get_permission_scope(uuid,text)
CREATE OR REPLACE FUNCTION public.get_permission_scope(p_user uuid, p_permission text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT e.scope FROM public.get_effective_permissions(p_user) e
    WHERE e.permission = p_permission
       OR (e.permission = 'grant_any_plan' AND p_permission LIKE 'grant\_%')
    ORDER BY public._scope_rank(e.scope) DESC
    LIMIT 1;
$function$;

-- @@ 50|function get_photo_campaign(uuid)
CREATE OR REPLACE FUNCTION public.get_photo_campaign(p_community uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user uuid := auth.uid(); c public.communities; v_today date; v_member boolean; v_voted uuid; v_has boolean; v_list jsonb;
BEGIN
    SELECT * INTO c FROM public.communities WHERE id = p_community;
    IF NOT FOUND THEN RETURN NULL; END IF;
    PERFORM public._community_close_rounds(p_community);
    SELECT * INTO c FROM public.communities WHERE id = p_community;
    v_today := public._community_today(p_community);
    v_member := public._community_is_member(p_community, v_user);
    SELECT candidate_id INTO v_voted FROM public.community_photo_votes
    WHERE community_id = p_community AND round_day = v_today AND voter_id = v_user;
    v_has := v_voted IS NOT NULL;

    SELECT COALESCE(jsonb_agg(row_to_json(t) ORDER BY t.rank_votes DESC, t.created_at ASC), '[]'::jsonb) INTO v_list
    FROM (
        SELECT cand.id, cand.image_url, cand.created_at,
               (cand.proposer_id = v_user) AS is_mine,
               (cand.id = v_voted) AS my_vote,
               pr."profileSlug" AS proposer_slug,
               (SELECT count(*) FROM public.community_photo_votes v WHERE v.candidate_id = cand.id) AS rank_votes,
               CASE WHEN v_has THEN (SELECT count(*) FROM public.community_photo_votes v WHERE v.candidate_id = cand.id) ELSE NULL END AS votes
        FROM public.community_photo_candidates cand
        JOIN public.profiles pr ON pr.id = cand.proposer_id
        WHERE cand.community_id = p_community AND cand.round_day = v_today AND cand.outcome IS NULL
    ) t;

    -- rank_votes só ordenava: não sai no resultado
    RETURN jsonb_build_object(
        'current_image', c.image_url,
        'kind', c.kind,
        'is_member', v_member,
        'has_voted', v_has,
        'candidates', (SELECT COALESCE(jsonb_agg(e - 'rank_votes'), '[]'::jsonb) FROM jsonb_array_elements(v_list) e)
    );
END; $function$;

-- @@ 50|function get_plan_ring_users(uuid[])
CREATE OR REPLACE FUNCTION public.get_plan_ring_users(p_ids uuid[])
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id
    FROM public.profiles p
    WHERE p.id = ANY (p_ids[1:200])
      AND (
          -- Administrador geral
          EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p.id AND u.email = 'ncastelano@gmail.com')
          -- Qualquer posição da hierarquia (do administrador pra baixo), tenha plano ou não
          OR EXISTS (SELECT 1 FROM public.user_statuses s WHERE s.id = p.status_id AND s.is_active)
          -- Pré-pago ativo (pago, brinde, código, concedido)
          OR EXISTS (
              SELECT 1 FROM public.subscriptions sub
              JOIN public.plans pl ON pl.id = sub.plan_id
              WHERE sub.user_id = p.id AND pl.code = 'pre_pago' AND sub.status = 'active'
                AND (sub.starts_at IS NULL OR sub.starts_at <= now())
                AND sub.current_period_end > now()
          )
      );
$function$;

-- @@ 50|function get_plan_subscriber_counts()
CREATE OR REPLACE FUNCTION public.get_plan_subscriber_counts()
 RETURNS TABLE(plan_id uuid, active_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT s.plan_id, count(*) AS active_count
    FROM public.subscriptions s
    WHERE s.status IN ('pending', 'active')
    GROUP BY s.plan_id;
$function$;

-- @@ 50|function get_profile_busy_slots(uuid,date,date)
CREATE OR REPLACE FUNCTION public.get_profile_busy_slots(p_profile_id uuid, p_from date, p_to date)
 RETURNS TABLE(slot_date text, slot_time text, duration_minutes integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT a.date::text, a.time::text, COALESCE(a.duration_minutes, 60)
    FROM public.appointments a
    WHERE a.store_id IS NULL
      AND a.direction = 'outgoing'
      AND a.provider_profile_id = p_profile_id
      AND a.customer_id IS DISTINCT FROM p_profile_id
      AND a.status::text NOT IN ('cancelled', 'declined', 'rejected')
      AND a.date::date BETWEEN p_from AND p_to;
$function$;

-- @@ 50|function get_profile_city(text)
CREATE OR REPLACE FUNCTION public.get_profile_city(p_slug text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT (SELECT m[1] || ' - ' || m[2] FROM regexp_match(p.address, ',\s*([^,]+?)\s-\s([^,]+?)(?:,|$)') m)
    FROM public.profiles p
    WHERE p."profileSlug" = p_slug AND p.show_location IS NOT FALSE
    LIMIT 1
$function$;

-- @@ 50|function get_profile_whatsapp(uuid)
CREATE OR REPLACE FUNCTION public.get_profile_whatsapp(p_profile uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me uuid := auth.uid(); v_wa text; v_ok boolean;
BEGIN
    IF v_me IS NULL OR p_profile IS NULL THEN RETURN NULL; END IF;
    SELECT p.whatsapp,
           (p.id = v_me)
           OR (coalesce(p.is_active, true) AND (
                coalesce(p.is_seller, false) OR coalesce(p.service_mode_active, false)
                OR EXISTS (SELECT 1 FROM public.stores s WHERE s.owner_id = p.id)
                OR EXISTS (SELECT 1 FROM public.products pr WHERE pr.owner_id = p.id AND coalesce(pr.is_active, true))
           ))
           OR EXISTS (
                SELECT 1 FROM public.service_applications sa
                JOIN public.service_requests sr ON sr.id = sa.service_request_id
                WHERE (sa.applicant_id = v_me AND sr.requester_id = p.id)
                   OR (sa.applicant_id = p.id AND sr.requester_id = v_me)
           )
      INTO v_wa, v_ok
    FROM public.profiles p WHERE p.id = p_profile;
    IF NOT coalesce(v_ok, false) THEN RETURN NULL; END IF;
    RETURN NULLIF(btrim(v_wa), '');
END $function$;

-- @@ 50|function get_profiles_ranking_info(uuid[])
CREATE OR REPLACE FUNCTION public.get_profiles_ranking_info(p_ids uuid[])
 RETURNS TABLE(id uuid, points integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.id, COALESCE(pp.total, 0)
    FROM public.profiles p
    LEFT JOIN public.profile_points pp ON pp.profile_id = p.id
    WHERE p.id = ANY (p_ids[1:200]);
$function$;

-- @@ 50|function get_radar_metrics()
CREATE OR REPLACE FUNCTION public.get_radar_metrics()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT jsonb_build_object(
        'stores', COALESCE((
            SELECT jsonb_object_agg(x.id::text, jsonb_build_object('sales', x.sales, 'comments', x.comments, 'followers', x.followers))
            FROM (
                SELECT st.id,
                    (SELECT count(*) FROM public.orders o WHERE o.store_id = st.id AND o.status = 'paid') AS sales,
                    (SELECT count(*) FROM public.comments c JOIN public.products p ON p.id = c.publication_id WHERE p.store_id = st.id)
                      + (SELECT count(*) FROM public.product_reviews r WHERE r.store_id = st.id AND btrim(COALESCE(r.comment, '')) <> '') AS comments,
                    (SELECT count(*) FROM public.follows f WHERE f.following_id = st.id) AS followers
                FROM public.stores st
            ) x
        ), '{}'::jsonb),
        'products', COALESCE((
            SELECT jsonb_object_agg(y.id::text, jsonb_build_object('sales', y.sales, 'comments', y.comments))
            FROM (
                SELECT p.id,
                    COALESCE((SELECT sum(oi.quantity) FROM public.order_items oi JOIN public.orders o ON o.id = oi.order_id
                              WHERE oi.product_id = p.id AND o.status = 'paid'), 0) AS sales,
                    (SELECT count(*) FROM public.comments c WHERE c.publication_id = p.id)
                      + (SELECT count(*) FROM public.product_reviews r WHERE r.product_id = p.id AND btrim(COALESCE(r.comment, '')) <> '') AS comments
                FROM public.products p
            ) y
        ), '{}'::jsonb)
    );
$function$;

-- @@ 50|function get_referral_commission_summary()
CREATE OR REPLACE FUNCTION public.get_referral_commission_summary()
 RETURNS TABLE(downline_id uuid, name text, avatar_url text, profile_slug text, joined_at timestamp with time zone, active_plans text, plan_price numeric, postpaid_debt numeric, commission_total numeric, sales json)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        p.id AS downline_id,
        p.name,
        p.avatar_url,
        p."profileSlug" AS profile_slug,
        p.created_at AS joined_at,
        (
            SELECT string_agg(pl.name, ' + ' ORDER BY pl.price DESC)
            FROM public.subscriptions s
            JOIN public.plans pl ON pl.id = s.plan_id
            WHERE s.user_id = p.id AND s.status = 'active' AND s.current_period_end > now()
        ) AS active_plans,
        COALESCE((
            SELECT sum(pl.price)
            FROM public.subscriptions s
            JOIN public.plans pl ON pl.id = s.plan_id
            WHERE s.user_id = p.id AND s.status = 'active' AND s.current_period_end > now()
        ), 0) AS plan_price,
        public.get_driver_postpaid_debt(p.id) AS postpaid_debt,
        COALESCE((
            SELECT sum(w.amount)
            FROM public.wallet_transactions w
            JOIN public.subscriptions s2 ON s2.id = w.source_subscription_id
            WHERE s2.user_id = p.id
                AND w.user_id = auth.uid()
                AND w.type = 'commission_credit'
        ), 0) AS commission_total,
        (
            SELECT COALESCE(json_agg(json_build_object(
                'plan_name', pl3.name,
                'amount', w3.amount,
                'date', w3.created_at
            ) ORDER BY w3.created_at DESC), '[]'::json)
            FROM public.wallet_transactions w3
            JOIN public.subscriptions s3 ON s3.id = w3.source_subscription_id
            JOIN public.plans pl3 ON pl3.id = s3.plan_id
            WHERE s3.user_id = p.id
                AND w3.user_id = auth.uid()
                AND w3.type = 'commission_credit'
        ) AS sales
    FROM public.profiles p
    WHERE p.upline_id = auth.uid()
    ORDER BY p.created_at DESC;
$function$;

-- @@ 50|function get_requester_tip_counts(uuid[])
CREATE OR REPLACE FUNCTION public.get_requester_tip_counts(p_ids uuid[])
 RETURNS TABLE(profile_id uuid, tips integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
