-- @@ 50|function get_ride_applicant_locations(uuid)
CREATE OR REPLACE FUNCTION public.get_ride_applicant_locations(p_ride uuid)
 RETURNS TABLE(profile_id uuid, lat double precision, lng double precision)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me uuid := auth.uid();
BEGIN
    IF v_me IS NULL THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.ride_requests r WHERE r.id = p_ride AND r.requester_id = v_me) THEN RETURN; END IF;
    RETURN QUERY
        SELECT p.id, round(p.store_lat::numeric, 2)::double precision, round(p.store_lng::numeric, 2)::double precision
        FROM public.profiles p
        WHERE p.store_lat IS NOT NULL AND p.store_lng IS NOT NULL
          AND (p.id IN (SELECT a.applicant_id FROM public.ride_applications a WHERE a.ride_request_id = p_ride)
               OR p.id IN (SELECT r.driver_id FROM public.ride_requests r WHERE r.id = p_ride AND r.driver_id IS NOT NULL));
END $function$;

-- @@ 50|function get_store_order_counts()
CREATE OR REPLACE FUNCTION public.get_store_order_counts()
 RETURNS TABLE(store_id uuid, orders_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT o.store_id, count(*)::bigint
    FROM public.orders o
    JOIN public.stores s ON s.id = o.store_id AND s.is_active
    WHERE o.status NOT IN ('pending', 'rejected', 'cancelled', 'canceled')
    GROUP BY o.store_id;
$function$;

-- @@ 50|function get_store_order_whatsapp(uuid)
CREATE OR REPLACE FUNCTION public.get_store_order_whatsapp(p_store uuid)
 RETURNS TABLE(whatsapp text, orders_enabled boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me uuid := auth.uid();
BEGIN
    IF v_me IS NULL OR p_store IS NULL THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.orders o WHERE o.store_id = p_store AND o.buyer_id = v_me) THEN RETURN; END IF;
    RETURN QUERY
        SELECT COALESCE(NULLIF(btrim(s.whatsapp), ''), NULLIF(btrim(o.whatsapp), '')),
               s.whatsapp_orders_enabled IS DISTINCT FROM false
        FROM public.stores s LEFT JOIN public.profiles o ON o.id = s.owner_id
        WHERE s.id = p_store;
END $function$;

-- @@ 50|function get_store_ordered_products(uuid,uuid)
CREATE OR REPLACE FUNCTION public.get_store_ordered_products(p_store_id uuid, p_exclude_product uuid DEFAULT NULL::uuid)
 RETURNS TABLE(product_id uuid, buyers bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT oi.product_id, COUNT(DISTINCT COALESCE(o.buyer_id::text, o.id::text)) AS buyers
    FROM public.orders o
    JOIN public.order_items oi ON oi.order_id = o.id
    JOIN public.products p ON p.id = oi.product_id AND p.store_id = p_store_id AND p.is_active
    WHERE o.store_id = p_store_id
      AND o.status NOT IN ('cancelled', 'canceled', 'rejected')
      AND (p_exclude_product IS NULL OR oi.product_id <> p_exclude_product)
    GROUP BY oi.product_id
    ORDER BY buyers DESC, MAX(o.created_at) DESC
    LIMIT 12;
$function$;

-- @@ 50|function get_store_price_ranges()
CREATE OR REPLACE FUNCTION public.get_store_price_ranges()
 RETURNS TABLE(store_id uuid, min_price numeric, max_price numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT p.store_id, min(p.price), max(p.price)
    FROM public.products p
    JOIN public.stores s ON s.id = p.store_id AND s.is_active
    WHERE p.store_id IS NOT NULL
      AND p.is_active IS NOT FALSE
      AND p.listing_type = 'sale'
      AND p.price IS NOT NULL AND p.price > 0
    GROUP BY p.store_id;
$function$;

-- @@ 50|function get_store_whatsapp(uuid)
CREATE OR REPLACE FUNCTION public.get_store_whatsapp(p_store uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me uuid := auth.uid(); v_wa text; v_ok boolean;
BEGIN
    IF v_me IS NULL OR p_store IS NULL THEN RETURN NULL; END IF;
    SELECT COALESCE(NULLIF(btrim(s.whatsapp), ''), NULLIF(btrim(o.whatsapp), '')),
           (s.owner_id = v_me) OR (coalesce(s.is_active, true) AND s.show_whatsapp IS NOT FALSE)
      INTO v_wa, v_ok
    FROM public.stores s LEFT JOIN public.profiles o ON o.id = s.owner_id
    WHERE s.id = p_store;
    IF NOT coalesce(v_ok, false) THEN RETURN NULL; END IF;
    RETURN v_wa;
END $function$;

-- @@ 50|function get_stores_with_distance(double precision,double precision,double precision)
CREATE OR REPLACE FUNCTION public.get_stores_with_distance(user_lat double precision, user_lng double precision, max_distance double precision)
 RETURNS TABLE(id uuid, name text, description text, category text, address text, "profileSlug" text, logo_url text, banner_url text, store_lat double precision, store_lng double precision, distance_km double precision, ratings_avg numeric, ratings_count integer, is_open boolean)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        s.id,
        s.name,
        s.description,
        s.category,
        s.address,
        s."storeSlug" as "profileSlug",
        s.logo_url,
        s.banner_url,
        s.store_lat,
        s.store_lng,
        (6371 * acos(
            cos(radians(user_lat)) * cos(radians(s.store_lat)) *
            cos(radians(s.store_lng) - radians(user_lng)) +
            sin(radians(user_lat)) * sin(radians(s.store_lat))
        )) as distance_km,
        s.ratings_avg,
        s.ratings_count,
        CASE 
            WHEN s.business_hours IS NULL OR s.business_hours = '{}'::jsonb THEN false
            ELSE check_store_open(s.business_hours)
        END as is_open
    FROM 
        stores s
    WHERE 
        s.store_lat IS NOT NULL 
        AND s.store_lng IS NOT NULL
        AND s.is_active = true
        AND (
            6371 * acos(
                cos(radians(user_lat)) * cos(radians(s.store_lat)) *
                cos(radians(s.store_lng) - radians(user_lng)) +
                sin(radians(user_lat)) * sin(radians(s.store_lat))
            )
        ) <= max_distance
    ORDER BY 
        distance_km ASC;
END;
$function$;

-- @@ 50|function get_stores_with_distance(double precision,double precision)
CREATE OR REPLACE FUNCTION public.get_stores_with_distance(user_lat double precision, user_lng double precision)
 RETURNS TABLE(id uuid, name text, storeslug text, description text, logo_url text, address text, business_hours jsonb, is_open boolean, is_active boolean, view_count integer, ratings_avg double precision, ratings_count integer, accepts_delivery boolean, accepts_pickup boolean, delivery_type text, delivery_fee numeric, distance_meters double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        s.id,
        s.name,
        s.storeSlug,
        s.description,
        s.logo_url,
        s.address,
        s.business_hours,
        s.is_open,
        s.is_active,
        s.view_count,
        s.ratings_avg,
        s.ratings_count,
        s.accepts_delivery,
        s.accepts_pickup,
        s.delivery_type,
        s.delivery_fee,
        -- Calcula distância em metros usando a extensão earthdistance
        -- Se não tiver earthdistance, use a fórmula manual
        (
            SELECT ST_Distance(
                ST_SetSRID(ST_MakePoint(s.longitude, s.latitude), 4326)::geography,
                ST_SetSRID(ST_MakePoint(user_lng, user_lat), 4326)::geography
            )
        ) AS distance_meters
    FROM stores s
    WHERE s.is_active = true
    ORDER BY distance_meters ASC
    LIMIT 20;
END;
$function$;

-- @@ 50|function get_total_commissions(uuid)
CREATE OR REPLACE FUNCTION public.get_total_commissions(user_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    total decimal;
BEGIN
    SELECT COALESCE(SUM(amount), 0) INTO total
    FROM public.commissions
    WHERE earner_id = user_id;

    RETURN total;
END;
$function$;

-- @@ 50|function get_tracking_info(uuid)
CREATE OR REPLACE FUNCTION public.get_tracking_info(p_checkout_id uuid)
 RETURNS TABLE(employee_name text, employee_phone text, store_lat double precision, store_lng double precision, stops jsonb)
 LANGUAGE plpgsql
