-- @@ 50|function get_vip_campaigns(uuid)
CREATE OR REPLACE FUNCTION public.get_vip_campaigns(p_store_id uuid)
 RETURNS TABLE(campaign_id uuid, publication_id uuid, name text, description text, image_url text, discount_type text, discount_value numeric, product_ids uuid[], ends_at timestamp with time zone, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_is_member boolean;
    v_is_owner boolean;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM public.store_vip_members m
        WHERE m.store_id = p_store_id AND m.profile_id = auth.uid() AND m.status = 'active'
    ) INTO v_is_member;

    SELECT EXISTS(
        SELECT 1 FROM public.stores s WHERE s.id = p_store_id AND s.owner_id = auth.uid()
    ) INTO v_is_owner;

    IF NOT v_is_member AND NOT v_is_owner THEN
        RAISE EXCEPTION 'Você não é membro desse clube VIP';
    END IF;

    RETURN QUERY
    SELECT c.id, c.publication_id, p.name, p.description, p.image_url,
           c.discount_type, c.discount_value, c.product_ids, c.ends_at, c.created_at
    FROM public.store_campaigns c
    JOIN public.products p ON p.id = c.publication_id
    WHERE c.store_id = p_store_id
        AND c.active = true
        AND (c.ends_at IS NULL OR c.ends_at > now())
    ORDER BY c.created_at DESC;
END;
$function$;

-- @@ 50|function grant_plan_internal(uuid,uuid,uuid,integer,text,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.grant_plan_internal(p_actor uuid, p_target uuid, p_plan_id uuid, p_days integer, p_reason text DEFAULT NULL::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_plan public.plans;
    v_perm text;
    v_scope text;
    v_level integer;
    v_existing public.subscriptions;
    v_sub public.subscriptions;
    v_now timestamptz := now();
    v_start timestamptz;
    v_end timestamptz;
    v_source text;
    v_count integer;
    v_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
    v_deny_code text;
    v_deny_msg text;
BEGIN
    IF p_actor IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_actor) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'unauthenticated', 'message', 'Não autenticado');
    END IF;

    SELECT * INTO v_plan FROM public.plans WHERE id = p_plan_id;
    -- Início no passado (tolerância de 5 min) vira "agora".
    v_start := CASE WHEN p_starts_at IS NULL OR p_starts_at <= v_now + interval '5 minutes' THEN v_now ELSE p_starts_at END;

    <<checks>>
    BEGIN
        IF p_days IS NULL OR p_days < 1 OR p_days > 3650 THEN
            v_deny_code := 'invalid_duration'; v_deny_msg := 'Duração inválida'; EXIT checks;
        END IF;
        IF v_start > v_now + interval '366 days' THEN
            v_deny_code := 'invalid_start'; v_deny_msg := 'A data de início pode ser no máximo daqui a 1 ano'; EXIT checks;
        END IF;
        IF p_target IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_target) THEN
            v_deny_code := 'target_not_found'; v_deny_msg := 'Pessoa não encontrada'; EXIT checks;
        END IF;
        IF p_target = p_actor THEN
            v_deny_code := 'self_grant_denied'; v_deny_msg := 'Você não pode conceder um benefício para si mesmo'; EXIT checks;
        END IF;
        IF v_plan.id IS NULL THEN
            v_deny_code := 'plan_not_found'; v_deny_msg := 'Plano não encontrado'; EXIT checks;
        END IF;
        IF NOT v_plan.grantable THEN
            v_deny_code := 'plan_not_grantable'; v_deny_msg := 'Esse plano não pode ser concedido'; EXIT checks;
        END IF;

        SELECT a.permission, a.scope INTO v_perm, v_scope FROM public.resolve_grant_authority(p_actor, p_plan_id) a;
        IF v_perm IS NULL THEN
            v_deny_code := 'permission_denied'; v_deny_msg := 'Você não tem permissão para conceder esse plano'; EXIT checks;
        END IF;
        IF NOT public.is_in_scope(p_actor, p_target, v_scope) THEN
            v_deny_code := 'out_of_scope'; v_deny_msg := 'Essa pessoa está fora do seu escopo'; EXIT checks;
        END IF;

        SELECT * INTO v_existing FROM public.subscriptions
        WHERE user_id = p_target AND plan_id = p_plan_id AND status IN ('pending', 'active')
        FOR UPDATE;

        IF v_existing.id IS NOT NULL AND v_existing.source = 'asaas' AND v_existing.status = 'active'
           AND v_existing.current_period_end > v_now THEN
            v_deny_code := 'already_subscribed'; v_deny_msg := 'Essa pessoa já tem esse plano pago ativo'; EXIT checks;
        END IF;

        -- Agendar por cima de um benefício EM VIGOR apagaria o que ela tem
        -- hoje. Um agendamento que ainda não começou pode ser remarcado.
        IF v_start > v_now AND v_existing.id IS NOT NULL AND v_existing.status = 'active'
           AND (v_existing.starts_at IS NULL OR v_existing.starts_at <= v_now)
           AND v_existing.current_period_end > v_now THEN
            v_deny_code := 'already_active'; v_deny_msg := 'Essa pessoa já tem esse plano ativo — conceda sem data de início para estender'; EXIT checks;
        END IF;

        IF v_plan.max_active_subscriptions IS NOT NULL AND v_existing.id IS NULL THEN
            PERFORM pg_advisory_xact_lock(hashtext('plan_slots:' || v_plan.id::text));
            SELECT count(*) INTO v_count FROM public.subscriptions WHERE plan_id = v_plan.id AND status IN ('pending', 'active');
            IF v_count >= v_plan.max_active_subscriptions THEN
                v_deny_code := 'slots_full'; v_deny_msg := 'Vagas desse plano esgotadas'; EXIT checks;
            END IF;
        END IF;
    END;

    IF v_deny_code IS NOT NULL THEN
        PERFORM public._log_grant_event('grant_plan', 'denied', v_deny_code, p_actor, p_target, v_plan.id, v_plan.code,
                                        v_perm, v_scope, NULL, NULL, NULL, v_reason, '{}'::jsonb);
        RETURN jsonb_build_object('ok', false, 'code', v_deny_code, 'message', v_deny_msg);
    END IF;

    SELECT st.level INTO v_level FROM public._actor_status(p_actor) st;
    v_source := CASE WHEN COALESCE(v_level, 0) >= 4 THEN 'admin_grant' ELSE 'leader_grant' END;
    v_end := v_start + make_interval(days => p_days);

    BEGIN
        IF v_existing.id IS NOT NULL THEN
            UPDATE public.subscriptions
            SET status = 'active', source = v_source, current_period_end = v_end,
                starts_at = v_start, granted_by = p_actor, granted_reason = v_reason, updated_at = v_now
            WHERE id = v_existing.id
            RETURNING * INTO v_sub;
        ELSE
            INSERT INTO public.subscriptions (user_id, plan_id, status, source, current_period_end, starts_at, granted_by, granted_reason)
            VALUES (p_target, p_plan_id, 'active', v_source, v_end, v_start, p_actor, v_reason)
            RETURNING * INTO v_sub;
        END IF;
    EXCEPTION WHEN unique_violation THEN
        PERFORM public._log_grant_event('grant_plan', 'denied', 'conflict', p_actor, p_target, v_plan.id, v_plan.code,
                                        v_perm, v_scope, NULL, NULL, NULL, v_reason, '{}'::jsonb);
        RETURN jsonb_build_object('ok', false, 'code', 'conflict', 'message', 'Conflito ao conceder, tente de novo');
    END;

    PERFORM public._log_grant_event('grant_plan', 'granted', NULL, p_actor, p_target, v_plan.id, v_plan.code,
                                    v_perm, v_scope, v_sub.id, v_start, v_end, v_reason,
                                    jsonb_build_object('days', p_days, 'source', v_source, 'scheduled', v_start > v_now));

    RETURN jsonb_build_object('ok', true, 'subscription_id', v_sub.id, 'starts_at', v_start, 'expires_at', v_end);
END;
$function$;

-- @@ 50|function guard_orders_delete()
CREATE OR REPLACE FUNCTION public.guard_orders_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF current_user NOT IN ('authenticated', 'anon') THEN RETURN OLD; END IF;
    IF OLD.status <> 'pending'
       OR EXISTS (SELECT 1 FROM public.order_delivery_dispatches d WHERE d.order_id = OLD.id)
       OR EXISTS (SELECT 1 FROM public.ride_requests r WHERE r.order_id = OLD.id) THEN
        RAISE EXCEPTION 'Este pedido já está em andamento e não pode ser apagado' USING ERRCODE = '42501';
    END IF;
    RETURN OLD;
END;
$function$;

-- @@ 50|function guard_orders_update()
CREATE OR REPLACE FUNCTION public.guard_orders_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
    IF (to_jsonb(NEW) - ARRAY['status', 'updated_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status', 'updated_at']) THEN
        RAISE EXCEPTION 'Campo protegido do pedido: valores, vínculos e endereço não podem ser alterados' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NOT (
            (OLD.status = 'pending'   AND NEW.status IN ('preparing', 'rejected'))
         OR (OLD.status = 'preparing' AND NEW.status IN ('ready', 'paid', 'rejected'))
         OR (OLD.status = 'ready'     AND NEW.status IN ('paid', 'rejected'))
        ) THEN
            RAISE EXCEPTION 'Mudança de status do pedido não permitida: % → %', OLD.status, NEW.status USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function guard_profile_booking()
CREATE OR REPLACE FUNCTION public.guard_profile_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_allowed boolean;
    v_start integer;
    v_end integer;
BEGIN
    IF NEW.store_id IS NOT NULL OR NEW.direction IS DISTINCT FROM 'outgoing'
       OR NEW.provider_profile_id IS NULL OR NEW.customer_id IS NOT DISTINCT FROM NEW.provider_profile_id THEN
        RETURN NEW;
    END IF;

    SELECT allow_scheduling INTO v_allowed FROM public.profiles WHERE id = NEW.provider_profile_id;
    IF v_allowed IS NOT TRUE THEN
        RAISE EXCEPTION 'Este perfil não está recebendo agendamentos.';
    END IF;

    -- Serializa marcações concorrentes do mesmo perfil.
    PERFORM pg_advisory_xact_lock(hashtext(NEW.provider_profile_id::text));

    v_start := (EXTRACT(EPOCH FROM NEW.time::time) / 60)::integer;
    v_end := v_start + COALESCE(NEW.duration_minutes, 60);
    IF EXISTS (
        SELECT 1 FROM public.appointments a
        WHERE a.store_id IS NULL AND a.direction = 'outgoing'
          AND a.provider_profile_id = NEW.provider_profile_id
          AND a.customer_id IS DISTINCT FROM a.provider_profile_id
          AND a.status::text NOT IN ('cancelled', 'declined', 'rejected')
          AND a.date::date = NEW.date::date
          AND v_start < (EXTRACT(EPOCH FROM a.time::time) / 60)::integer + COALESCE(a.duration_minutes, 60)
          AND (EXTRACT(EPOCH FROM a.time::time) / 60)::integer < v_end
    ) THEN
        RAISE EXCEPTION 'Esse horário acabou de ser reservado. Escolha outro.';
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function guard_ride_applications_insert()
CREATE OR REPLACE FUNCTION public.guard_ride_applications_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_offered numeric;
    v_order uuid;
BEGIN
    IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
    IF NEW.status IS DISTINCT FROM 'pending' THEN
        RAISE EXCEPTION 'Candidatura nova começa pendente' USING ERRCODE = '42501';
    END IF;
    IF NEW.proposed_price IS NOT NULL AND (NEW.proposed_price <= 0 OR NEW.proposed_price > 100000) THEN
        RAISE EXCEPTION 'Valor inválido' USING ERRCODE = '42501';
    END IF;
    -- O frete de entrega de loja é fixo: quem aceita, aceita o valor oferecido (nada de preço próprio por aqui)
    SELECT order_id, offered_price INTO v_order, v_offered FROM public.ride_offers WHERE id = NEW.ride_request_id;
    IF v_order IS NOT NULL AND NEW.proposed_price IS DISTINCT FROM v_offered THEN
        RAISE EXCEPTION 'O frete desta entrega é fixo (R$ %): aceite o valor oferecido', v_offered USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function guard_ride_applications_update()
CREATE OR REPLACE FUNCTION public.guard_ride_applications_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
    IF (to_jsonb(NEW) - 'status') IS DISTINCT FROM (to_jsonb(OLD) - 'status') THEN
        RAISE EXCEPTION 'Campo protegido da candidatura' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (OLD.status = 'pending' AND NEW.status = 'rejected') THEN
        RAISE EXCEPTION 'Para escolher o motorista use a operação própria' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function guard_ride_requests_insert()
CREATE OR REPLACE FUNCTION public.guard_ride_requests_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
    IF NEW.requester_id IS DISTINCT FROM auth.uid() THEN
        RAISE EXCEPTION 'Corrida só pode ser criada em nome de quem está logado' USING ERRCODE = '42501';
    END IF;
    IF NEW.order_id IS NOT NULL OR NEW.store_id IS NOT NULL OR NEW.offered_price IS NOT NULL OR NEW.visible_radius_km IS NOT NULL THEN
        RAISE EXCEPTION 'Entrega de loja só é criada pelo servidor' USING ERRCODE = '42501';
    END IF;
    IF NEW.status IS DISTINCT FROM 'pending'
       OR NEW.driver_id IS NOT NULL OR NEW.cancelled_by IS NOT NULL
       OR NEW.driver_en_route IS TRUE OR NEW.driver_departed_at IS NOT NULL OR NEW.driver_arrived_at IS NOT NULL
       OR NEW.ride_started_at IS NOT NULL OR NEW.stop1_reached_at IS NOT NULL OR NEW.stop2_reached_at IS NOT NULL
       OR COALESCE(NEW.applicant_count, 0) <> 0
       OR NEW.extra_task_minutes IS NOT NULL OR NEW.extra_task_fee IS NOT NULL OR NEW.extra_task_description IS NOT NULL THEN
        RAISE EXCEPTION 'Corrida nova começa pendente, sem motorista e sem etapas' USING ERRCODE = '42501';
    END IF;
    NEW.share_token := substr(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 1, 40);
    NEW.share_closed_at := NULL;
    RETURN NEW;
END;
$function$;

-- @@ 50|function guard_ride_requests_update()
CREATE OR REPLACE FUNCTION public.guard_ride_requests_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    uid uuid := auth.uid();
    is_req boolean := (uid IS NOT NULL AND uid = OLD.requester_id);
    is_drv boolean := (uid IS NOT NULL AND OLD.driver_id IS NOT NULL AND uid = OLD.driver_id);
    allowed text[] := '{}';
    expected text;
BEGIN
    IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;
    IF NOT (is_req OR is_drv) THEN
        RAISE EXCEPTION 'Sem permissão para alterar esta corrida' USING ERRCODE = '42501';
    END IF;

    -- Colunas que cada papel pode mexer. Todo o resto (preço, loja, pedido, motorista, endereços...) é do servidor.
    IF is_req THEN allowed := allowed || ARRAY['status', 'cancelled_by']; END IF;
    IF is_drv THEN
        allowed := allowed || ARRAY['status', 'cancelled_by', 'driver_en_route', 'driver_departed_at', 'driver_arrived_at',
                                    'ride_started_at', 'stop1_reached_at', 'stop2_reached_at',
                                    'extra_task_minutes', 'extra_task_fee', 'extra_task_description'];
    END IF;
    IF (to_jsonb(NEW) - allowed) IS DISTINCT FROM (to_jsonb(OLD) - allowed) THEN
        RAISE EXCEPTION 'Campo protegido: só o servidor altera preço, vínculos e dados da corrida' USING ERRCODE = '42501';
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status THEN
        -- A única mudança de status direta é cancelar; aceitar e concluir têm função própria.
        IF NEW.status = 'cancelled' AND OLD.status IN ('pending', 'accepted') THEN
            expected := CASE WHEN is_req THEN 'requester' ELSE 'driver' END;
            IF NEW.cancelled_by IS DISTINCT FROM expected THEN
                RAISE EXCEPTION 'cancelled_by inválido' USING ERRCODE = '42501';
            END IF;
            IF NOT is_req AND OLD.status <> 'accepted' THEN
                RAISE EXCEPTION 'O motorista só cancela corrida que aceitou' USING ERRCODE = '42501';
            END IF;
        ELSE
            RAISE EXCEPTION 'Mudança de status não permitida por aqui (use a operação própria: aceitar, concluir ou cancelar)' USING ERRCODE = '42501';
        END IF;
    ELSIF NEW.cancelled_by IS DISTINCT FROM OLD.cancelled_by THEN
        RAISE EXCEPTION 'cancelled_by só muda ao cancelar' USING ERRCODE = '42501';
    END IF;

    -- Entrega de loja tem frete FIXO: o motorista não registra "tarefa extra" (valor a mais) nela
    IF OLD.order_id IS NOT NULL
       AND (NEW.extra_task_minutes, NEW.extra_task_fee, NEW.extra_task_description)
           IS DISTINCT FROM (OLD.extra_task_minutes, OLD.extra_task_fee, OLD.extra_task_description) THEN
        RAISE EXCEPTION 'O frete de entrega de loja é fixo: não aceita tarefa extra' USING ERRCODE = '42501';
    END IF;

    -- Etapas do motorista só existem com a corrida aceita, e uma vez gravadas não são reescritas.
    IF (NEW.driver_en_route, NEW.driver_departed_at, NEW.driver_arrived_at, NEW.ride_started_at, NEW.stop1_reached_at, NEW.stop2_reached_at,
        NEW.extra_task_minutes, NEW.extra_task_fee, NEW.extra_task_description)
       IS DISTINCT FROM
       (OLD.driver_en_route, OLD.driver_departed_at, OLD.driver_arrived_at, OLD.ride_started_at, OLD.stop1_reached_at, OLD.stop2_reached_at,
        OLD.extra_task_minutes, OLD.extra_task_fee, OLD.extra_task_description) THEN
        IF OLD.status <> 'accepted' THEN
            RAISE EXCEPTION 'Etapas da corrida só podem ser registradas com a corrida aceita' USING ERRCODE = '42501';
        END IF;
        IF (OLD.driver_departed_at IS NOT NULL AND NEW.driver_departed_at IS DISTINCT FROM OLD.driver_departed_at)
           OR (OLD.driver_arrived_at IS NOT NULL AND NEW.driver_arrived_at IS DISTINCT FROM OLD.driver_arrived_at)
           OR (OLD.ride_started_at IS NOT NULL AND NEW.ride_started_at IS DISTINCT FROM OLD.ride_started_at)
           OR (OLD.stop1_reached_at IS NOT NULL AND NEW.stop1_reached_at IS DISTINCT FROM OLD.stop1_reached_at)
           OR (OLD.stop2_reached_at IS NOT NULL AND NEW.stop2_reached_at IS DISTINCT FROM OLD.stop2_reached_at) THEN
            RAISE EXCEPTION 'Etapa já registrada não pode ser alterada' USING ERRCODE = '42501';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function guard_upline_change()
CREATE OR REPLACE FUNCTION public.guard_upline_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.upline_id IS NOT DISTINCT FROM OLD.upline_id THEN
        RETURN NEW;
    END IF;

    -- Sem auth.uid() = service role, admin, funções internas (ex: excluir conta zera o vínculo dos convidados)
    IF auth.uid() IS NULL OR auth.uid() <> NEW.id THEN
        RETURN NEW;
    END IF;

    IF OLD.upline_id IS NOT NULL THEN
        RAISE EXCEPTION 'Esta conta já foi convidada por alguém: o vínculo de convite não pode ser trocado.'
            USING ERRCODE = '42501';
    END IF;
    IF NEW.upline_id = NEW.id THEN
        RAISE EXCEPTION 'Uma conta não pode convidar a si mesma.' USING ERRCODE = '22023';
    END IF;
    IF NEW.upline_id IS NOT NULL AND public._upline_would_cycle(NEW.id, NEW.upline_id) THEN
        RAISE EXCEPTION 'Esse convite criaria um ciclo na rede.' USING ERRCODE = '22023';
    END IF;

    RETURN NEW;
END;
$function$;

-- @@ 50|function handle_new_user()
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO public.profiles (id, name, "profileSlug", upline_id)
  VALUES (
    NEW.id,
    NEW.raw_user_meta_data->>'name',
    NEW.raw_user_meta_data->>'profileSlug',
    (NEW.raw_user_meta_data->>'upline_id')::UUID
  );
  RETURN NEW;
END;
$function$;

