-- @@ 50|function has_permission(uuid,text)
CREATE OR REPLACE FUNCTION public.has_permission(p_user uuid, p_permission text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.get_effective_permissions(p_user) e
        WHERE e.permission = p_permission
           OR (e.permission = 'grant_any_plan' AND p_permission LIKE 'grant\_%')
    );
$function$;

-- @@ 50|function haversine_km(double precision,double precision,double precision,double precision)
CREATE OR REPLACE FUNCTION public.haversine_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$
    SELECT (6371 * 2 * asin(sqrt(
        power(sin(radians(lat2 - lat1) / 2), 2)
        + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)
    )))::numeric
$function$;

