-- @@ 50|function invite_to_group(uuid,uuid[])
CREATE OR REPLACE FUNCTION public.invite_to_group(p_conv uuid, p_members uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); m uuid; v_title text; v_count integer; v_new integer := 0; v_status text;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.conversation_members WHERE conversation_id = p_conv AND profile_id = v_user AND status = 'active' AND role = 'admin') THEN
        RAISE EXCEPTION 'Só quem administra o grupo pode convidar';
    END IF;
    SELECT title INTO v_title FROM public.conversations WHERE id = p_conv AND kind = 'group';
    IF v_title IS NULL THEN RAISE EXCEPTION 'Grupo não encontrado'; END IF;
    FOREACH m IN ARRAY COALESCE(p_members, ARRAY[]::uuid[]) LOOP
        CONTINUE WHEN m IS NULL OR m = v_user OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = m);
        SELECT status INTO v_status FROM public.conversation_members WHERE conversation_id = p_conv AND profile_id = m;
        CONTINUE WHEN v_status IN ('active', 'invited');
        SELECT count(*) INTO v_count FROM public.conversation_members WHERE conversation_id = p_conv AND status IN ('active', 'invited');
        IF v_count >= 30 THEN RAISE EXCEPTION 'Um grupo tem no máximo 30 pessoas'; END IF;
        INSERT INTO public.conversation_members (conversation_id, profile_id, role, status, invited_by, push_sent_at)
        VALUES (p_conv, m, 'member', 'invited', v_user, NULL)
        ON CONFLICT (conversation_id, profile_id) DO UPDATE
            SET status = 'invited', invited_by = v_user, push_sent_at = NULL, created_at = now();
        BEGIN
            PERFORM public._notify(m, 'group_invite', v_user, p_conv, jsonb_build_object('title', v_title), 'ginv:' || p_conv || ':' || m || ':' || extract(epoch FROM now())::bigint);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        v_new := v_new + 1;
    END LOOP;
    RETURN v_new;
END; $function$;

-- @@ 50|function is_in_scope(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.is_in_scope(p_actor uuid, p_target uuid, p_scope text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF p_actor IS NULL OR p_target IS NULL OR p_actor = p_target THEN RETURN false; END IF;

    IF p_scope = 'all' THEN
        RETURN EXISTS (SELECT 1 FROM public.profiles WHERE id = p_target);
    ELSIF p_scope IN ('direct_invite', 'direct_downline') THEN
        RETURN EXISTS (SELECT 1 FROM public.profiles WHERE id = p_target AND upline_id = p_actor);
    ELSIF p_scope = 'network' THEN
        -- Sobe a cadeia de convites a partir do alvo; se o ator aparece
        -- como upline em algum ponto, o alvo é da estrutura dele.
        RETURN EXISTS (
            WITH RECURSIVE chain AS (
                SELECT id, upline_id, 1 AS depth FROM public.profiles WHERE id = p_target
                UNION ALL
                SELECT pr.id, pr.upline_id, c.depth + 1
                FROM public.profiles pr JOIN chain c ON pr.id = c.upline_id
                WHERE c.depth < 20
            )
            SELECT 1 FROM chain WHERE upline_id = p_actor
        );
    END IF;
    RETURN false;
END;
$function$;

-- @@ 50|function is_postpaid_user(uuid)
CREATE OR REPLACE FUNCTION public.is_postpaid_user(p_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT EXISTS (
        SELECT 1 FROM public.subscriptions s
        JOIN public.plans p ON p.id = s.plan_id
        WHERE s.user_id = p_user_id AND p.code = 'pos_pago'
          AND s.status = 'active'
          AND (s.starts_at IS NULL OR s.starts_at <= now())
          AND s.current_period_end > now()
    )
    AND NOT EXISTS (
        SELECT 1 FROM public.subscriptions s
        JOIN public.plans p ON p.id = s.plan_id
        WHERE s.user_id = p_user_id AND p.code = 'pre_pago'
          AND s.status = 'active'
          AND (s.starts_at IS NULL OR s.starts_at <= now())
          AND s.current_period_end > now()
    );
$function$;

-- @@ 50|function join_community(uuid,text)
CREATE OR REPLACE FUNCTION public.join_community(p_community uuid, p_password text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_user uuid := auth.uid(); c public.communities; v_hash text;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra participar'; END IF;
    SELECT * INTO c FROM public.communities WHERE id = p_community;
    IF NOT FOUND THEN RAISE EXCEPTION 'Comunidade não encontrada'; END IF;
    IF c.requires_password THEN
        SELECT password_hash INTO v_hash FROM public.community_secrets WHERE community_id = c.id;
        IF v_hash IS NULL OR COALESCE(p_password, '') = '' OR crypt(p_password, v_hash) <> v_hash THEN
            RAISE EXCEPTION 'Senha incorreta';
        END IF;
    END IF;
    INSERT INTO public.community_members (community_id, profile_id) VALUES (c.id, v_user)
    ON CONFLICT (community_id, profile_id) DO NOTHING;
    RETURN true;
END; $function$;

-- @@ 50|function join_vip_club(uuid)
CREATE OR REPLACE FUNCTION public.join_vip_club(p_store_id uuid)
 RETURNS store_vip_members
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_store public.stores;
    v_member public.store_vip_members;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
    END IF;

    SELECT * INTO v_store FROM public.stores WHERE id = p_store_id;
    IF NOT FOUND OR NOT v_store.vip_club_enabled THEN
        RAISE EXCEPTION 'Essa loja não tem clube VIP ativo';
    END IF;
    IF v_store.vip_club_price IS NOT NULL THEN
        RAISE EXCEPTION 'Clube pago em breve';
    END IF;

    INSERT INTO public.store_vip_members (store_id, profile_id, status, source)
    VALUES (p_store_id, auth.uid(), 'active', 'free')
    ON CONFLICT (store_id, profile_id) DO UPDATE SET status = 'active'
    RETURNING * INTO v_member;

    RETURN v_member;
END;
$function$;

-- @@ 50|function leave_group(uuid)
CREATE OR REPLACE FUNCTION public.leave_group(p_conv uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_was_admin boolean; v_next uuid;
BEGIN
    IF v_user IS NULL THEN RETURN; END IF;
    SELECT (role = 'admin') INTO v_was_admin FROM public.conversation_members
    WHERE conversation_id = p_conv AND profile_id = v_user AND status = 'active';
    IF v_was_admin IS NULL THEN RETURN; END IF;
    UPDATE public.conversation_members SET status = 'left', role = 'member'
    WHERE conversation_id = p_conv AND profile_id = v_user;
    IF v_was_admin AND NOT EXISTS (SELECT 1 FROM public.conversation_members WHERE conversation_id = p_conv AND status = 'active' AND role = 'admin') THEN
        SELECT profile_id INTO v_next FROM public.conversation_members
        WHERE conversation_id = p_conv AND status = 'active' ORDER BY joined_at, created_at LIMIT 1;
        IF v_next IS NOT NULL THEN
            UPDATE public.conversation_members SET role = 'admin' WHERE conversation_id = p_conv AND profile_id = v_next;
        END IF;
    END IF;
END; $function$;

-- @@ 50|function link_user_to_network(uuid,uuid)
CREATE OR REPLACE FUNCTION public.link_user_to_network(p_user_id uuid, p_upline_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_current uuid;
BEGIN
    IF auth.uid() IS NULL OR auth.uid() <> p_user_id THEN
        RAISE EXCEPTION 'Só a própria conta pode aceitar um convite.' USING ERRCODE = '42501';
    END IF;
    IF p_upline_id IS NULL OR p_upline_id = p_user_id THEN
        RAISE EXCEPTION 'Convite inválido.' USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_upline_id) THEN
        RAISE EXCEPTION 'Quem convidou não foi encontrado.' USING ERRCODE = '22023';
    END IF;

    SELECT upline_id INTO v_current FROM public.profiles WHERE id = p_user_id FOR UPDATE;
    IF v_current IS NOT NULL THEN
        RAISE EXCEPTION 'Esta conta já foi convidada por alguém.' USING ERRCODE = '42501';
    END IF;
    IF public._upline_would_cycle(p_user_id, p_upline_id) THEN
        RAISE EXCEPTION 'Esse convite criaria um ciclo na rede.' USING ERRCODE = '22023';
    END IF;

    UPDATE public.profiles SET upline_id = p_upline_id, updated_at = now() WHERE id = p_user_id;
    RETURN jsonb_build_object('linked', true, 'upline_id', p_upline_id);
END;
$function$;

-- @@ 50|function list_network_internal(uuid,uuid,text,integer,integer,text)
CREATE OR REPLACE FUNCTION public.list_network_internal(p_actor uuid, p_parent uuid DEFAULT NULL::uuid, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_filter text DEFAULT 'all'::text)
 RETURNS TABLE(id uuid, name text, profile_slug text, avatar_url text, created_at timestamp with time zone, upline_id uuid, upline_name text, upline_slug text, status_slug text, status_name text, status_level integer, children_count bigint, active_plans text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_q text := btrim(COALESCE(p_search, ''));
    v_filter text := COALESCE(p_filter, 'all');
BEGIN
    IF NOT public.has_permission(p_actor, 'manage_hierarchy') THEN RETURN; END IF;

    RETURN QUERY
    SELECT p.id, p.name, p."profileSlug", p.avatar_url, p.created_at,
           p.upline_id, u.name, u."profileSlug",
           COALESCE(s.slug, 'usuario'), COALESCE(s.name, 'Usuário'), COALESCE(s.level, 0),
           (SELECT count(*) FROM public.profiles c WHERE c.upline_id = p.id),
           COALESCE((
               SELECT array_agg(DISTINCT pl.code)
               FROM public.subscriptions sb JOIN public.plans pl ON pl.id = sb.plan_id
               WHERE sb.user_id = p.id AND sb.status = 'active'
                 AND (sb.starts_at IS NULL OR sb.starts_at <= now()) AND sb.current_period_end > now()
           ), ARRAY[]::text[])
    FROM public.profiles p
    LEFT JOIN public.profiles u ON u.id = p.upline_id
    LEFT JOIN public.user_statuses s ON s.id = p.status_id
    WHERE (CASE
            WHEN v_q <> '' THEN (p.name ILIKE '%' || v_q || '%' OR p."profileSlug" ILIKE '%' || v_q || '%')
            WHEN p_parent IS NOT NULL THEN p.upline_id = p_parent
            ELSE true
          END)
      AND (CASE
            WHEN p_parent IS NOT NULL AND v_q = '' THEN true
            WHEN v_filter = 'invited' THEN p.upline_id IS NOT NULL
            WHEN v_filter = 'roots' THEN p.upline_id IS NULL
            WHEN v_filter LIKE 'status:%' THEN COALESCE(s.slug, 'usuario') = substr(v_filter, 8)
            ELSE true
          END)
    ORDER BY p.created_at DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200)
    OFFSET GREATEST(COALESCE(p_offset, 0), 0);
END;
$function$;

-- @@ 50|function log_event(text,uuid,uuid,uuid,jsonb,jsonb,text,inet,text,uuid)
CREATE OR REPLACE FUNCTION public.log_event(p_event_type text, p_user_id uuid DEFAULT NULL::uuid, p_target_user_id uuid DEFAULT NULL::uuid, p_performed_by uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb, p_changes jsonb DEFAULT NULL::jsonb, p_reason text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text, p_session_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_log_id UUID;
BEGIN
    INSERT INTO public.system_logs (
        event_type,
        user_id,
        target_user_id,
        performed_by,
        details,
        changes,
        reason,
        ip_address,
        user_agent,
        session_id
    ) VALUES (
        p_event_type,
        p_user_id,
        p_target_user_id,
        p_performed_by,
        p_details,
        p_changes,
        p_reason,
        p_ip_address,
        p_user_agent,
        p_session_id
    )
    RETURNING id INTO v_log_id;
    
    RETURN v_log_id;
END;
$function$;

-- @@ 50|function manage_hierarchy_internal(uuid,text,jsonb)
CREATE OR REPLACE FUNCTION public.manage_hierarchy_internal(p_actor uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_status public.user_statuses;
    v_perm public.permissions;
    v_target uuid;
    v_slug text;
    v_level integer;
    v_scope text;
    v_deny_code text;
    v_deny_msg text;
    -- permissões sem as quais o Administrador perderia o controle do sistema
    c_admin_required text[] := ARRAY['grant_any_plan', 'manage_leaders', 'manage_hierarchy'];
BEGIN
    IF NOT public.has_permission(p_actor, 'manage_hierarchy') THEN
        v_deny_code := 'permission_denied'; v_deny_msg := 'Você não pode gerenciar a hierarquia';
    END IF;

    IF v_deny_code IS NULL THEN
        <<work>>
        BEGIN
            IF p_action = 'upsert_status' THEN
                v_slug := lower(btrim(COALESCE(p_payload->>'slug', '')));
                v_level := (p_payload->>'level')::integer;
                IF v_slug !~ '^[a-z0-9_]{2,40}$' OR btrim(COALESCE(p_payload->>'name', '')) = '' OR v_level IS NULL OR v_level < 0 OR v_level > 100 THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Dados do status inválidos'; EXIT work;
                END IF;
                IF v_slug = 'usuario' AND (v_level <> 0 OR COALESCE((p_payload->>'is_active')::boolean, true) = false) THEN
                    v_deny_code := 'protected_status'; v_deny_msg := 'O status Usuário é fixo (nível 0, sempre ativo)'; EXIT work;
                END IF;
                IF v_slug = 'administrador' AND COALESCE((p_payload->>'is_active')::boolean, true) = false THEN
                    v_deny_code := 'protected_status'; v_deny_msg := 'O status Administrador não pode ser desativado'; EXIT work;
                END IF;
                IF v_slug <> 'usuario' AND v_level = 0 THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'O nível 0 é reservado ao status Usuário'; EXIT work;
                END IF;
                INSERT INTO public.user_statuses (slug, name, level, description, is_active)
                VALUES (v_slug, btrim(p_payload->>'name'), v_level, NULLIF(btrim(COALESCE(p_payload->>'description', '')), ''),
                        COALESCE((p_payload->>'is_active')::boolean, true))
                ON CONFLICT (slug) DO UPDATE
                SET name = EXCLUDED.name, level = EXCLUDED.level, description = EXCLUDED.description,
                    is_active = EXCLUDED.is_active, updated_at = now();

            ELSIF p_action = 'set_status_permission' THEN
                SELECT * INTO v_status FROM public.user_statuses WHERE slug = p_payload->>'status_slug';
                SELECT * INTO v_perm FROM public.permissions WHERE slug = p_payload->>'permission_slug';
                v_scope := p_payload->>'scope';
                IF v_status.id IS NULL OR v_perm.id IS NULL OR v_scope NOT IN ('direct_invite', 'direct_downline', 'network', 'all') THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Status, permissão ou escopo inválido'; EXIT work;
                END IF;
                IF v_status.slug = 'administrador' AND v_perm.slug = ANY (c_admin_required) AND v_scope <> 'all' THEN
                    v_deny_code := 'protected_status'; v_deny_msg := 'Essa permissão do Administrador precisa ter escopo total'; EXIT work;
                END IF;
                INSERT INTO public.status_permissions (status_id, permission_id, scope)
                VALUES (v_status.id, v_perm.id, v_scope)
                ON CONFLICT (status_id, permission_id) DO UPDATE SET scope = EXCLUDED.scope;

            ELSIF p_action = 'remove_status_permission' THEN
                SELECT * INTO v_status FROM public.user_statuses WHERE slug = p_payload->>'status_slug';
                SELECT * INTO v_perm FROM public.permissions WHERE slug = p_payload->>'permission_slug';
                IF v_status.id IS NULL OR v_perm.id IS NULL THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Status ou permissão inválido'; EXIT work;
                END IF;
                IF v_status.slug = 'administrador' AND v_perm.slug = ANY (c_admin_required) THEN
                    v_deny_code := 'protected_status'; v_deny_msg := 'O Administrador não pode perder essa permissão'; EXIT work;
                END IF;
                DELETE FROM public.status_permissions WHERE status_id = v_status.id AND permission_id = v_perm.id;

            ELSIF p_action = 'set_plan_grant_settings' THEN
                IF NOT EXISTS (SELECT 1 FROM public.plans WHERE id = (p_payload->>'plan_id')::uuid) THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Plano não encontrado'; EXIT work;
                END IF;
                v_slug := NULLIF(p_payload->>'grant_permission', '');
                IF v_slug IS NOT NULL AND (v_slug NOT LIKE 'grant\_%' OR v_slug = 'grant_any_plan'
                        OR NOT EXISTS (SELECT 1 FROM public.permissions WHERE slug = v_slug)) THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Permissão de concessão inválida'; EXIT work;
                END IF;
                UPDATE public.plans
                SET grantable = COALESCE((p_payload->>'grantable')::boolean, grantable), grant_permission = v_slug
                WHERE id = (p_payload->>'plan_id')::uuid;

            ELSIF p_action = 'set_user_permission' THEN
                v_target := (p_payload->>'profile_id')::uuid;
                SELECT * INTO v_perm FROM public.permissions WHERE slug = p_payload->>'permission_slug';
                v_scope := NULLIF(p_payload->>'scope', '');
                IF v_target IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_target) OR v_perm.id IS NULL
                   OR p_payload->>'effect' NOT IN ('grant', 'revoke')
                   OR (p_payload->>'effect' = 'grant' AND (v_scope IS NULL OR v_scope NOT IN ('direct_invite', 'direct_downline', 'network', 'all'))) THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Pessoa, permissão, efeito ou escopo inválido'; EXIT work;
                END IF;
                IF v_target = p_actor AND p_payload->>'effect' = 'revoke' THEN
                    v_deny_code := 'self_change_denied'; v_deny_msg := 'Você não pode revogar as próprias permissões'; EXIT work;
                END IF;
                INSERT INTO public.user_permissions (profile_id, permission_id, effect, scope, expires_at, granted_by, reason)
                VALUES (v_target, v_perm.id, p_payload->>'effect', CASE WHEN p_payload->>'effect' = 'grant' THEN v_scope END,
                        NULLIF(p_payload->>'expires_at', '')::timestamptz, p_actor, NULLIF(btrim(COALESCE(p_payload->>'reason', '')), ''))
                ON CONFLICT (profile_id, permission_id) DO UPDATE
                SET effect = EXCLUDED.effect, scope = EXCLUDED.scope, expires_at = EXCLUDED.expires_at,
                    granted_by = EXCLUDED.granted_by, reason = EXCLUDED.reason, created_at = now();

            ELSIF p_action = 'remove_user_permission' THEN
                v_target := (p_payload->>'profile_id')::uuid;
                SELECT * INTO v_perm FROM public.permissions WHERE slug = p_payload->>'permission_slug';
                IF v_target IS NULL OR v_perm.id IS NULL THEN
                    v_deny_code := 'invalid_payload'; v_deny_msg := 'Pessoa ou permissão inválida'; EXIT work;
                END IF;
                DELETE FROM public.user_permissions WHERE profile_id = v_target AND permission_id = v_perm.id;

            ELSE
                v_deny_code := 'unknown_action'; v_deny_msg := 'Ação desconhecida';
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_deny_code := 'invalid_payload'; v_deny_msg := 'Dados inválidos';
        END;
    END IF;

    IF v_deny_code IS NOT NULL THEN
        PERFORM public._log_grant_event('hierarchy_change', 'denied', v_deny_code, p_actor, NULL, NULL, NULL,
                                        'manage_hierarchy', NULL, NULL, NULL, NULL, NULL,
                                        jsonb_build_object('action', p_action, 'payload', p_payload));
        RETURN jsonb_build_object('ok', false, 'code', v_deny_code, 'message', v_deny_msg);
    END IF;

    PERFORM public._log_grant_event('hierarchy_change', 'granted', NULL, p_actor, NULL, NULL, NULL,
                                    'manage_hierarchy', 'all', NULL, NULL, NULL, NULL,
                                    jsonb_build_object('action', p_action, 'payload', p_payload));
    RETURN jsonb_build_object('ok', true);
END;
$function$;

-- @@ 50|function mark_all_notifications_as_read(uuid)
CREATE OR REPLACE FUNCTION public.mark_all_notifications_as_read(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_count INTEGER;
BEGIN
    UPDATE public.notifications
    SET 
        is_read = TRUE,
        read_at = NOW(),
        updated_at = NOW()
    WHERE user_id = p_user_id 
    AND is_read = FALSE;
    
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$function$;

-- @@ 50|function mark_conversation_read(uuid)
CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_conv uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); c public.conversations;
BEGIN
    IF NOT public._can_access_conversation(p_conv, v_user) THEN RETURN; END IF;
    SELECT * INTO c FROM public.conversations WHERE id = p_conv;
    IF c.kind = 'group' THEN
        UPDATE public.conversation_members SET last_read_at = now() WHERE conversation_id = p_conv AND profile_id = v_user;
    ELSIF c.customer_id = v_user THEN
        UPDATE public.conversations SET customer_read_at = now() WHERE id = p_conv;
    ELSE
        UPDATE public.conversations SET owner_read_at = now() WHERE id = p_conv;
    END IF;
END; $function$;

-- @@ 50|function mark_notification_as_read(uuid,uuid)
CREATE OR REPLACE FUNCTION public.mark_notification_as_read(p_notification_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    UPDATE public.notifications
    SET 
        is_read = TRUE,
        read_at = NOW(),
        updated_at = NOW()
    WHERE id = p_notification_id 
    AND user_id = p_user_id;
    
    RETURN FOUND;
END;
$function$;

-- @@ 50|function mark_notifications_read(uuid[])
CREATE OR REPLACE FUNCTION public.mark_notifications_read(p_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    UPDATE public.profile_notifications SET read_at = now()
    WHERE profile_id = auth.uid() AND read_at IS NULL AND (p_ids IS NULL OR id = ANY (p_ids));
$function$;

-- @@ 50|function network_summary_internal(uuid)
CREATE OR REPLACE FUNCTION public.network_summary_internal(p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.has_permission(p_actor, 'manage_hierarchy') THEN RETURN NULL; END IF;
    RETURN jsonb_build_object(
        'total', (SELECT count(*) FROM public.profiles),
        'roots', (SELECT count(*) FROM public.profiles WHERE upline_id IS NULL),
        'invited', (SELECT count(*) FROM public.profiles WHERE upline_id IS NOT NULL),
        'by_status', COALESCE((
            SELECT jsonb_agg(jsonb_build_object('slug', x.slug, 'name', x.name, 'level', x.level, 'count', x.cnt) ORDER BY x.level)
            FROM (
                SELECT COALESCE(s.slug, 'usuario') AS slug, COALESCE(s.name, 'Usuário') AS name,
                       COALESCE(s.level, 0) AS level, count(*) AS cnt
                FROM public.profiles p LEFT JOIN public.user_statuses s ON s.id = p.status_id
                GROUP BY 1, 2, 3
            ) x
        ), '[]'::jsonb)
    );
END;
$function$;

-- @@ 50|function normalize_profile_slug()
CREATE OR REPLACE FUNCTION public.normalize_profile_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.profile_slug = lower(trim(new.profile_slug));
    return new;
end;
$function$;

-- @@ 50|function on_auth_user_created()
CREATE OR REPLACE FUNCTION public.on_auth_user_created()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.users (id, email, name, name_page, image)
  values (
    new.id,
    new.email,
    new.user_metadata->>'name',       -- pegar do user_metadata se existir
    new.user_metadata->>'name_page',  -- opcional, se você usa
    new.user_metadata->>'image'  -- imagem do usuário, se preencher
  );
  return new;
end;
$function$;

-- @@ 50|function open_delivery_incident(uuid,text,text)
CREATE OR REPLACE FUNCTION public.open_delivery_incident(p_dispatch uuid, p_kind text, p_description text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); d public.order_delivery_dispatches; v_role text; v_driver uuid; v_owner uuid; v_id uuid;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch;
    IF NOT FOUND OR d.flow_version <> 2 OR v_uid IS NULL THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT owner_id INTO v_owner FROM public.stores WHERE id = d.store_id;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;
    v_role := CASE WHEN v_uid = v_owner THEN 'store' WHEN v_uid = v_driver THEN 'driver' WHEN v_uid = d.customer_id THEN 'customer' END;
    IF v_role IS NULL THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF p_kind NOT IN ('divergence', 'cancellation_contested', 'operational', 'other') THEN RAISE EXCEPTION 'Tipo de ocorrência inválido' USING ERRCODE = '22023'; END IF;
    IF p_description IS NULL OR char_length(btrim(p_description)) < 3 OR char_length(p_description) > 2000 THEN RAISE EXCEPTION 'Descreva o problema (3 a 2000 caracteres)' USING ERRCODE = '22023'; END IF;
    SELECT id INTO v_id FROM public.delivery_incidents WHERE dispatch_id = d.id AND opened_by = v_uid AND kind = p_kind AND status IN ('open', 'under_review');
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;                      -- idempotente: já existe uma aberta igual
    INSERT INTO public.delivery_incidents (dispatch_id, order_id, ride_request_id, store_id, driver_id, kind, description, opened_by, opened_role)
    VALUES (d.id, d.order_id, d.ride_request_id, d.store_id, v_driver, p_kind, btrim(p_description), v_uid, v_role) RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$;

-- @@ 50|function orders_start_delivery_on_accept()
CREATE OR REPLACE FUNCTION public.orders_start_delivery_on_accept()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status = 'preparing' AND OLD.status IS DISTINCT FROM 'preparing' THEN
        IF NEW.delivery_flow_version = 2 THEN
            PERFORM public._start_order_delivery_dispatch(NEW.id);        -- V2: falha visível (o aceite não passa sem entrega)
        ELSE
            BEGIN
                PERFORM public._start_order_delivery_dispatch(NEW.id);
            EXCEPTION WHEN OTHERS THEN
                RAISE WARNING 'delivery dispatch failed for order %: %', NEW.id, SQLERRM;
            END;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function prevent_reserved_slug()
CREATE OR REPLACE FUNCTION public.prevent_reserved_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin

    if exists (
        select 1
        from public.reserved_slugs
        where slug = new.profile_slug
    ) then
        raise exception 'profile slug reservado';
    end if;

    return new;

end;
$function$;

-- @@ 50|function process_delivery_search_v2()
CREATE OR REPLACE FUNCTION public.process_delivery_search_v2()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_res text; v_n integer := 0;
BEGIN
    FOR r IN
        SELECT id FROM public.order_delivery_dispatches
         WHERE flow_version = 2 AND status = 'searching'
           AND (offer_expires_at IS NULL OR offer_expires_at <= now() OR phase = 'AGUARDANDO_AUTORIZACAO_REAJUSTE')
         ORDER BY created_at
         FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            v_res := public._advance_delivery_search_v2(r.id);
            IF v_res LIKE 'round:%' OR v_res LIKE 'ended:%' OR v_res = 'asked' THEN v_n := v_n + 1; END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'busca V2 falhou na entrega %: %', r.id, SQLERRM;
        END;
    END LOOP;
    FOR r IN
        SELECT id FROM public.order_delivery_dispatches
         WHERE flow_version = 2 AND status = 'accepted' AND reserved_until <= now() AND reservation_released_at IS NULL
           AND phase IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE')
         ORDER BY reserved_until
         FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            v_res := public._v2_expire_reservation(r.id);
            IF v_res LIKE 'expired:%' THEN v_n := v_n + 1; END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'reserva V2 falhou na entrega %: %', r.id, SQLERRM;
        END;
    END LOOP;
    FOR r IN
        SELECT id FROM public.order_delivery_dispatches
         WHERE flow_version = 2 AND status = 'accepted' AND reserved_until <= now()
           AND phase IN ('LOJA_INFORMOU_RECEBIMENTO', 'AGUARDANDO_PAGAMENTO_ENTREGADOR', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR')
         ORDER BY reserved_until
         FOR UPDATE SKIP LOCKED
    LOOP
        BEGIN
            v_res := public._v2_financial_timeout(r.id);
            IF v_res LIKE 'timeout:%' THEN v_n := v_n + 1; END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'janela financeira V2 falhou na entrega %: %', r.id, SQLERRM;
        END;
    END LOOP;
    IF v_n > 0 THEN PERFORM public._ping_delivery_events(); END IF;
    RETURN v_n;
END;
$function$;

-- @@ 50|function process_order_delivery_dispatches()
CREATE OR REPLACE FUNCTION public.process_order_delivery_dispatches()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    cfg public.delivery_dispatch_settings;
    d public.order_delivery_dispatches;
    v_ride_status text;
    v_inc numeric;
    v_new_final numeric;
    v_radius numeric;
    v_platform numeric;
    v_round uuid;
    v_count integer := 0;
BEGIN
    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    FOR d IN
        SELECT * FROM public.order_delivery_dispatches
        WHERE flow_version = 1 AND status = 'searching' AND round_started_at + make_interval(mins => cfg.retry_interval_minutes) <= now()
        FOR UPDATE SKIP LOCKED
    LOOP
        SELECT status INTO v_ride_status FROM public.ride_requests WHERE id = d.ride_request_id;
        IF v_ride_status IS DISTINCT FROM 'pending' THEN
            UPDATE public.order_delivery_dispatches
               SET status = CASE v_ride_status WHEN 'accepted' THEN 'accepted' WHEN 'completed' THEN 'completed' ELSE 'cancelled' END, updated_at = now()
             WHERE id = d.id;
            CONTINUE;
        END IF;

        IF d.round - 1 >= cfg.max_rounds THEN CONTINUE; END IF;

        UPDATE public.order_delivery_rounds SET status = 'expired' WHERE dispatch_id = d.id AND status = 'pending_customer';

        v_radius := d.radius_km + cfg.radius_step_km;
        v_inc := CASE cfg.increase_kind WHEN 'percent' THEN round(d.final_freight * cfg.increase_value / 100, 2) ELSE cfg.increase_value END;
        v_inc := LEAST(v_inc, cfg.max_freight - d.final_freight);
        IF v_inc < 0 THEN v_inc := 0; END IF;

        UPDATE public.ride_requests SET visible_radius_km = v_radius WHERE id = d.ride_request_id;
        UPDATE public.order_delivery_dispatches SET round = d.round + 1, radius_km = v_radius, round_started_at = now(), updated_at = now() WHERE id = d.id;

        IF v_inc > 0 THEN
            v_new_final := d.final_freight + v_inc;
            v_platform := round(v_new_final * cfg.platform_fee_percent / 100, 2);
            INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status)
            VALUES (d.id, d.round + 1, 'increase', d.original_freight, d.authorized_extra + v_inc, v_new_final, v_platform, v_new_final - v_platform, v_radius, 'pending_customer')
            RETURNING id INTO v_round;
        ELSE
            v_platform := round(d.final_freight * cfg.platform_fee_percent / 100, 2);
            INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status)
            VALUES (d.id, d.round + 1, 'radius_only', d.original_freight, d.authorized_extra, d.final_freight, v_platform, d.final_freight - v_platform, v_radius, 'radius_only')
            RETURNING id INTO v_round;
            v_round := NULL;
        END IF;
        INSERT INTO public.order_delivery_events (dispatch_id, kind, old_radius, new_radius, round_id) VALUES (d.id, 'tick', d.radius_km, v_radius, v_round);
        v_count := v_count + 1;
    END LOOP;
    IF v_count > 0 THEN PERFORM public._ping_delivery_events(); END IF;
    RETURN v_count;
END;
$function$;

-- @@ 50|function propose_community_photo(uuid,text)
CREATE OR REPLACE FUNCTION public.propose_community_photo(p_community uuid, p_image_url text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); c public.communities; v_today date; v_id uuid; v_n int;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    SELECT * INTO c FROM public.communities WHERE id = p_community;
    IF NOT FOUND THEN RAISE EXCEPTION 'Comunidade não encontrada'; END IF;
    IF c.kind <> 'place' THEN RAISE EXCEPTION 'A foto dessa comunidade é escolhida por quem a criou'; END IF;
    IF NOT public._community_is_member(p_community, v_user) THEN RAISE EXCEPTION 'Entre na comunidade primeiro'; END IF;
    IF COALESCE(btrim(p_image_url), '') = '' THEN RAISE EXCEPTION 'Foto inválida'; END IF;
    PERFORM public._community_close_rounds(p_community);
    v_today := public._community_today(p_community);

    SELECT count(*) INTO v_n FROM public.community_photo_candidates
    WHERE community_id = p_community AND round_day = v_today AND outcome IS NULL AND proposer_id <> v_user;
    IF v_n >= 12 THEN RAISE EXCEPTION 'A votação de hoje já tem fotos demais. Tente amanhã'; END IF;

    DELETE FROM public.community_photo_candidates
    WHERE community_id = p_community AND round_day = v_today AND proposer_id = v_user AND outcome IS NULL;
    INSERT INTO public.community_photo_candidates (community_id, proposer_id, image_url, round_day)
    VALUES (p_community, v_user, p_image_url, v_today) RETURNING id INTO v_id;
    RETURN v_id;
END; $function$;

-- @@ 50|function queue_push_notifications()
CREATE OR REPLACE FUNCTION public.queue_push_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    INSERT INTO public.notifications_queue (notification_id, push_token_id)
    SELECT NEW.id, pt.id
    FROM public.push_tokens pt
    WHERE pt.user_id = NEW.user_id;
    
    RETURN NEW;
END;
$function$;

-- @@ 50|function recheck_all_levels()
CREATE OR REPLACE FUNCTION public.recheck_all_levels()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_n integer := 0;
BEGIN
    FOR v_id IN SELECT DISTINCT upline_id FROM public.profiles WHERE upline_id IS NOT NULL LOOP
        IF (public.check_and_upgrade_user_level(v_id) ->> 'upgraded')::boolean THEN v_n := v_n + 1; END IF;
    END LOOP;
    RETURN v_n;
END $function$;

-- @@ 50|function record_delivery_estimate(uuid,uuid,double precision,double precision,integer,text,text,text)
CREATE OR REPLACE FUNCTION public.record_delivery_estimate(p_customer uuid, p_store uuid, p_lat double precision, p_lng double precision, p_distance_m integer, p_distance_source text, p_destination_check text, p_address text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    s public.stores;
    v_straight_m integer;
    v_radius numeric;
    v_calc jsonb;
    v_snap jsonb;
    v_id uuid;
    v_exp timestamptz := now() + interval '30 minutes';
    v_addr text := public._norm_address(p_address);
BEGIN
    IF v_addr IS NULL OR length(v_addr) < 5 THEN RAISE EXCEPTION 'Endereço inválido' USING ERRCODE = '22023'; END IF;
    IF p_distance_source NOT IN ('route', 'straight_line') OR p_destination_check NOT IN ('verified', 'unverified') THEN
        RAISE EXCEPTION 'Origem de distância inválida';
    END IF;
    IF p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -34 AND 6 OR p_lng NOT BETWEEN -74 AND -28 THEN
        RAISE EXCEPTION 'Destino fora do Brasil ou inválido' USING ERRCODE = '22023';
    END IF;
    SELECT * INTO s FROM public.stores WHERE id = p_store;
    IF NOT FOUND THEN RAISE EXCEPTION 'Loja não encontrada'; END IF;
    IF NOT (COALESCE(s.accepts_delivery, false) AND COALESCE(s.iuser_delivery_enabled, false)) THEN
        RAISE EXCEPTION 'Esta loja não usa a entrega iUser' USING ERRCODE = '22023';
    END IF;
    IF s.store_lat IS NULL OR s.store_lng IS NULL THEN RAISE EXCEPTION 'A loja não tem localização cadastrada'; END IF;

    v_straight_m := round(public.haversine_km(s.store_lat, s.store_lng, p_lat, p_lng) * 1000)::integer;
    SELECT max_radius_km INTO v_radius FROM public.delivery_dispatch_settings WHERE id;
    IF v_straight_m > v_radius * 1000 THEN
        RAISE EXCEPTION 'Endereço fora da área de entrega' USING ERRCODE = '22023';
    END IF;
    -- a rota nunca é bem mais curta que a linha reta: valor assim indica dado adulterado/defeituoso
    IF p_distance_source = 'route' AND p_distance_m < v_straight_m * 0.95 - 50 THEN
        RAISE EXCEPTION 'Distância de rota inconsistente' USING ERRCODE = '22023';
    END IF;
    IF p_distance_m > 400000 THEN RAISE EXCEPTION 'Distância inválida' USING ERRCODE = '22023'; END IF;
    IF (SELECT count(*) FROM public.delivery_estimates WHERE customer_id = p_customer AND created_at > now() - interval '1 hour') >= 60 THEN
        RAISE EXCEPTION 'Muitas estimativas em pouco tempo. Tente novamente mais tarde.' USING ERRCODE = '54000';
    END IF;

    v_calc := public._compute_delivery_estimate(p_distance_m);
    v_snap := v_calc || jsonb_build_object('distance_source', p_distance_source, 'destination_check', p_destination_check,
                                           'straight_line_m', v_straight_m, 'calculated_at', now());
    -- estimativa nova para a mesma loja substitui as anteriores ainda não usadas (só a mais recente vale)
    UPDATE public.delivery_estimates SET invalidated_at = now()
     WHERE customer_id = p_customer AND store_id = p_store AND order_id IS NULL AND invalidated_at IS NULL;
    INSERT INTO public.delivery_estimates (customer_id, store_id, destination_lat, destination_lng, destination_address, estimated_freight, distance_km,
                                           calculation_version, snapshot, expires_at)
    VALUES (p_customer, p_store, p_lat, p_lng, v_addr, (v_calc->>'final_cents')::integer / 100.0, round(p_distance_m / 1000.0, 3),
            v_calc->>'calculation_version', v_snap, v_exp)
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('estimate_id', v_id, 'estimated_freight', round((v_calc->>'final_cents')::integer / 100.0, 2),
                              'distance_km', round(p_distance_m / 1000.0, 3), 'calculation_version', v_calc->>'calculation_version',
                              'expires_at', v_exp);
END;
$function$;

-- @@ 50|function record_delivery_round_notified(uuid,integer)
CREATE OR REPLACE FUNCTION public.record_delivery_round_notified(p_dispatch uuid, p_count integer)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    UPDATE public.order_delivery_rounds r
       SET notified_count = COALESCE(r.notified_count, 0) + GREATEST(COALESCE(p_count, 0), 0)
      FROM public.order_delivery_dispatches d
     WHERE d.id = p_dispatch AND r.dispatch_id = d.id AND r.round = d.round
$function$;

-- @@ 50|function record_profile_visit(uuid,text,uuid,text,text,text,text)
CREATE OR REPLACE FUNCTION public.record_profile_visit(p_profile_id uuid, p_session_id text, p_viewer_id uuid DEFAULT NULL::uuid, p_anonymous_id text DEFAULT NULL::text, p_device_type text DEFAULT 'desktop'::text, p_referrer text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  recent_visit_exists BOOLEAN;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM profile_visits
    WHERE profile_id = p_profile_id
      AND session_id = p_session_id
      AND created_at > (NOW() - INTERVAL '60 seconds')
  ) INTO recent_visit_exists;

  IF recent_visit_exists THEN
    RETURN FALSE;
  END IF;

  INSERT INTO profile_visits (
    profile_id, viewer_id, anonymous_id, session_id,
    device_type, referrer, user_agent
  ) VALUES (
    p_profile_id, p_viewer_id, p_anonymous_id, p_session_id,
    p_device_type, p_referrer, p_user_agent
  );

  UPDATE profiles
  SET view_count = COALESCE(view_count, 0) + 1
  WHERE id = p_profile_id;

  RETURN TRUE;
END;
$function$;

-- @@ 50|function record_referral_commission(uuid,text,bigint,text,uuid,uuid)
CREATE OR REPLACE FUNCTION public.record_referral_commission(p_paying_user uuid, p_plan_type text, p_base_cents bigint, p_payment_id text, p_subscription_id uuid DEFAULT NULL::uuid, p_plan_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_upline uuid;
    v_eff jsonb;
    v_rate integer;
    v_amount bigint;
    v_commission_id uuid;
    v_wallet_id uuid;
    v_level_name text;
BEGIN
    IF p_base_cents IS NULL OR p_base_cents <= 0 THEN
        RETURN jsonb_build_object('credited', false, 'reason', 'valor inválido');
    END IF;

    SELECT upline_id INTO v_upline FROM public.profiles WHERE id = p_paying_user;
    IF v_upline IS NULL THEN
        RETURN jsonb_build_object('credited', false, 'reason', 'sem indicador');
    END IF;

    v_eff := public.get_effective_commission(v_upline, p_plan_type);
    v_rate := (v_eff ->> 'commission_rate_bp')::integer;
    v_amount := public.commission_cents(p_base_cents, v_rate);
    v_level_name := v_eff ->> 'level';

    INSERT INTO public.commissions (
        user_id, source_user_id, transaction_id, subscription_id, plan_id, plan_type,
        base_amount_cents, commission_rate_bp, commission_amount_cents, level_id, level_name_snapshot,
        is_custom_commission, commission_source, status
    ) VALUES (
        v_upline, p_paying_user, p_payment_id, p_subscription_id, p_plan_id, p_plan_type,
        p_base_cents, v_rate, v_amount, (v_eff ->> 'level_id')::uuid, v_level_name,
        (v_eff ->> 'is_custom')::boolean, v_eff ->> 'commission_source', 'credited'
    ) ON CONFLICT (transaction_id, user_id, plan_type) DO NOTHING
    RETURNING id INTO v_commission_id;

    IF v_commission_id IS NULL THEN
        RETURN jsonb_build_object('credited', false, 'reason', 'já registrada');   -- reentrega do mesmo evento
    END IF;

    IF v_amount > 0 THEN
        INSERT INTO public.wallet_transactions (user_id, type, amount, source_subscription_id, source_payment_id, description)
        VALUES (
            v_upline, 'commission_credit', v_amount / 100.0, p_subscription_id, p_payment_id,
            format('Comissão de indicação — %s%% (%s)', trim(trailing '.' FROM trim(trailing '0' FROM round(v_rate / 100.0, 2)::text)), v_level_name)
        ) RETURNING id INTO v_wallet_id;
        UPDATE public.commissions SET wallet_transaction_id = v_wallet_id WHERE id = v_commission_id;
    END IF;

    RETURN jsonb_build_object('credited', v_amount > 0, 'commission_id', v_commission_id, 'upline_id', v_upline,
                              'rate_bp', v_rate, 'amount_cents', v_amount, 'level', v_level_name,
                              'source', v_eff ->> 'commission_source');
END $function$;

-- @@ 50|function record_store_visit(uuid,text,uuid,text,text,text,text)
CREATE OR REPLACE FUNCTION public.record_store_visit(p_store_id uuid, p_session_id text, p_viewer_id uuid DEFAULT NULL::uuid, p_anonymous_id text DEFAULT NULL::text, p_device_type text DEFAULT NULL::text, p_referrer text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    last_visit TIMESTAMP;
BEGIN
    -- Verifica cooldown de 30 minutos para este anônimo/sessão
    IF p_viewer_id IS NULL AND p_anonymous_id IS NOT NULL THEN
        SELECT created_at INTO last_visit
        FROM public.store_visits
        WHERE store_id = p_store_id
          AND anonymous_id = p_anonymous_id
        ORDER BY created_at DESC
        LIMIT 1;
    ELSIF p_viewer_id IS NOT NULL THEN
        SELECT created_at INTO last_visit
        FROM public.store_visits
        WHERE store_id = p_store_id
          AND viewer_id = p_viewer_id
        ORDER BY created_at DESC
        LIMIT 1;
    ELSE
        -- Se não tiver identificador, permite (mas evite)
        last_visit := NULL;
    END IF;

    IF last_visit IS NOT NULL AND (NOW() - last_visit) < INTERVAL '30 minutes' THEN
        RETURN FALSE; -- não registra nova visita
    END IF;

    -- Insere a visita
    INSERT INTO public.store_visits (
        store_id,
        viewer_id,
        anonymous_id,
        session_id,
        device_type,
        referrer,
        user_agent,
        created_at
    ) VALUES (
        p_store_id,
        p_viewer_id,
        p_anonymous_id,
        p_session_id,
        p_device_type,
        p_referrer,
        p_user_agent,
        NOW()
    );

    -- Incrementa view_count da loja
    UPDATE public.stores
    SET view_count = COALESCE(view_count, 0) + 1
    WHERE id = p_store_id;

    RETURN TRUE;
END;
$function$;

-- @@ 50|function redeem_campaign_code(uuid)
CREATE OR REPLACE FUNCTION public.redeem_campaign_code(p_campaign_id uuid)
 RETURNS store_campaign_redemptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_campaign public.store_campaigns;
    v_is_member boolean;
    v_existing public.store_campaign_redemptions;
    v_new_code text;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
    END IF;

    SELECT * INTO v_campaign FROM public.store_campaigns WHERE id = p_campaign_id;
    IF NOT FOUND OR NOT v_campaign.active OR (v_campaign.ends_at IS NOT NULL AND v_campaign.ends_at <= now()) THEN
        RAISE EXCEPTION 'Campanha não disponível';
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM public.store_vip_members m
        WHERE m.store_id = v_campaign.store_id AND m.profile_id = auth.uid() AND m.status = 'active'
    ) INTO v_is_member;
    IF NOT v_is_member THEN
        RAISE EXCEPTION 'Você não é membro desse clube VIP';
    END IF;

    SELECT * INTO v_existing
    FROM public.store_campaign_redemptions
    WHERE campaign_id = p_campaign_id AND member_id = auth.uid();
    IF FOUND THEN
        RETURN v_existing;
    END IF;

    v_new_code := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

    INSERT INTO public.store_campaign_redemptions (campaign_id, member_id, code, status)
    VALUES (p_campaign_id, auth.uid(), v_new_code, 'available')
    RETURNING * INTO v_existing;

    RETURN v_existing;
END;
$function$;

-- @@ 50|function redeem_plan_code(text)
CREATE OR REPLACE FUNCTION public.redeem_plan_code(p_code text)
 RETURNS subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_code public.plan_codes;
    v_period_end timestamptz;
    v_existing_id uuid;
    v_sub public.subscriptions;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Não autenticado';
    END IF;

    SELECT * INTO v_code
    FROM public.plan_codes
    WHERE code = p_code AND active = true
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Código inválido ou já usado';
    END IF;

    IF v_code.use_count >= v_code.max_uses THEN
        RAISE EXCEPTION 'Código esgotado';
    END IF;

    v_period_end := CASE
        WHEN v_code.grant_type = 'days' THEN now() + make_interval(days => v_code.days)
        ELSE now() + interval '100 years'
    END;

    SELECT id INTO v_existing_id
    FROM public.subscriptions
    WHERE user_id = auth.uid() AND plan_id = v_code.plan_id AND status IN ('pending', 'active')
    FOR UPDATE;

    IF v_existing_id IS NOT NULL THEN
        UPDATE public.subscriptions
        SET status = 'active', source = 'code', current_period_end = v_period_end, updated_at = now()
        WHERE id = v_existing_id
        RETURNING * INTO v_sub;
    ELSE
        INSERT INTO public.subscriptions (user_id, plan_id, status, source, current_period_end)
        VALUES (auth.uid(), v_code.plan_id, 'active', 'code', v_period_end)
        RETURNING * INTO v_sub;
    END IF;

    UPDATE public.plan_codes
        SET use_count = use_count + 1,
            active = CASE WHEN use_count + 1 >= max_uses THEN false ELSE active END
        WHERE id = v_code.id;

    RETURN v_sub;
END;
$function$;

-- @@ 50|function redeem_store_access_code(text)
CREATE OR REPLACE FUNCTION public.redeem_store_access_code(p_code text)
 RETURNS store_access_grants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_code public.store_access_codes;
    v_grant public.store_access_grants;
begin
    if auth.uid() is null then
        raise exception 'Não autenticado';
    end if;

    select * into v_code
    from public.store_access_codes
    where code = p_code and active = true
    for update;

    if not found then
        raise exception 'Código inválido ou já usado';
    end if;

    if v_code.use_count >= v_code.max_uses then
        raise exception 'Código esgotado';
    end if;

    insert into public.store_access_grants (
        profile_id, source, source_code_id, grant_type, days,
        status, reviewed_at
    ) values (
        auth.uid(), 'code', v_code.id, v_code.grant_type, v_code.days,
        'approved', now()
    ) returning * into v_grant;

    update public.store_access_codes
        set use_count = use_count + 1,
            active = case when use_count + 1 >= max_uses then false else active end
        where id = v_code.id;

    return v_grant;
end;
$function$;

-- @@ 50|function reject_application_on_closed_ride()
CREATE OR REPLACE FUNCTION public.reject_application_on_closed_ride()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_status text;
    v_driver uuid;
BEGIN
    SELECT status, driver_id INTO v_status, v_driver FROM public.ride_requests WHERE id = NEW.ride_request_id;
    IF v_status IS NOT NULL AND v_status <> 'pending' THEN
        UPDATE public.ride_applications SET status = 'rejected'
         WHERE id = NEW.id AND status = 'pending' AND applicant_id IS DISTINCT FROM v_driver;
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function reject_losing_ride_applications()
CREATE OR REPLACE FUNCTION public.reject_losing_ride_applications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    UPDATE public.ride_applications
       SET status = 'rejected'
     WHERE ride_request_id = NEW.id
       AND status = 'pending'
       AND applicant_id IS DISTINCT FROM NEW.driver_id;
    RETURN NEW;
END;
$function$;

-- @@ 50|function remove_group_member(uuid,uuid)
CREATE OR REPLACE FUNCTION public.remove_group_member(p_conv uuid, p_profile uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid();
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.conversation_members WHERE conversation_id = p_conv AND profile_id = v_user AND status = 'active' AND role = 'admin') THEN
        RAISE EXCEPTION 'Só quem administra o grupo pode remover pessoas';
    END IF;
    IF p_profile = v_user THEN RAISE EXCEPTION 'Para sair, use "Sair do grupo"'; END IF;
    UPDATE public.conversation_members SET status = 'removed', role = 'member'
    WHERE conversation_id = p_conv AND profile_id = p_profile AND status IN ('active', 'invited');
END; $function$;

-- @@ 50|function require_stop_reached_before_completion()
CREATE OR REPLACE FUNCTION public.require_stop_reached_before_completion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed' THEN
        IF NEW.stop1_lat IS NOT NULL AND NEW.stop1_lng IS NOT NULL AND NEW.stop1_reached_at IS NULL THEN
            RAISE EXCEPTION 'Confirme a chegada na 1ª parada antes de concluir a corrida.';
        END IF;
        IF NEW.stop2_lat IS NOT NULL AND NEW.stop2_lng IS NOT NULL AND NEW.stop2_reached_at IS NULL THEN
            RAISE EXCEPTION 'Confirme a chegada na 2ª parada antes de concluir a corrida.';
        END IF;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function resolve_grant_authority(uuid,uuid)
CREATE OR REPLACE FUNCTION public.resolve_grant_authority(p_actor uuid, p_plan_id uuid)
 RETURNS TABLE(permission text, scope text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT e.permission, e.scope
    FROM public.get_effective_permissions(p_actor) e
    JOIN public.plans pl ON pl.id = p_plan_id AND pl.grantable
    WHERE e.permission = 'grant_any_plan' OR e.permission = pl.grant_permission
    ORDER BY public._scope_rank(e.scope) DESC, (e.permission = pl.grant_permission) DESC
    LIMIT 1;
$function$;

-- @@ 50|function respond_delivery_counter(uuid,boolean)
CREATE OR REPLACE FUNCTION public.respond_delivery_counter(p_counter uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    c public.order_delivery_counters;
    d public.order_delivery_dispatches;
    cfg public.delivery_dispatch_settings;
    v_ride_status text;
    v_old_fee numeric;
    v_offered numeric;
BEGIN
    SELECT * INTO c FROM public.order_delivery_counters WHERE id = p_counter FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Proposta não encontrada'; END IF;
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = c.dispatch_id FOR UPDATE;
    IF d.customer_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
    IF c.status <> 'pending_customer' THEN RAISE EXCEPTION 'Essa proposta não está mais disponível'; END IF;

    SELECT status INTO v_ride_status FROM public.ride_requests WHERE id = d.ride_request_id;
    IF d.status <> 'searching' OR v_ride_status IS DISTINCT FROM 'pending' THEN
        UPDATE public.order_delivery_counters SET status = 'expired', decided_at = now() WHERE id = c.id;
        RAISE EXCEPTION 'A entrega já não está em busca';
    END IF;

    IF NOT p_accept THEN
        UPDATE public.order_delivery_counters SET status = 'declined', decided_at = now() WHERE id = c.id;
        RETURN jsonb_build_object('accepted', false);
    END IF;

    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    IF c.amount > cfg.max_freight THEN RAISE EXCEPTION 'Valor acima do máximo permitido'; END IF;

    SELECT delivery_fee INTO v_old_fee FROM public.orders WHERE id = d.order_id;
    UPDATE public.orders
       SET delivery_fee = c.amount, total_amount = total_amount - COALESCE(v_old_fee, 0) + c.amount
     WHERE id = d.order_id;

    UPDATE public.order_delivery_counters SET status = 'authorized', decided_at = now() WHERE id = c.id;
    UPDATE public.order_delivery_counters SET status = 'expired', decided_at = now() WHERE dispatch_id = d.id AND id <> c.id AND status = 'pending_customer';
    UPDATE public.order_delivery_rounds SET status = 'expired' WHERE dispatch_id = d.id AND status = 'pending_customer';

    INSERT INTO public.order_delivery_rounds (dispatch_id, round, kind, original_freight, extra, final_freight, platform_fee, driver_offer, radius_km, status, authorized_at, authorized_by, proposed_by)
    VALUES (d.id, d.round + 1, 'driver_counter', d.original_freight, c.amount - d.original_freight, c.amount, c.platform_fee, c.driver_offer, d.radius_km, 'authorized', now(), auth.uid(), c.driver_id);
    UPDATE public.order_delivery_dispatches
       SET round = d.round + 1, authorized_extra = c.amount - d.original_freight, final_freight = c.amount, round_started_at = now(), updated_at = now()
     WHERE id = d.id;
    UPDATE public.ride_requests SET offered_price = c.driver_offer WHERE id = d.ride_request_id;

    -- o motorista que propôs fica com a entrega (a candidatura no valor da corrida o aceita sozinha)
    PERFORM set_config('app.skip_delivery_radius', '1', true);
    INSERT INTO public.ride_applications (ride_request_id, applicant_id, status, proposed_price)
    VALUES (d.ride_request_id, c.driver_id, 'pending', c.driver_offer)
    ON CONFLICT DO NOTHING;
    RETURN jsonb_build_object('accepted', true, 'final_freight', c.amount, 'driver_offer', c.driver_offer);
END;
$function$;

-- @@ 50|function respond_delivery_increase(uuid,boolean)
CREATE OR REPLACE FUNCTION public.respond_delivery_increase(p_round uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    r public.order_delivery_rounds;
    d public.order_delivery_dispatches;
    cfg public.delivery_dispatch_settings;
    v_ride_status text;
    v_old_fee numeric;
BEGIN
    SELECT * INTO r FROM public.order_delivery_rounds WHERE id = p_round FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Proposta não encontrada'; END IF;
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = r.dispatch_id FOR UPDATE;
    IF d.customer_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão'; END IF;
    IF r.status <> 'pending_customer' THEN RAISE EXCEPTION 'Essa proposta não está mais disponível'; END IF;

    SELECT status INTO v_ride_status FROM public.ride_requests WHERE id = d.ride_request_id;
    IF d.status <> 'searching' OR v_ride_status IS DISTINCT FROM 'pending' THEN
        UPDATE public.order_delivery_rounds SET status = 'expired' WHERE id = r.id;
        RAISE EXCEPTION 'A entrega já não está em busca';
    END IF;

    IF NOT p_accept THEN
        UPDATE public.order_delivery_rounds SET status = 'declined' WHERE id = r.id;
        RETURN jsonb_build_object('accepted', false, 'final_freight', d.final_freight);
    END IF;

    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;
    IF r.final_freight > cfg.max_freight THEN RAISE EXCEPTION 'Valor acima do máximo permitido'; END IF;

    SELECT delivery_fee INTO v_old_fee FROM public.orders WHERE id = d.order_id;
    UPDATE public.orders
       SET delivery_fee = r.final_freight,
           total_amount = total_amount - COALESCE(v_old_fee, 0) + r.final_freight
     WHERE id = d.order_id;

    UPDATE public.order_delivery_rounds SET status = 'authorized', authorized_at = now(), authorized_by = auth.uid() WHERE id = r.id;
    UPDATE public.order_delivery_dispatches
       SET authorized_extra = r.extra, final_freight = r.final_freight, round_started_at = now(), updated_at = now()
     WHERE id = d.id;
    UPDATE public.ride_requests SET offered_price = r.driver_offer WHERE id = d.ride_request_id;

    INSERT INTO public.order_delivery_events (dispatch_id, kind, new_radius, round_id) VALUES (d.id, 'price_raised', d.radius_km, r.id);
    PERFORM public._ping_delivery_events();

    RETURN jsonb_build_object('accepted', true, 'final_freight', r.final_freight, 'driver_offer', r.driver_offer);
END;
$function$;

-- @@ 50|function respond_delivery_reajust(uuid,boolean)
CREATE OR REPLACE FUNCTION public.respond_delivery_reajust(p_authorization uuid, p_accept boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    a public.delivery_reajust_authorizations;
    d public.order_delivery_dispatches;
    v_dispatch uuid;
BEGIN
    SELECT dispatch_id INTO v_dispatch FROM public.delivery_reajust_authorizations WHERE id = p_authorization;
    -- trava primeiro a entrega (mesma ordem do cron) para não travar em círculo
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = v_dispatch FOR UPDATE;
    IF NOT FOUND OR d.customer_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT * INTO a FROM public.delivery_reajust_authorizations WHERE id = p_authorization FOR UPDATE;
    IF a.status <> 'pending' THEN RAISE EXCEPTION 'Essa solicitação não está mais disponível' USING HINT = 'reajust_closed'; END IF;
    IF d.status <> 'searching' THEN
        UPDATE public.delivery_reajust_authorizations SET status = 'cancelled', decided_at = now() WHERE id = a.id;
        RAISE EXCEPTION 'A entrega já não está em busca' USING HINT = 'not_searching';
    END IF;
    IF now() >= a.expires_at THEN
        UPDATE public.delivery_reajust_authorizations SET status = 'expired', decided_at = now() WHERE id = a.id;
        PERFORM public._v2_end_search(d.id, 'authorization_expired');
        RETURN jsonb_build_object('accepted', false, 'expired', true);
    END IF;

    IF NOT p_accept THEN
        UPDATE public.delivery_reajust_authorizations SET status = 'declined', decided_at = now(), decided_by = auth.uid() WHERE id = a.id;
        INSERT INTO public.order_delivery_events (dispatch_id, kind, actor_id, actor_role, data, processed_at)
        VALUES (d.id, 'reajust_decided', auth.uid(), 'customer', jsonb_build_object('authorization_id', a.id, 'accepted', false, 'previous_limit', a.previous_limit, 'requested_limit', a.requested_limit), now());
        PERFORM public._v2_end_search(d.id, 'customer_declined');
        RETURN jsonb_build_object('accepted', false);
    END IF;

    PERFORM set_config('app.delivery_actor', 'customer', true);
    UPDATE public.delivery_reajust_authorizations SET status = 'authorized', decided_at = now(), decided_by = auth.uid() WHERE id = a.id;
    UPDATE public.order_delivery_dispatches
       SET price_limit = a.requested_limit, phase = 'PROCURANDO_ENTREGADOR', offer_expires_at = now(), updated_at = now()
     WHERE id = d.id;
    INSERT INTO public.order_delivery_events (dispatch_id, kind, actor_id, actor_role, data, processed_at)
    VALUES (d.id, 'reajust_decided', auth.uid(), 'customer', jsonb_build_object('authorization_id', a.id, 'accepted', true, 'previous_limit', a.previous_limit, 'requested_limit', a.requested_limit), now());
    PERFORM public._advance_delivery_search_v2(d.id);      -- retoma já, sem esperar o próximo minuto do cron
    PERFORM public._ping_delivery_events();
    RETURN jsonb_build_object('accepted', true, 'price_limit', a.requested_limit);
END;
$function$;

-- @@ 50|function respond_group_invite(uuid,boolean)
CREATE OR REPLACE FUNCTION public.respond_group_invite(p_conv uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid();
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF p_accept THEN
        UPDATE public.conversation_members
        SET status = 'active', joined_at = now(), last_read_at = now()
        WHERE conversation_id = p_conv AND profile_id = v_user AND status = 'invited';
    ELSE
        UPDATE public.conversation_members SET status = 'declined'
        WHERE conversation_id = p_conv AND profile_id = v_user AND status = 'invited';
    END IF;
END; $function$;

-- @@ 50|function resync_iuser_delivery_stores()
CREATE OR REPLACE FUNCTION public.resync_iuser_delivery_stores()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.vehicle_kind = 'moto' THEN
        UPDATE public.stores SET iuser_delivery_enabled = true WHERE iuser_delivery_enabled;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function review_customer(uuid,integer,text)
CREATE OR REPLACE FUNCTION public.review_customer(p_order uuid, p_rating integer, p_comment text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); o public.orders; s public.stores; v_comment text := NULLIF(btrim(COALESCE(p_comment, '')), '');
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN RAISE EXCEPTION 'Escolha de 1 a 5 estrelas'; END IF;
    SELECT * INTO o FROM public.orders WHERE id = p_order;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;
    SELECT * INTO s FROM public.stores WHERE id = o.store_id;
    IF s.owner_id <> v_user THEN RAISE EXCEPTION 'Só a loja do pedido pode avaliar o cliente'; END IF;
    IF NOT s.mutual_reviews THEN RAISE EXCEPTION 'A troca de avaliações está desligada nessa loja'; END IF;
    IF o.status <> 'paid' THEN RAISE EXCEPTION 'O pedido ainda não foi concluído'; END IF;
    IF o.buyer_id IS NULL THEN RAISE EXCEPTION 'Esse pedido não tem um cliente com conta'; END IF;

    INSERT INTO public.customer_reviews (order_id, store_id, reviewer_id, reviewee_id, rating, comment)
    VALUES (o.id, s.id, v_user, o.buyer_id, p_rating, left(v_comment, 500))
    ON CONFLICT (order_id) DO NOTHING;
    IF NOT FOUND THEN RAISE EXCEPTION 'Você já avaliou esse cliente'; END IF;

    BEGIN
        PERFORM public._notify(o.buyer_id, 'customer_review', v_user, o.id,
            jsonb_build_object('rating', p_rating, 'snippet', left(COALESCE(v_comment, ''), 120), 'title', s.name), 'custrev:' || o.id);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN true;
END; $function$;

-- @@ 50|function ride_applications_v2_gate()
CREATE OR REPLACE FUNCTION public.ride_applications_v2_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d public.order_delivery_dispatches; v_status text; v_price numeric;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE ride_request_id = NEW.ride_request_id AND flow_version = 2 FOR UPDATE;
    IF NOT FOUND THEN RETURN NEW; END IF;                       -- entrega V1: nada muda
    IF d.status <> 'searching' THEN RETURN NEW; END IF;         -- já decidida: os gatilhos existentes rejeitam a candidatura
    SELECT status, offered_price INTO v_status, v_price FROM public.ride_requests WHERE id = NEW.ride_request_id;
    IF v_status IS DISTINCT FROM 'pending' THEN RETURN NEW; END IF;
    -- sem chave Pix cadastrada o motorista não aceita: a loja nunca recebe do cliente para depois não conseguir pagar o frete
    IF NOT EXISTS (SELECT 1 FROM public.driver_payout_keys WHERE driver_id = NEW.applicant_id) THEN
        RAISE EXCEPTION 'Cadastre sua chave Pix para aceitar entregas do novo fluxo' USING ERRCODE = '42501', HINT = 'payout_pix_required';
    END IF;
    IF d.offer_expires_at IS NULL OR now() >= d.offer_expires_at THEN
        RAISE EXCEPTION 'Esta oferta expirou' USING ERRCODE = '42501', HINT = 'offer_expired';
    END IF;
    IF NEW.proposed_price IS DISTINCT FROM d.final_freight OR v_price IS DISTINCT FROM d.final_freight THEN
        RAISE EXCEPTION 'O valor da oferta mudou. Veja o valor atual.' USING ERRCODE = '42501', HINT = 'offer_changed';
    END IF;
    IF d.price_limit IS NULL OR d.final_freight > d.price_limit THEN
        RAISE EXCEPTION 'Valor acima do autorizado pelo cliente' USING ERRCODE = '42501', HINT = 'above_authorized';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function ride_requests_v2_after_cancel()
CREATE OR REPLACE FUNCTION public.ride_requests_v2_after_cancel()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record;
BEGIN
    IF NEW.order_id IS NOT NULL AND OLD.status = 'accepted' AND NEW.status = 'cancelled' THEN
        SELECT id, phase, status INTO d FROM public.order_delivery_dispatches WHERE ride_request_id = NEW.id AND flow_version = 2;
        IF FOUND AND d.status = 'accepted' AND d.phase IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE') THEN
            IF NEW.cancelled_by = 'driver' THEN
                PERFORM public._v2_release_reservation(d.id, 'driver_cancelled', 'reopen', false);
            ELSE
                PERFORM public._v2_release_reservation(d.id, 'store_cancelled', 'cancel', true);
            END IF;
        END IF;
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function ride_requests_v2_barrier()
CREATE OR REPLACE FUNCTION public.ride_requests_v2_barrier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d record; v_reserved boolean; v_allowed boolean;
BEGIN
    IF NEW.order_id IS NULL THEN RETURN NEW; END IF;
    SELECT id, phase, status INTO d FROM public.order_delivery_dispatches WHERE ride_request_id = NEW.id AND flow_version = 2;
    IF NOT FOUND THEN RETURN NEW; END IF;                        -- V1 e corridas comuns: nada muda
    v_reserved := d.status = 'accepted' AND d.phase IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE');

    IF v_reserved AND OLD.status = 'accepted' AND NEW.status = 'cancelled' THEN
        IF NEW.cancelled_by = 'driver' THEN
            SELECT cancel_driver_after_reservation INTO v_allowed FROM public.delivery_dispatch_settings WHERE id;
            IF NOT v_allowed THEN
                RAISE EXCEPTION 'O entregador não pode cancelar depois da reserva' USING ERRCODE = '42501', HINT = 'cancel_not_allowed';
            END IF;
        END IF;
        RETURN NEW;                                              -- a liberação é feita pelo gatilho DEPOIS (a política de segurança confere a linha final)
    END IF;

    -- dinheiro já declarado (ou entrega liberada): cancelar a corrida não é cancelamento simples → bloqueado; abra uma ocorrência
    IF OLD.status = 'accepted' AND NEW.status = 'cancelled' AND public._v2_phase_money(d.phase) THEN
        RAISE EXCEPTION 'Há pagamento informado nesta entrega: o cancelamento simples não é possível. Abra uma ocorrência.' USING ERRCODE = '42501', HINT = 'cancel_blocked_after_payment';
    END IF;

    IF NOT public._v2_phase_released(d.phase)
       AND ((NEW.driver_en_route, NEW.driver_departed_at, NEW.driver_arrived_at, NEW.ride_started_at, NEW.stop1_reached_at, NEW.stop2_reached_at,
             NEW.extra_task_minutes, NEW.extra_task_fee, NEW.extra_task_description)
            IS DISTINCT FROM
            (OLD.driver_en_route, OLD.driver_departed_at, OLD.driver_arrived_at, OLD.ride_started_at, OLD.stop1_reached_at, OLD.stop2_reached_at,
             OLD.extra_task_minutes, OLD.extra_task_fee, OLD.extra_task_description)
            OR (NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed')) THEN
        RAISE EXCEPTION 'Aguarde a liberação da entrega antes de iniciar a retirada' USING ERRCODE = '42501', HINT = 'delivery_not_released';
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function rotate_ride_share_token(uuid)
CREATE OR REPLACE FUNCTION public.rotate_ride_share_token(p_ride uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_new text := substr(replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''), 1, 40);
    v_updated integer;
BEGIN
    UPDATE public.ride_requests SET share_token = v_new
     WHERE id = p_ride AND (requester_id = auth.uid() OR driver_id = auth.uid());
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated = 0 THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    RETURN v_new;
END;
$function$;

-- @@ 50|function search_products_unaccented(text)
CREATE OR REPLACE FUNCTION public.search_products_unaccented(search_term text)
 RETURNS SETOF products
 LANGUAGE sql
 STABLE
AS $function$
    select *
    from products
    where listing_type = 'sale'
        and public.unaccent(coalesce(name, '')) ilike public.unaccent('%' || search_term || '%')
    limit 50;
$function$;

-- @@ 50|function search_profiles_unaccented(text)
CREATE OR REPLACE FUNCTION public.search_profiles_unaccented(search_term text)
 RETURNS TABLE(id uuid, name text, "profileSlug" text, avatar_url text, description text, bio text, ratings_avg numeric, ratings_count integer, view_count integer, is_seller boolean, category text, created_at timestamp with time zone, public_address text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    SELECT p.id, p.name, p."profileSlug", p.avatar_url, p.description, p.bio,
           p.ratings_avg, p.ratings_count, p.view_count, p.is_seller, p.category, p.created_at, p.public_address
    FROM public.profiles p
    WHERE p.is_active = true AND (
        public.unaccent(coalesce(p.name, '')) ILIKE public.unaccent('%' || search_term || '%')
        OR public.unaccent(coalesce(p."profileSlug", '')) ILIKE public.unaccent('%' || search_term || '%')
        OR public.unaccent(coalesce(p.description, '')) ILIKE public.unaccent('%' || search_term || '%')
        OR public.unaccent(coalesce(p.bio, '')) ILIKE public.unaccent('%' || search_term || '%')
        OR public.unaccent(coalesce(p.public_address, '')) ILIKE public.unaccent('%' || search_term || '%')
    ) LIMIT 20
$function$;

-- @@ 50|function search_stores_unaccented(text)
CREATE OR REPLACE FUNCTION public.search_stores_unaccented(search_term text)
 RETURNS TABLE(id uuid, name text, "storeSlug" text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    SELECT s.id, s.name, s."storeSlug"
    FROM public.stores s
    WHERE public.unaccent(coalesce(s.name, '')) ILIKE public.unaccent('%' || search_term || '%')
       OR public.unaccent(coalesce(s.description, '')) ILIKE public.unaccent('%' || search_term || '%')
       OR public.unaccent(coalesce(s."storeSlug", '')) ILIKE public.unaccent('%' || search_term || '%')
       OR public.unaccent(coalesce(s.category, '')) ILIKE public.unaccent('%' || search_term || '%')
    LIMIT 30
$function$;

-- @@ 50|function select_ride_driver(uuid,uuid)
CREATE OR REPLACE FUNCTION public.select_ride_driver(p_ride uuid, p_application uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    r public.ride_requests;
    a public.ride_applications;
BEGIN
    SELECT * INTO r FROM public.ride_requests WHERE id = p_ride FOR UPDATE;
    IF NOT FOUND OR r.requester_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF r.status <> 'pending' THEN RAISE EXCEPTION 'Este pedido já foi decidido.'; END IF;
    SELECT * INTO a FROM public.ride_applications WHERE id = p_application AND ride_request_id = p_ride;
    IF NOT FOUND OR a.status <> 'pending' THEN RAISE EXCEPTION 'Candidatura inválida'; END IF;
    IF a.applicant_id = r.requester_id THEN RAISE EXCEPTION 'Candidatura inválida'; END IF;

    UPDATE public.ride_requests SET status = 'accepted', driver_id = a.applicant_id WHERE id = p_ride AND status = 'pending';
    UPDATE public.ride_applications SET status = 'accepted' WHERE id = p_application;
    UPDATE public.ride_applications SET status = 'rejected' WHERE ride_request_id = p_ride AND status = 'pending' AND id <> p_application;
    RETURN jsonb_build_object('ok', true, 'driver_id', a.applicant_id);
END;
$function$;

-- @@ 50|function set_community_image(uuid,text)
CREATE OR REPLACE FUNCTION public.set_community_image(p_community uuid, p_image_url text)
