-- @@ 50|function set_last_seen_visibility(text)
CREATE OR REPLACE FUNCTION public.set_last_seen_visibility(p_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF p_value NOT IN ('all', 'following', 'none') THEN RAISE EXCEPTION 'Opção inválida'; END IF;
    INSERT INTO public.profile_presence (profile_id, visibility) VALUES (auth.uid(), p_value)
    ON CONFLICT (profile_id) DO UPDATE SET visibility = EXCLUDED.visibility;
END; $function$;

-- @@ 50|function set_live_location_enabled(boolean)
CREATE OR REPLACE FUNCTION public.set_live_location_enabled(p_on boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    UPDATE public.profiles SET live_location = COALESCE(p_on, false) WHERE id = auth.uid();
    IF NOT COALESCE(p_on, false) THEN DELETE FROM public.profile_live_location WHERE profile_id = auth.uid(); END IF;
END; $function$;

-- @@ 50|function set_location()
CREATE OR REPLACE FUNCTION public.set_location()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.lat is not null and new.lng is not null then
    new.location = ST_SetSRID(ST_MakePoint(new.lng, new.lat), 4326);
  end if;
  return new;
end;
$function$;

-- @@ 50|function set_my_payout_pix(text,text,boolean)
CREATE OR REPLACE FUNCTION public.set_my_payout_pix(p_type text, p_key text, p_consent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid uuid := auth.uid(); v_key text;
BEGIN
    IF v_uid IS NULL THEN RAISE EXCEPTION 'Entre na sua conta' USING ERRCODE = '42501'; END IF;
    IF NOT COALESCE(p_consent, false) THEN
        RAISE EXCEPTION 'Autorize mostrar a chave à loja que for te pagar' USING ERRCODE = '22023', HINT = 'consent_required';
    END IF;
    v_key := public._pix_normalize(p_type, p_key);
    IF v_key IS NULL OR NOT public._pix_key_valid(p_type, v_key) THEN
        RAISE EXCEPTION 'Chave Pix inválida para o tipo escolhido' USING ERRCODE = '22023', HINT = 'invalid_pix';
    END IF;
    -- a chave não troca no meio de um pagamento em andamento
    IF EXISTS (SELECT 1 FROM public.order_delivery_dispatches d JOIN public.ride_requests r ON r.id = d.ride_request_id
                WHERE r.driver_id = v_uid AND d.flow_version = 2 AND d.status = 'accepted'
                  AND d.phase IN ('LOJA_INFORMOU_RECEBIMENTO', 'AGUARDANDO_PAGAMENTO_ENTREGADOR', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', 'PAGAMENTO_EM_VERIFICACAO')) THEN
        RAISE EXCEPTION 'Você tem um pagamento de entrega em andamento: não dá para trocar a chave agora' USING ERRCODE = '42501', HINT = 'payment_in_progress';
    END IF;
    INSERT INTO public.driver_payout_keys (driver_id, pix_key_type, pix_key, consent_at, updated_at)
    VALUES (v_uid, p_type, v_key, now(), now())
    ON CONFLICT (driver_id) DO UPDATE SET pix_key_type = EXCLUDED.pix_key_type, pix_key = EXCLUDED.pix_key, consent_at = now(), updated_at = now();
    RETURN jsonb_build_object('registered', true, 'type', p_type, 'masked', public._pix_mask(p_type, v_key));
END;
$function$;

-- @@ 50|function set_my_ui_version(text)
CREATE OR REPLACE FUNCTION public.set_my_ui_version(p_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'not authenticated';
    END IF;
    IF p_version IS NOT NULL AND p_version NOT IN ('v2', 'v3') THEN
        RAISE EXCEPTION 'invalid version';
    END IF;
    UPDATE public.profiles SET preferred_version = p_version WHERE id = auth.uid();
END;
$function$;

-- @@ 50|function set_presence_mode(text)
CREATE OR REPLACE FUNCTION public.set_presence_mode(p_mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF p_mode NOT IN ('auto', 'online', 'offline') THEN RAISE EXCEPTION 'Opção inválida'; END IF;
    INSERT INTO public.profile_presence (profile_id, mode, online, last_seen_at) VALUES (auth.uid(), p_mode, p_mode = 'online', CASE WHEN p_mode = 'offline' THEN NULL ELSE now() END)
    ON CONFLICT (profile_id) DO UPDATE
        SET mode = EXCLUDED.mode,
            online = (EXCLUDED.mode = 'online') OR (EXCLUDED.mode = 'auto' AND public.profile_presence.online),
            last_seen_at = CASE WHEN EXCLUDED.mode = 'offline' THEN public.profile_presence.last_seen_at ELSE now() END;
END; $function$;

-- @@ 50|function set_ride_share_closed()
CREATE OR REPLACE FUNCTION public.set_ride_share_closed()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status IN ('completed', 'cancelled') AND OLD.status IS DISTINCT FROM NEW.status AND NEW.share_closed_at IS NULL THEN
        NEW.share_closed_at := now();
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function set_user_status_internal(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.set_user_status_internal(p_actor uuid, p_target uuid, p_status_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_status public.user_statuses;
    v_actor_level integer;
    v_target_level integer;
    v_deny_code text;
    v_deny_msg text;
BEGIN
    SELECT * INTO v_status FROM public.user_statuses WHERE slug = p_status_slug AND is_active;
    SELECT st.level INTO v_actor_level FROM public._actor_status(p_actor) st;
    SELECT st.level INTO v_target_level FROM public._actor_status(p_target) st;

    IF p_target IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_target) THEN
        v_deny_code := 'target_not_found'; v_deny_msg := 'Pessoa não encontrada';
    ELSIF v_status.id IS NULL THEN
        v_deny_code := 'status_not_found'; v_deny_msg := 'Status não encontrado';
    ELSIF NOT public.has_permission(p_actor, 'manage_leaders') THEN
        v_deny_code := 'permission_denied'; v_deny_msg := 'Você não pode gerenciar status';
    ELSIF p_actor = p_target THEN
        v_deny_code := 'self_change_denied'; v_deny_msg := 'Você não pode alterar o próprio status';
    ELSIF COALESCE(v_actor_level, 0) < 4 AND (v_status.level >= COALESCE(v_actor_level, 0) OR COALESCE(v_target_level, 0) >= COALESCE(v_actor_level, 0)) THEN
        v_deny_code := 'level_denied'; v_deny_msg := 'Você só gerencia status abaixo do seu nível';
    ELSIF NOT public.can_act_on_user(p_actor, p_target, 'manage_leaders') THEN
        v_deny_code := 'out_of_scope'; v_deny_msg := 'Essa pessoa está fora do seu escopo';
    END IF;

    IF v_deny_code IS NOT NULL THEN
        PERFORM public._log_grant_event('set_status', 'denied', v_deny_code, p_actor, p_target, NULL, NULL,
                                        'manage_leaders', NULL, NULL, NULL, NULL, NULL,
                                        jsonb_build_object('status_slug', p_status_slug));
        RETURN jsonb_build_object('ok', false, 'code', v_deny_code, 'message', v_deny_msg);
    END IF;

    UPDATE public.profiles SET status_id = v_status.id WHERE id = p_target;
    PERFORM public._log_grant_event('set_status', 'granted', NULL, p_actor, p_target, NULL, NULL,
                                    'manage_leaders', public.get_permission_scope(p_actor, 'manage_leaders'), NULL, NULL, NULL, NULL,
                                    jsonb_build_object('status_slug', p_status_slug));
    RETURN jsonb_build_object('ok', true);
END;
$function$;

-- @@ 50|function start_conversation(uuid,uuid)
CREATE OR REPLACE FUNCTION public.start_conversation(p_owner_profile uuid DEFAULT NULL::uuid, p_store uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_id uuid; v_ok boolean;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra conversar'; END IF;
    IF (p_owner_profile IS NULL) = (p_store IS NULL) THEN RAISE EXCEPTION 'Escolha um perfil ou uma loja'; END IF;

    IF p_owner_profile IS NOT NULL THEN
        IF p_owner_profile = v_user THEN RAISE EXCEPTION 'Você não pode conversar consigo mesmo'; END IF;
        -- Já existe uma sala entre as duas pessoas (quem puxou não importa)? Reaproveita.
        SELECT id INTO v_id FROM public.conversations
        WHERE (customer_id = v_user AND owner_profile_id = p_owner_profile)
           OR (customer_id = p_owner_profile AND owner_profile_id = v_user)
        LIMIT 1;
        IF v_id IS NOT NULL THEN RETURN v_id; END IF;

        SELECT chat_enabled INTO v_ok FROM public.profiles WHERE id = p_owner_profile;
        IF v_ok IS DISTINCT FROM true AND NOT public._have_accepted_service(v_user, p_owner_profile) THEN
            RAISE EXCEPTION 'Essa pessoa não está recebendo conversas';
        END IF;
        BEGIN
            INSERT INTO public.conversations (customer_id, owner_profile_id) VALUES (v_user, p_owner_profile) RETURNING id INTO v_id;
        EXCEPTION WHEN unique_violation THEN
            -- as duas pessoas abriram ao mesmo tempo: fica com a sala que ganhou a corrida
            SELECT id INTO v_id FROM public.conversations
            WHERE (customer_id = v_user AND owner_profile_id = p_owner_profile)
               OR (customer_id = p_owner_profile AND owner_profile_id = v_user)
            LIMIT 1;
        END;
    ELSE
        SELECT chat_enabled INTO v_ok FROM public.stores WHERE id = p_store AND is_active;
        IF v_ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Essa loja não está recebendo conversas'; END IF;
        IF EXISTS (SELECT 1 FROM public.stores WHERE id = p_store AND owner_id = v_user) THEN RAISE EXCEPTION 'Essa loja é sua'; END IF;
        SELECT id INTO v_id FROM public.conversations WHERE customer_id = v_user AND store_id = p_store;
        IF v_id IS NULL THEN
            INSERT INTO public.conversations (customer_id, store_id) VALUES (v_user, p_store) RETURNING id INTO v_id;
        END IF;
    END IF;
    RETURN v_id;
END; $function$;

-- @@ 50|function start_conversation_about_product(uuid)
CREATE OR REPLACE FUNCTION public.start_conversation_about_product(p_product uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user uuid := auth.uid();
    p public.products;
    v_conv uuid;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra conversar'; END IF;
    SELECT * INTO p FROM public.products WHERE id = p_product;
    IF NOT FOUND THEN RAISE EXCEPTION 'Postagem não encontrada'; END IF;

    IF p.store_id IS NOT NULL THEN
        v_conv := public.start_conversation(NULL, p.store_id);
    ELSIF p.owner_id IS NOT NULL THEN
        v_conv := public.start_conversation(p.owner_id, NULL);
    ELSE
        RAISE EXCEPTION 'Essa postagem não tem dono';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM public.direct_messages
        WHERE conversation_id = v_conv AND sender_id = v_user AND ref_product_id = p_product
          AND created_at > now() - interval '12 hours'
    ) THEN
        INSERT INTO public.direct_messages (conversation_id, sender_id, content, ref_product_id)
        VALUES (v_conv, v_user, 'Olá! Vi o seu serviço "' || left(p.name, 120) || '" no iUser e quero saber mais.', p_product);
    END IF;
    RETURN v_conv;
END; $function$;

-- @@ 50|function start_conversation_about_request(uuid)
CREATE OR REPLACE FUNCTION public.start_conversation_about_request(p_application uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user uuid := auth.uid();
    a public.service_applications;
    r public.service_requests;
    v_other uuid;
    v_conv uuid;
    v_text text;
    v_chosen boolean;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra conversar'; END IF;
    SELECT * INTO a FROM public.service_applications WHERE id = p_application;
    IF NOT FOUND THEN RAISE EXCEPTION 'Candidatura não encontrada'; END IF;
    SELECT * INTO r FROM public.service_requests WHERE id = a.service_request_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pedido não encontrado'; END IF;

    v_chosen := a.status = 'accepted';
    IF v_user = r.requester_id THEN
        v_other := a.applicant_id;
        v_text := CASE WHEN v_chosen
            THEN 'Oi! Escolhi você pra fazer o serviço que eu publiquei aqui no iUser. Vamos combinar os detalhes?'
            ELSE 'Oi! Vi que você quer fazer o serviço que eu publiquei aqui no iUser. Podemos conversar?' END;
    ELSIF v_user = a.applicant_id THEN
        v_other := r.requester_id;
        v_text := CASE WHEN v_chosen
            THEN 'Oi! Vi que você me escolheu pro serviço que publicou no iUser. Vamos combinar os detalhes?'
            ELSE 'Oi! Me candidatei ao serviço que você publicou no iUser. Posso tirar alguma dúvida com você?' END;
    ELSE RAISE EXCEPTION 'Você não participa desse pedido';
    END IF;

    v_conv := public.start_conversation(v_other, NULL);

    IF NOT EXISTS (
        SELECT 1 FROM public.direct_messages
        WHERE conversation_id = v_conv AND sender_id = v_user AND ref_request_id = r.id AND content = v_text
          AND created_at > now() - interval '12 hours'
    ) THEN
        INSERT INTO public.direct_messages (conversation_id, sender_id, content, ref_request_id)
        VALUES (v_conv, v_user, v_text, r.id);
    END IF;
    RETURN v_conv;
END; $function$;

-- @@ 50|function start_my_order_delivery(uuid)
CREATE OR REPLACE FUNCTION public.start_my_order_delivery(p_order uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.orders o JOIN public.stores s ON s.id = o.store_id
        WHERE o.id = p_order AND s.owner_id = auth.uid() AND o.status IN ('preparing', 'ready')
    ) THEN
        RAISE EXCEPTION 'Sem permissão ou pedido ainda não aceito';
    END IF;
    RETURN public._start_order_delivery_dispatch(p_order);
END;
$function$;

