-- @@ 50|function store_report_customer_payment(uuid,text)
CREATE OR REPLACE FUNCTION public.store_report_customer_payment(p_dispatch uuid, p_method text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    d public.order_delivery_dispatches;
    o public.orders;
    cfg public.delivery_dispatch_settings;
    v_owner uuid; v_driver uuid; v_method text;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT owner_id INTO v_owner FROM public.stores WHERE id = d.store_id;
    IF v_uid IS NULL OR v_owner IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'store_declared_customer_payment') THEN
        RETURN jsonb_build_object('ok', true, 'duplicate', true, 'phase', d.phase);      -- clique repetido: nada novo
    END IF;
    IF d.status <> 'accepted' OR d.phase <> 'AGUARDANDO_PAGAMENTO_CLIENTE' THEN
        RAISE EXCEPTION 'Esta entrega não está aguardando o pagamento do cliente' USING ERRCODE = '22023', HINT = 'wrong_phase';
    END IF;
    IF d.reservation_released_at IS NOT NULL OR d.reserved_until IS NULL THEN
        RAISE EXCEPTION 'A reserva do entregador não está mais ativa' USING ERRCODE = '22023', HINT = 'reservation_inactive';
    END IF;
    -- a reserva venceu: processa a expiração ANTES de aceitar qualquer declaração (nunca "recebi" depois de liberar o motorista)
    IF now() >= d.reserved_until THEN
        PERFORM public._v2_expire_reservation(d.id);
        RETURN jsonb_build_object('ok', false, 'expired', true);
    END IF;
    SELECT * INTO o FROM public.orders WHERE id = d.order_id;
    IF d.frozen_freight IS NULL OR o.delivery_fee IS DISTINCT FROM d.frozen_freight THEN
        RAISE EXCEPTION 'O total definitivo do pedido não confere com o frete aceito' USING ERRCODE = '22023', HINT = 'total_mismatch';
    END IF;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;
    IF v_driver IS NULL THEN RAISE EXCEPTION 'A entrega não tem entregador reservado' USING ERRCODE = '22023', HINT = 'no_driver'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.driver_payout_keys WHERE driver_id = v_driver) THEN
        RAISE EXCEPTION 'O entregador ainda não tem chave Pix cadastrada' USING ERRCODE = '22023', HINT = 'driver_pix_missing';
    END IF;
    v_method := COALESCE(NULLIF(btrim(p_method), ''), o.payment_method, 'combinar');
    IF v_method NOT IN ('pix', 'dinheiro', 'cartao', 'combinar', 'outro') THEN v_method := 'outro'; END IF;
    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;

    INSERT INTO public.delivery_payment_events (dispatch_id, order_id, store_id, ride_request_id, driver_id, kind, amount, declared_by, declared_role, metadata)
    VALUES (d.id, d.order_id, d.store_id, d.ride_request_id, v_driver, 'store_declared_customer_payment', o.total_amount, v_uid, 'store',
            jsonb_build_object('method', v_method, 'declaratory', true));
    -- a janela agora é a financeira: reinicia o relógio (e daqui em diante NÃO volta sozinho à busca)
    PERFORM set_config('app.delivery_actor', 'store', true);
    UPDATE public.order_delivery_dispatches SET phase = 'LOJA_INFORMOU_RECEBIMENTO', reserved_until = now() + make_interval(mins => cfg.reservation_timeout_minutes), updated_at = now() WHERE id = d.id;
    PERFORM set_config('app.delivery_actor', 'system', true);
    UPDATE public.order_delivery_dispatches SET phase = 'AGUARDANDO_PAGAMENTO_ENTREGADOR', updated_at = now() WHERE id = d.id;
    RETURN jsonb_build_object('ok', true, 'phase', 'AGUARDANDO_PAGAMENTO_ENTREGADOR', 'amount_received', o.total_amount);
END;
$function$;

-- @@ 50|function store_report_driver_payment(uuid,numeric)
CREATE OR REPLACE FUNCTION public.store_report_driver_payment(p_dispatch uuid, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid uuid := auth.uid();
    d public.order_delivery_dispatches;
    cfg public.delivery_dispatch_settings;
    k public.driver_payout_keys;
    v_owner uuid; v_driver uuid;
BEGIN
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE id = p_dispatch FOR UPDATE;
    IF NOT FOUND OR d.flow_version <> 2 THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    SELECT owner_id INTO v_owner FROM public.stores WHERE id = d.store_id;
    IF v_uid IS NULL OR v_owner IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501'; END IF;
    IF EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'store_declared_driver_payment') THEN
        RETURN jsonb_build_object('ok', true, 'duplicate', true, 'phase', d.phase);
    END IF;
    IF d.status <> 'accepted' OR d.phase <> 'AGUARDANDO_PAGAMENTO_ENTREGADOR'
       OR NOT EXISTS (SELECT 1 FROM public.delivery_payment_events WHERE dispatch_id = d.id AND kind = 'store_declared_customer_payment') THEN
        RAISE EXCEPTION 'Esta entrega não está aguardando o pagamento ao entregador' USING ERRCODE = '22023', HINT = 'wrong_phase';
    END IF;
    IF d.reserved_until IS NULL OR now() >= d.reserved_until THEN
        PERFORM public._v2_financial_timeout(d.id);
        RETURN jsonb_build_object('ok', false, 'expired', true, 'in_verification', true);
    END IF;
    IF p_amount IS DISTINCT FROM d.frozen_freight THEN
        RAISE EXCEPTION 'O valor a pagar ao entregador é R$ %', to_char(d.frozen_freight, 'FM999990D00') USING ERRCODE = '22023', HINT = 'amount_mismatch';
    END IF;
    SELECT driver_id INTO v_driver FROM public.ride_requests WHERE id = d.ride_request_id;
    SELECT * INTO k FROM public.driver_payout_keys WHERE driver_id = v_driver;
    IF v_driver IS NULL OR NOT FOUND THEN RAISE EXCEPTION 'O entregador não tem chave Pix cadastrada' USING ERRCODE = '22023', HINT = 'driver_pix_missing'; END IF;
    SELECT * INTO cfg FROM public.delivery_dispatch_settings WHERE id;

    INSERT INTO public.delivery_payment_events (dispatch_id, order_id, store_id, ride_request_id, driver_id, kind, amount, declared_by, declared_role, metadata)
    VALUES (d.id, d.order_id, d.store_id, d.ride_request_id, v_driver, 'store_declared_driver_payment', d.frozen_freight, v_uid, 'store',
            jsonb_build_object('pix_key_type', k.pix_key_type, 'declaratory', true));
    PERFORM set_config('app.delivery_actor', 'store', true);
    UPDATE public.order_delivery_dispatches
       SET phase = 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', reserved_until = now() + make_interval(mins => cfg.reservation_timeout_minutes), updated_at = now()
     WHERE id = d.id;
    INSERT INTO public.order_delivery_events (dispatch_id, kind, data)
    VALUES (d.id, 'reservation_notice', jsonb_build_object('reason', 'driver_payment_reported', 'driver_id', v_driver, 'amount', d.frozen_freight));
    PERFORM public._ping_delivery_events();
    RETURN jsonb_build_object('ok', true, 'phase', 'LOJA_INFORMOU_PAGAMENTO_ENTREGADOR', 'amount_declared', d.frozen_freight);
END;
$function$;

-- @@ 50|function store_uses_delivery_flow_v2(uuid)
CREATE OR REPLACE FUNCTION public.store_uses_delivery_flow_v2(p_store uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE((SELECT new_delivery_flow_enabled FROM public.delivery_dispatch_settings WHERE id), false)
       AND COALESCE((SELECT v2_enabled FROM public.store_delivery_flow WHERE store_id = p_store), false)
$function$;

-- @@ 50|function submit_service_review(uuid,integer,text,boolean,boolean)
CREATE OR REPLACE FUNCTION public.submit_service_review(p_application uuid, p_rating integer, p_comment text DEFAULT NULL::text, p_tip_received boolean DEFAULT false, p_tip_visible boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); a public.service_applications; r public.service_requests; v_reviewee uuid; v_role text; v_comment text := NULLIF(btrim(COALESCE(p_comment, '')), '');
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF;
    IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN RAISE EXCEPTION 'Escolha de 1 a 5 estrelas'; END IF;
    SELECT * INTO a FROM public.service_applications WHERE id = p_application;
    IF NOT FOUND THEN RAISE EXCEPTION 'Serviço não encontrado'; END IF;
    SELECT * INTO r FROM public.service_requests WHERE id = a.service_request_id;
    IF a.completed_at IS NULL THEN RAISE EXCEPTION 'O serviço ainda não foi marcado como feito'; END IF;
    IF v_user = r.requester_id THEN v_reviewee := a.applicant_id; v_role := 'provider';
    ELSIF v_user = a.applicant_id THEN v_reviewee := r.requester_id; v_role := 'owner';
    ELSE RAISE EXCEPTION 'Você não participou desse serviço'; END IF;

    INSERT INTO public.service_reviews (application_id, service_request_id, reviewer_id, reviewee_id, rating, comment)
    VALUES (a.id, r.id, v_user, v_reviewee, p_rating, left(v_comment, 500))
    ON CONFLICT (application_id, reviewer_id) DO NOTHING;
    IF NOT FOUND THEN RAISE EXCEPTION 'Você já avaliou esse serviço'; END IF;

    -- Gorjeta: só quem prestou o serviço registra, e só quando recebeu
    IF v_user = a.applicant_id AND COALESCE(p_tip_received, false) THEN
        INSERT INTO public.service_tips (application_id, tipper_id, receiver_id, tip_visible)
        VALUES (a.id, r.requester_id, a.applicant_id, COALESCE(p_tip_visible, false))
        ON CONFLICT (application_id) DO NOTHING;
    END IF;

    BEGIN
        PERFORM public._notify(v_reviewee, 'service_review', v_user, r.id,
            jsonb_build_object('rating', p_rating, 'snippet', left(COALESCE(v_comment, ''), 120), 'title', public._service_request_title(r.id), 'role', v_role),
            'svcrev:' || a.id || ':' || v_user);
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN true;
END; $function$;

-- @@ 50|function sync_dispatch_with_ride()
CREATE OR REPLACE FUNCTION public.sync_dispatch_with_ride()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    d public.order_delivery_dispatches;
    v_stage text;
BEGIN
    IF NEW.order_id IS NULL THEN RETURN NEW; END IF;
    SELECT * INTO d FROM public.order_delivery_dispatches WHERE ride_request_id = NEW.id;
    IF NOT FOUND THEN RETURN NEW; END IF;
    -- V2: cancelar a corrida durante a reserva não encerra a entrega por aqui; quem decide (voltar à busca ou cancelar) é a liberação da reserva
    IF d.flow_version = 2 AND NEW.status = 'cancelled' AND d.status = 'accepted' AND d.phase IN ('ENTREGADOR_RESERVADO', 'AGUARDANDO_PAGAMENTO_CLIENTE')
       AND COALESCE(current_setting('app.delivery_v2_release', true), '') <> '1' THEN
        RETURN NEW;
    END IF;

    v_stage := CASE
        WHEN NEW.status = 'cancelled' THEN 'cancelled'
        WHEN NEW.status = 'completed' THEN 'delivered'
        WHEN NEW.status = 'accepted' THEN
            CASE WHEN NEW.ride_started_at IS NOT NULL THEN 'in_transit'
                 WHEN NEW.driver_arrived_at IS NOT NULL THEN 'at_store'
                 WHEN NEW.driver_departed_at IS NOT NULL THEN 'to_store'
                 ELSE 'assigned' END
        ELSE 'searching' END;

    UPDATE public.order_delivery_dispatches
       SET stage = v_stage,
           status = CASE NEW.status WHEN 'accepted' THEN 'accepted' WHEN 'completed' THEN 'completed' WHEN 'cancelled' THEN 'cancelled' ELSE status END,
           updated_at = now()
     WHERE id = d.id;

    IF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status <> 'pending' THEN
            UPDATE public.order_delivery_rounds SET status = 'expired' WHERE status = 'pending_customer' AND dispatch_id = d.id;
            UPDATE public.order_delivery_counters SET status = 'expired', decided_at = now() WHERE status = 'pending_customer' AND dispatch_id = d.id;
        END IF;
        IF NEW.status = 'completed' THEN
            -- entregue: o pedido está finalizado
            UPDATE public.orders SET status = 'paid' WHERE id = d.order_id AND status IN ('preparing', 'ready');
            INSERT INTO public.order_delivery_events (dispatch_id, kind) VALUES (d.id, 'delivered');
            PERFORM public._ping_delivery_events();
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function sync_ride_offer()
CREATE OR REPLACE FUNCTION public.sync_ride_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    r public.ride_requests;
BEGIN
    IF TG_OP = 'DELETE' THEN
        DELETE FROM public.ride_offers WHERE id = OLD.id;
        RETURN OLD;
    END IF;
    r := NEW;
    IF r.status <> 'pending' THEN
        DELETE FROM public.ride_offers WHERE id = r.id;
        RETURN NEW;
    END IF;
    INSERT INTO public.ride_offers (id, requester_id, ride_type, origin_address, destination_address, notes, status, created_at, passenger_count, vehicle_type, origin_needs_access, origin_access_notes, destination_needs_access, destination_access_notes, has_shopping, has_extra_object, has_child, has_pet, object_description, object_is_sensitive, object_size, is_grocery_shopping, bag_count, extra_object_description, pet_description, origin_lat, origin_lng, destination_lat, destination_lng, distance_km, duration_min, child_age, child_needs_car_seat, scheduled_for, children_count, applicant_count, has_special_needs, special_needs_description, extra_object_count, pet_count, origin_complement, destination_complement, special_needs_wheelchair, special_needs_wheelchair_type, special_needs_visual_impairment, has_guide_dog, pet_weight_range, pet_has_carrier, delivery_location, payment_method, cash_change_for, grocery_bag_size, card_is_contactless, wants_air_conditioning, offered_price, order_id, store_id, stop1_address, stop1_complement, stop1_lat, stop1_lng, stop2_address, stop2_complement, stop2_lat, stop2_lng, preferred_driver_id, visible_radius_km)
    VALUES (
        r.id,
        CASE WHEN r.order_id IS NOT NULL THEN r.requester_id ELSE NULL END,
        r.ride_type,
        CASE WHEN r.order_id IS NOT NULL THEN r.origin_address ELSE COALESCE(public._address_area(r.origin_address), 'Região aproximada') END,
        COALESCE(public._address_area(r.destination_address), 'Região aproximada'),
        NULL,
        r.status,
        r.created_at,
        r.passenger_count,
        r.vehicle_type,
        r.origin_needs_access,
        NULL,
        r.destination_needs_access,
        NULL,
        r.has_shopping,
        r.has_extra_object,
        r.has_child,
        r.has_pet,
        r.object_description,
        r.object_is_sensitive,
        r.object_size,
        r.is_grocery_shopping,
        r.bag_count,
        r.extra_object_description,
        r.pet_description,
        CASE WHEN r.order_id IS NOT NULL THEN r.origin_lat ELSE round(r.origin_lat::numeric, 2)::double precision END,
        CASE WHEN r.order_id IS NOT NULL THEN r.origin_lng ELSE round(r.origin_lng::numeric, 2)::double precision END,
        round(r.destination_lat::numeric, 2)::double precision,
        round(r.destination_lng::numeric, 2)::double precision,
        r.distance_km,
        r.duration_min,
        r.child_age,
        r.child_needs_car_seat,
        r.scheduled_for,
        r.children_count,
        r.applicant_count,
        r.has_special_needs,
        NULL,
        r.extra_object_count,
        r.pet_count,
        NULL,
        NULL,
        r.special_needs_wheelchair,
        r.special_needs_wheelchair_type,
        r.special_needs_visual_impairment,
        r.has_guide_dog,
        r.pet_weight_range,
        r.pet_has_carrier,
        r.delivery_location,
        r.payment_method,
        r.cash_change_for,
        r.grocery_bag_size,
        r.card_is_contactless,
        r.wants_air_conditioning,
        r.offered_price,
        r.order_id,
        r.store_id,
        CASE WHEN r.stop1_address IS NULL THEN NULL ELSE COALESCE(public._address_area(r.stop1_address), 'Região aproximada') END,
        r.stop1_complement,
        round(r.stop1_lat::numeric, 2)::double precision,
        round(r.stop1_lng::numeric, 2)::double precision,
        CASE WHEN r.stop2_address IS NULL THEN NULL ELSE COALESCE(public._address_area(r.stop2_address), 'Região aproximada') END,
        r.stop2_complement,
        round(r.stop2_lat::numeric, 2)::double precision,
        round(r.stop2_lng::numeric, 2)::double precision,
        r.preferred_driver_id,
        r.visible_radius_km
    )
    ON CONFLICT (id) DO UPDATE SET
        requester_id = EXCLUDED.requester_id,
        ride_type = EXCLUDED.ride_type,
        origin_address = EXCLUDED.origin_address,
        destination_address = EXCLUDED.destination_address,
        notes = EXCLUDED.notes,
        status = EXCLUDED.status,
        created_at = EXCLUDED.created_at,
        passenger_count = EXCLUDED.passenger_count,
        vehicle_type = EXCLUDED.vehicle_type,
        origin_needs_access = EXCLUDED.origin_needs_access,
        origin_access_notes = EXCLUDED.origin_access_notes,
        destination_needs_access = EXCLUDED.destination_needs_access,
        destination_access_notes = EXCLUDED.destination_access_notes,
        has_shopping = EXCLUDED.has_shopping,
        has_extra_object = EXCLUDED.has_extra_object,
        has_child = EXCLUDED.has_child,
        has_pet = EXCLUDED.has_pet,
        object_description = EXCLUDED.object_description,
        object_is_sensitive = EXCLUDED.object_is_sensitive,
        object_size = EXCLUDED.object_size,
        is_grocery_shopping = EXCLUDED.is_grocery_shopping,
        bag_count = EXCLUDED.bag_count,
        extra_object_description = EXCLUDED.extra_object_description,
        pet_description = EXCLUDED.pet_description,
        origin_lat = EXCLUDED.origin_lat,
        origin_lng = EXCLUDED.origin_lng,
        destination_lat = EXCLUDED.destination_lat,
        destination_lng = EXCLUDED.destination_lng,
        distance_km = EXCLUDED.distance_km,
        duration_min = EXCLUDED.duration_min,
        child_age = EXCLUDED.child_age,
        child_needs_car_seat = EXCLUDED.child_needs_car_seat,
        scheduled_for = EXCLUDED.scheduled_for,
        children_count = EXCLUDED.children_count,
        applicant_count = EXCLUDED.applicant_count,
        has_special_needs = EXCLUDED.has_special_needs,
        special_needs_description = EXCLUDED.special_needs_description,
        extra_object_count = EXCLUDED.extra_object_count,
        pet_count = EXCLUDED.pet_count,
        origin_complement = EXCLUDED.origin_complement,
        destination_complement = EXCLUDED.destination_complement,
        special_needs_wheelchair = EXCLUDED.special_needs_wheelchair,
        special_needs_wheelchair_type = EXCLUDED.special_needs_wheelchair_type,
        special_needs_visual_impairment = EXCLUDED.special_needs_visual_impairment,
        has_guide_dog = EXCLUDED.has_guide_dog,
        pet_weight_range = EXCLUDED.pet_weight_range,
        pet_has_carrier = EXCLUDED.pet_has_carrier,
        delivery_location = EXCLUDED.delivery_location,
        payment_method = EXCLUDED.payment_method,
        cash_change_for = EXCLUDED.cash_change_for,
        grocery_bag_size = EXCLUDED.grocery_bag_size,
        card_is_contactless = EXCLUDED.card_is_contactless,
        wants_air_conditioning = EXCLUDED.wants_air_conditioning,
        offered_price = EXCLUDED.offered_price,
        order_id = EXCLUDED.order_id,
        store_id = EXCLUDED.store_id,
        stop1_address = EXCLUDED.stop1_address,
        stop1_complement = EXCLUDED.stop1_complement,
        stop1_lat = EXCLUDED.stop1_lat,
        stop1_lng = EXCLUDED.stop1_lng,
        stop2_address = EXCLUDED.stop2_address,
        stop2_complement = EXCLUDED.stop2_complement,
        stop2_lat = EXCLUDED.stop2_lat,
