-- @@ 50|function sync_store_coordinates()
CREATE OR REPLACE FUNCTION public.sync_store_coordinates()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.location IS NOT NULL THEN
        NEW.store_lat := ST_Y(NEW.location::geometry);
        NEW.store_lng := ST_X(NEW.location::geometry);
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function touch_last_seen(boolean)
CREATE OR REPLACE FUNCTION public.touch_last_seen(p_online boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_mode text;
BEGIN
    IF auth.uid() IS NULL THEN RETURN; END IF;
    INSERT INTO public.profile_presence (profile_id) VALUES (auth.uid()) ON CONFLICT (profile_id) DO NOTHING;
    SELECT mode INTO v_mode FROM public.profile_presence WHERE profile_id = auth.uid();

    IF v_mode = 'offline' THEN
        UPDATE public.profile_presence SET online = false WHERE profile_id = auth.uid() AND online;
        RETURN;                                       -- invisível: não registra que esteve online
    END IF;
    IF v_mode = 'online' THEN p_online := true; END IF;   -- "sempre online" ignora o aviso de saída

    UPDATE public.profile_presence
       SET last_seen_at = now(), online = p_online
     WHERE profile_id = auth.uid()
       AND (online IS DISTINCT FROM p_online OR last_seen_at IS NULL OR last_seen_at < now() - interval '45 seconds');
END; $function$;

-- @@ 50|function track_link_visit(text,text,text)
CREATE OR REPLACE FUNCTION public.track_link_visit(p_slug text, p_path text, p_anon text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_visitor text := COALESCE(auth.uid()::text, 'anon:' || COALESCE(left(p_anon, 60), 'x'));
BEGIN
    SELECT id INTO v_id FROM public.profiles WHERE "profileSlug" = lower(btrim(p_slug));
    IF v_id IS NULL THEN RETURN; END IF;
    -- A página do próprio perfil já gera "visitou seu perfil"
    IF p_path = '/' || lower(btrim(p_slug)) THEN RETURN; END IF;
    PERFORM public._notify(v_id, 'link_visit', auth.uid(), NULL, jsonb_build_object('path', left(COALESCE(p_path, ''), 200)),
        'link:' || v_visitor || ':' || left(COALESCE(p_path, ''), 120) || ':' || to_char(now() AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD'));
END; $function$;

-- @@ 50|function track_service_request_view(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.track_service_request_view(p_request_id uuid, p_anonymous_id uuid DEFAULT NULL::uuid, p_device_type text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid UUID := auth.uid();
    v_owner UUID;
    v_recent BOOLEAN;
BEGIN
    SELECT requester_id INTO v_owner FROM public.service_requests WHERE id = p_request_id;
    IF NOT FOUND OR v_owner = v_uid THEN
        RETURN FALSE;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.service_request_visits
        WHERE service_request_id = p_request_id
          AND created_at > now() - interval '30 minutes'
          AND (
              (v_uid IS NOT NULL AND viewer_id = v_uid)
              OR (v_uid IS NULL AND p_anonymous_id IS NOT NULL AND anonymous_id = p_anonymous_id)
          )
    ) INTO v_recent;
    IF v_recent THEN
        RETURN FALSE;
    END IF;

    INSERT INTO public.service_request_visits (service_request_id, viewer_id, anonymous_id, device_type)
    VALUES (p_request_id, v_uid, p_anonymous_id, p_device_type);

    UPDATE public.service_requests SET view_count = view_count + 1 WHERE id = p_request_id;
    RETURN TRUE;
END;
$function$;

-- @@ 50|function track_service_usage(text,text,integer)
CREATE OR REPLACE FUNCTION public.track_service_usage(p_service text, p_metric text, p_count integer DEFAULT 1)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    INSERT INTO public.service_usage_telemetry_daily (day, service, metric, count, updated_at)
    VALUES (current_date, p_service, p_metric, p_count, now())
    ON CONFLICT (day, service, metric)
    DO UPDATE SET count = service_usage_telemetry_daily.count + p_count, updated_at = now();
END;
$function$;

-- @@ 50|function track_usage(bigint,bigint)
CREATE OR REPLACE FUNCTION public.track_usage(p_egress_bytes bigint DEFAULT 0, p_realtime_messages bigint DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    insert into public.usage_telemetry_daily (day, egress_bytes, realtime_messages)
    values (current_date, greatest(p_egress_bytes, 0), greatest(p_realtime_messages, 0))
    on conflict (day) do update set
        egress_bytes = usage_telemetry_daily.egress_bytes + excluded.egress_bytes,
        realtime_messages = usage_telemetry_daily.realtime_messages + excluded.realtime_messages,
        updated_at = now();
end;
$function$;

-- @@ 50|function trg_community_message_edit()
CREATE OR REPLACE FUNCTION public.trg_community_message_edit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.profile_id := OLD.profile_id;
    NEW.community_id := OLD.community_id;
    NEW.created_at := OLD.created_at;
    IF btrim(COALESCE(NEW.content, '')) = '' THEN RAISE EXCEPTION 'A mensagem não pode ficar vazia'; END IF;
    IF NEW.content IS DISTINCT FROM OLD.content THEN NEW.edited_at := now(); END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function trg_direct_message_after_insert()
CREATE OR REPLACE FUNCTION public.trg_direct_message_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c public.conversations;
BEGIN
    SELECT * INTO c FROM public.conversations WHERE id = NEW.conversation_id;
    IF c.kind = 'group' THEN
        UPDATE public.conversations SET
            last_message_at = NEW.created_at, last_message = left(NEW.content, 140), last_sender_id = NEW.sender_id
        WHERE id = NEW.conversation_id;
        UPDATE public.conversation_members SET last_read_at = NEW.created_at
        WHERE conversation_id = NEW.conversation_id AND profile_id = NEW.sender_id;
    ELSE
        UPDATE public.conversations SET
            last_message_at = NEW.created_at,
            last_message = left(NEW.content, 140),
            last_sender_id = NEW.sender_id,
            customer_read_at = CASE WHEN NEW.sender_id = c.customer_id THEN NEW.created_at ELSE customer_read_at END,
            owner_read_at = CASE WHEN NEW.sender_id <> c.customer_id THEN NEW.created_at ELSE owner_read_at END
        WHERE id = NEW.conversation_id;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function trg_network_levels_cap()
CREATE OR REPLACE FUNCTION public.trg_network_levels_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_max integer;
BEGIN
    SELECT max_commission_bp INTO v_max FROM public.network_settings WHERE id;
    IF NEW.commission_prepaid_bp > v_max OR NEW.commission_postpaid_bp > v_max THEN
        RAISE EXCEPTION 'A comissão de um nível não pode passar de % %% (teto do sistema).', round(v_max / 100.0, 2);
    END IF;
    NEW.updated_at := now();
    RETURN NEW;
END $function$;

-- @@ 50|function trg_notify_appointment()
CREATE OR REPLACE FUNCTION public.trg_notify_appointment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_actor uuid := auth.uid();
    v_creator uuid;
    v_other uuid;
    v_meta jsonb;
    v_p uuid;
BEGIN
    -- Compromisso pessoal (dono = cliente) e o espelho do remetente: ninguém a avisar
    IF NEW.owner_id IS NOT DISTINCT FROM NEW.customer_id THEN RETURN NEW; END IF;

    -- Quem criou: 'outgoing' = o cliente (pediu horário); o resto = o dono (convidou)
    IF NEW.direction = 'outgoing' THEN v_creator := NEW.customer_id; v_other := NEW.owner_id;
    ELSE v_creator := NEW.owner_id; v_other := NEW.customer_id; END IF;

    v_meta := jsonb_build_object(
        'title', NEW.service_name, 'store', NEW.store_name, 'store_id', NEW.store_id,
        'date', NEW.date, 'time', left(NEW.time::text, 5),
        'flow', CASE WHEN NEW.direction = 'outgoing' THEN 'booking' ELSE 'invite' END
    );

    IF TG_OP = 'INSERT' THEN
        PERFORM public._notify(v_other, 'appointment_new', v_creator, NEW.id, v_meta, 'appt:' || NEW.id || ':new');

    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status = 'confirmed' THEN
            -- quem estava esperando a resposta (o criador) é avisado; o ator é quem confirmou
            PERFORM public._notify(v_creator, 'appointment_confirmed', COALESCE(v_actor, v_other), NEW.id, v_meta, 'appt:' || NEW.id || ':confirmed');
        ELSIF NEW.status = 'cancelled' THEN
            FOREACH v_p IN ARRAY ARRAY[NEW.owner_id, NEW.customer_id] LOOP
                PERFORM public._notify(v_p, 'appointment_cancelled', v_actor, NEW.id, v_meta, 'appt:' || NEW.id || ':cancelled');
            END LOOP;
        END IF;

    ELSIF (NEW.date IS DISTINCT FROM OLD.date OR NEW.time IS DISTINCT FROM OLD.time) AND NEW.status <> 'cancelled' THEN
        FOREACH v_p IN ARRAY ARRAY[NEW.owner_id, NEW.customer_id] LOOP
            PERFORM public._notify(v_p, 'appointment_changed', v_actor, NEW.id, v_meta,
                'appt:' || NEW.id || ':changed:' || NEW.date || ':' || left(NEW.time::text, 5));
        END LOOP;
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function trg_notify_comment()
CREATE OR REPLACE FUNCTION public.trg_notify_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p public.products; v_owner uuid; v_slug text; par public.comments; v_snip text := left(NEW.content, 140);
BEGIN
    IF NEW.publication_id IS NOT NULL THEN
        SELECT * INTO p FROM public.products WHERE id = NEW.publication_id;
        IF FOUND THEN
            IF p.store_id IS NOT NULL THEN
                SELECT s.owner_id, s."storeSlug" INTO v_owner, v_slug FROM public.stores s WHERE s.id = p.store_id;
            ELSE
                v_owner := p.owner_id;
                SELECT "profileSlug" INTO v_slug FROM public.profiles WHERE id = p.owner_id;
            END IF;
        END IF;
    END IF;

    IF NEW.parent_comment_id IS NOT NULL THEN
        SELECT * INTO par FROM public.comments WHERE id = NEW.parent_comment_id;
        IF FOUND THEN
            PERFORM public._notify(par.profile_id, 'comment_reply', NEW.profile_id, NEW.id,
                jsonb_build_object('snippet', v_snip, 'title', p.name, 'slug', p.slug, 'owner_slug', v_slug), 'reply:' || NEW.id);
        END IF;
    ELSIF NEW.publication_id IS NOT NULL THEN
        PERFORM public._notify(v_owner, 'publication_comment', NEW.profile_id, NEW.id,
            jsonb_build_object('snippet', v_snip, 'title', p.name, 'slug', p.slug, 'owner_slug', v_slug), 'comment:' || NEW.id);
    ELSIF NEW.profile_target_id IS NOT NULL THEN
        PERFORM public._notify(NEW.profile_target_id, 'profile_comment', NEW.profile_id, NEW.id,
            jsonb_build_object('snippet', v_snip), 'comment:' || NEW.id);
    END IF;
    RETURN NEW;
END; $function$;

-- @@ 50|function trg_notify_comment_like()
CREATE OR REPLACE FUNCTION public.trg_notify_comment_like()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c public.comments; p public.products; v_slug text;
BEGIN
    SELECT * INTO c FROM public.comments WHERE id = NEW.comment_id;
    IF NOT FOUND THEN RETURN NEW; END IF;
    IF c.publication_id IS NOT NULL THEN
        SELECT * INTO p FROM public.products WHERE id = c.publication_id;
        IF p.store_id IS NOT NULL THEN SELECT "storeSlug" INTO v_slug FROM public.stores WHERE id = p.store_id;
        ELSE SELECT "profileSlug" INTO v_slug FROM public.profiles WHERE id = p.owner_id; END IF;
    END IF;
    PERFORM public._notify(c.profile_id, 'comment_like', NEW.profile_id, c.id,
        jsonb_build_object('snippet', left(c.content, 140), 'title', p.name, 'slug', p.slug, 'owner_slug', v_slug),
        'clike:' || NEW.profile_id || ':' || c.id);
    RETURN NEW;
END; $function$;

