-- @@ 50|function update_cascade_levels(uuid)
CREATE OR REPLACE FUNCTION public.update_cascade_levels(upline_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_user RECORD;
BEGIN
    FOR v_user IN 
        WITH RECURSIVE downline_tree AS (
            SELECT id, 1 as level
            FROM public.profiles
            WHERE upline_id = upline_id
            UNION ALL
            SELECT p.id, d.level + 1
            FROM public.profiles p
            INNER JOIN downline_tree d ON p.upline_id = d.id
        )
        SELECT * FROM downline_tree
    LOOP
        UPDATE public.profiles
        SET level = v_user.level
        WHERE id = v_user.id;
    END LOOP;
END;
$function$;

