-- @@ 50|function update_group(uuid,text)
CREATE OR REPLACE FUNCTION public.update_group(p_conv uuid, p_title text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); v_title text := btrim(COALESCE(p_title, ''));
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.conversation_members WHERE conversation_id = p_conv AND profile_id = v_user AND status = 'active' AND role = 'admin') THEN
        RAISE EXCEPTION 'Só quem administra o grupo pode mudar o nome';
    END IF;
    IF char_length(v_title) < 1 OR char_length(v_title) > 60 THEN RAISE EXCEPTION 'Dê um nome ao grupo (até 60 letras)'; END IF;
    UPDATE public.conversations SET title = v_title WHERE id = p_conv AND kind = 'group';
END; $function$;

-- @@ 50|function update_live_location(double precision,double precision)
CREATE OR REPLACE FUNCTION public.update_live_location(p_lat double precision, p_lng double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF auth.uid() IS NULL OR p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND live_location) THEN RETURN; END IF;
    INSERT INTO public.profile_live_location (profile_id, lat, lng, updated_at) VALUES (auth.uid(), p_lat, p_lng, now())
    ON CONFLICT (profile_id) DO UPDATE SET lat = EXCLUDED.lat, lng = EXCLUDED.lng, updated_at = now();
END; $function$;

