-- @@ 50|function update_product_rating_stats()
CREATE OR REPLACE FUNCTION public.update_product_rating_stats()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE public.products
    SET 
        ratings_avg = (
            SELECT COALESCE(AVG(rating), 0)::NUMERIC(3,2) 
            FROM public.product_ratings 
            WHERE product_id = COALESCE(NEW.product_id, OLD.product_id)
        ),
        ratings_count = (
            SELECT COUNT(*) 
            FROM public.product_ratings 
            WHERE product_id = COALESCE(NEW.product_id, OLD.product_id)
        )
    WHERE id = COALESCE(NEW.product_id, OLD.product_id);
    RETURN NULL;
END;
$function$;

-- @@ 50|function update_profile_location(uuid,double precision,double precision,text)
CREATE OR REPLACE FUNCTION public.update_profile_location(profile_id uuid, lat double precision, lng double precision, addr text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  UPDATE public.profiles
  SET 
    location = ST_SetSRID(ST_MakePoint(lng, lat), 4326),
    address = addr,
    store_lat = lat,
    store_lng = lng
  WHERE id = profile_id;
END;
$function$;

-- @@ 50|function update_profile_rating()
CREATE OR REPLACE FUNCTION public.update_profile_rating()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin

    update public.profiles
    set
        rating_avg = coalesce((
            select round(avg(rating)::numeric, 2)
            from public.profile_reviews
            where profile_id = coalesce(new.profile_id, old.profile_id)
        ), 0),

        rating_count = (
            select count(*)
            from public.profile_reviews
            where profile_id = coalesce(new.profile_id, old.profile_id)
        )

    where id = coalesce(new.profile_id, old.profile_id);

    return null;

end;
$function$;

-- @@ 50|function update_profile_stats()
CREATE OR REPLACE FUNCTION public.update_profile_stats()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE profile_stats 
        SET followers_count = followers_count + 1,
            last_updated = NOW()
        WHERE profile_id = NEW.following_id;
        
        UPDATE profile_stats 
        SET following_count = following_count + 1,
            last_updated = NOW()
        WHERE profile_id = NEW.follower_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE profile_stats 
        SET followers_count = followers_count - 1,
            last_updated = NOW()
        WHERE profile_id = OLD.following_id;
        
        UPDATE profile_stats 
        SET following_count = following_count - 1,
            last_updated = NOW()
        WHERE profile_id = OLD.follower_id;
    END IF;
    RETURN NULL;
END;
$function$;

-- @@ 50|function update_store_rating()
CREATE OR REPLACE FUNCTION public.update_store_rating()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE stores
  SET
    ratings_avg = (
      SELECT COALESCE(AVG(rating), 0)
      FROM reviews
      WHERE store_id = NEW.store_id
    ),
    ratings_count = (
      SELECT COUNT(*)
      FROM reviews
      WHERE store_id = NEW.store_id
    )
  WHERE id = NEW.store_id;

  RETURN NEW;
END;
$function$;

-- @@ 50|function update_store_rating_stats()
CREATE OR REPLACE FUNCTION public.update_store_rating_stats()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE public.stores
    SET 
        ratings_avg = (
            SELECT COALESCE(AVG(rating), 0)::NUMERIC(3,2) 
            FROM public.store_ratings 
            WHERE store_id = COALESCE(NEW.store_id, OLD.store_id)
        ),
        ratings_count = (
            SELECT COUNT(*) 
            FROM public.store_ratings 
            WHERE store_id = COALESCE(NEW.store_id, OLD.store_id)
        )
    WHERE id = COALESCE(NEW.store_id, OLD.store_id);
    RETURN NULL;
END;
$function$;

-- @@ 50|function update_store_ratings_stats()
CREATE OR REPLACE FUNCTION public.update_store_ratings_stats()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  WITH stats AS (
    SELECT 
      AVG(rating) as avg_rating,
      COUNT(*) as count_rating
    FROM store_ratings
    WHERE store_id = COALESCE(NEW.store_id, OLD.store_id)
  )
  UPDATE stores
  SET 
    ratings_avg = stats.avg_rating,
    ratings_count = stats.count_rating
  FROM stats
  WHERE stores.id = COALESCE(NEW.store_id, OLD.store_id);
  RETURN NULL;
END;
$function$;

