$function$;

-- @@ 50|function validate_campaign_code(text)
CREATE OR REPLACE FUNCTION public.validate_campaign_code(p_code text)
 RETURNS TABLE(redemption_id uuid, store_id uuid, discount_type text, discount_value numeric, product_ids uuid[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_redemption public.store_campaign_redemptions;
    v_campaign public.store_campaigns;
BEGIN
    SELECT * INTO v_redemption FROM public.store_campaign_redemptions WHERE code = upper(trim(p_code));
    IF NOT FOUND OR v_redemption.status != 'available' THEN
        RAISE EXCEPTION 'Código inválido ou já usado';
    END IF;

    SELECT * INTO v_campaign FROM public.store_campaigns WHERE id = v_redemption.campaign_id;
    IF NOT FOUND OR NOT v_campaign.active OR (v_campaign.ends_at IS NOT NULL AND v_campaign.ends_at <= now()) THEN
        RAISE EXCEPTION 'Código inválido ou já usado';
    END IF;

    RETURN QUERY SELECT v_redemption.id, v_campaign.store_id, v_campaign.discount_type, v_campaign.discount_value, v_campaign.product_ids;
END;
$function$;

-- @@ 50|function validate_ride_order_link()
CREATE OR REPLACE FUNCTION public.validate_ride_order_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_store uuid;
BEGIN
    IF NEW.order_id IS NOT NULL THEN
        SELECT store_id INTO v_store FROM public.orders WHERE id = NEW.order_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Pedido da corrida não existe'; END IF;
        IF NEW.store_id IS DISTINCT FROM v_store THEN RAISE EXCEPTION 'A loja da corrida não é a loja do pedido'; END IF;
    END IF;
    RETURN NEW;
END;
$function$;

-- @@ 50|function vincular_upline(uuid,uuid)
CREATE OR REPLACE FUNCTION public.vincular_upline(p_user_id uuid, p_upline_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Atualizar o upline_id do usuário
    UPDATE profiles 
    SET upline_id = p_upline_id
    WHERE id = p_user_id;
    
    RETURN TRUE;
END;
$function$;

-- @@ 50|function vote_community_photo(uuid)
CREATE OR REPLACE FUNCTION public.vote_community_photo(p_candidate uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user uuid := auth.uid(); cand public.community_photo_candidates; v_today date;
BEGIN
    IF v_user IS NULL THEN RAISE EXCEPTION 'Entre na sua conta pra votar'; END IF;
    SELECT * INTO cand FROM public.community_photo_candidates WHERE id = p_candidate;
    IF NOT FOUND THEN RAISE EXCEPTION 'Foto não encontrada'; END IF;
    IF NOT public._community_is_member(cand.community_id, v_user) THEN RAISE EXCEPTION 'Entre na comunidade primeiro'; END IF;
    v_today := public._community_today(cand.community_id);
    IF cand.round_day <> v_today OR cand.outcome IS NOT NULL THEN RAISE EXCEPTION 'Essa votação já terminou'; END IF;
    INSERT INTO public.community_photo_votes (community_id, round_day, voter_id, candidate_id)
    VALUES (cand.community_id, cand.round_day, v_user, cand.id)
    ON CONFLICT (community_id, round_day, voter_id) DO UPDATE SET candidate_id = EXCLUDED.candidate_id, created_at = now();
    RETURN true;
END; $function$;

-- @@ 50|function wallet_block_negative_balance()
CREATE OR REPLACE FUNCTION public.wallet_block_negative_balance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.amount < 0 AND
       (SELECT COALESCE(SUM(amount), 0) FROM public.wallet_transactions WHERE user_id = NEW.user_id) + NEW.amount < 0 THEN
        RAISE EXCEPTION 'Saldo insuficiente';
    END IF;
    RETURN NEW;
END; $function$;

