-- @@ 100|view flash_posts_with_stores
CREATE OR REPLACE VIEW public."flash_posts_with_stores" AS SELECT fp.id,
    fp.store_id,
    fp.product_id,
    fp.type,
    fp.title,
    fp.content,
    fp.old_price,
    fp.new_price,
    fp.image_url,
    fp.created_at,
    s.name AS store_name,
    s."storeSlug",
    s.logo_url AS store_logo,
    p.name AS product_name,
    p.slug AS product_slug,
    prof."profileSlug"
   FROM flash_posts fp
     JOIN stores s ON fp.store_id = s.id
     LEFT JOIN products p ON fp.product_id = p.id
     JOIN profiles prof ON s.owner_id = prof.id;

